  ui_story_5053_50530101_27_dialog_content = "조슈아는 줄곧 건강했고, 몸이 불편함을 호소하는 일은 드물었다.\n특히 오늘 같은 특별한 날이라면 더욱 그러했지.",
  ui_story_5053_50530101_28_dialog_content = "공작부인께서는 최근 각 귀족 부인들에게 성주님의 정책을 전파하려고\n심혈을 기울여 오셨습니다.",
  ui_story_5053_50530101_29_dialog_content = "...어쩔 수 없지.",
  ui_story_5053_50530101_30_dialog_content = "미즈 로트, 그대는 남아서 조슈아를 돌보도록.\n무슨 일이 있으면 즉시 내게 보고해라.",
  ui_story_5053_50530101_31_dialog_content = "네. 성주 전하.",
  ui_story_5053_50530101_32_dialog_content = "저건... 젊은 성주님이잖아요? 어째서...?! 그럼 설마...",
  ui_story_5053_50530101_33_dialog_content = "우린 아직 수정 속에서 나가지 못한 것이다.",
  ui_story_5053_50530101_34_dialog_content = "아버님...",
  ui_story_5053_50530101_35_dialog_content = "...아버님? 그리고... PlayerName.",
  ui_story_5053_50530101_36_dialog_content = "우리... 지, 지금 현실 세계로 돌아온 건가요?",
  ui_story_5053_50530101_37_dialog_content = "이곳은 원래의 세계가 아니다.",
  ui_story_5053_50530101_38_dialog_content = "네? 하지만 기록된 하루가 끝날 때까지 못 나가면...",
  ui_story_5053_50530101_39_dialog_content = "...그럼 이제 다들 영원히 「영원한 기억의 수정」 속에 갇혀버린 건가요?",
  ui_story_5053_50530101_40_dialog_content = "나도 잘 모르겠어... 쟈키니한테 물어볼 수밖에 없겠네.",
  ui_story_5053_50530101_41_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5053_50530101_42_dialog_content = "쟈키니!",
  ui_story_5053_50530101_43_dialog_content = "위스퍼... 깨우지 마... 조금만 더 잘래...",
  ui_story_5053_50530101_44_dialog_content = "쟈키니, 나야! PlayerName! 빨리 일어나! 긴급 상황이라고!",
  ui_story_5053_50530101_45_dialog_content = "어? 뭐야, PlayerName 씨였어요? 하아암──",
  ui_story_5053_50530101_46_dialog_content = "어라? 여긴...",
  ui_story_5053_50530101_47_dialog_content = "쉿!",
  ui_story_5053_50530101_48_dialog_content = "방금 소리 들었지?",
  ui_story_5053_50530101_49_dialog_content = "그래, 수풀 쪽에서 무슨 소리가 난 것 같은데?",
  ui_story_5053_50530101_50_dialog_content = "가서 확인해 보자고.",
  ui_story_5053_50530101_51_dialog_content = "뀨...?",
  ui_story_5053_50530101_52_dialog_content = "뭐야, 그냥 토끼였잖아.",
  ui_story_5053_50530101_53_dialog_content = "<size=50>뀨── 뀨우!</size>",
  ui_story_5053_50530101_54_dialog_content = "깜짝 놀랐네. 원래 토끼도 소리를 내서 울 수 있는 거였나?",
  ui_story_5053_50530101_55_dialog_content = "됐어, 토끼 한 마리가 뭐 대수라고. 순찰이나 마저 하자고.",
  ui_story_5053_50530101_56_dialog_content = "위험했어...",
  ui_story_5053_50530101_57_dialog_content = "다행이에요! 제가 마침 딱 재치 있게 칼렙 씨를 토끼로 변신시켜서 속였네요!",
  ui_story_5053_50530101_58_dialog_content = "뀨뀨뀨뀨!",
  ui_story_5053_50530101_59_dialog_content = "잠깐만요, 근데 우리 왜 숨는 건데요?",
  ui_story_5053_50530101_60_dialog_content = "쟈키니, 우리는 아직 「영원한 기억의 수정」 속 세계에 있다.",
  ui_story_5053_50530101_61_dialog_content = "네?! 그럴 리가 없잖아요! 주문도 맞았고, 방법도... 어... 문제없었는데요?!",
  ui_story_5053_50530101_62_dialog_content = "그러니까 그때...",
  ui_story_5053_50530101_63_dialog_content = "열두 시 종이 울리기 시작했고, 우린 이미 하루의 끝을 맞이하고 있었어요.",
  ui_story_5053_50530101_64_dialog_content = "수정 속 세계에서 나가려면 <color=#FFB400>시간을 되돌리는 주문</color>과\n<color=#FFB400>「영원한 기억의 수정」에서 나가는 주문</color>을 동시에 외워야 해요.",
  ui_story_5053_50530101_65_dialog_content = "근데 방금 미즈 로트가 젊은 성주님이랑 카렌을 배웅했잖아?\n그럼 그건 그러니까...",
  ui_story_5053_50530101_66_dialog_content = "<color=#FFB400>「영원한 기억의 수정」에서 나가는 주문</color>은 발동하지 않았고,\n<color=#FFB400>시간을 되돌리는 주문</color>만 발동한 걸까요?",
  ui_story_5053_50530101_67_dialog_content = "혹시 그 괴물의 영향을 받은 건 아니겠지...?",
  ui_story_5053_50530101_68_dialog_content = "아, 생각났어요! 그 괴물... 지금 생각해도 정말 소름 끼친다니까요!",
  ui_story_5053_50530101_69_dialog_content = "머리엔 날개가 잔뜩 나 있고... 정말 무서웠어요.",
  ui_story_5053_50530101_70_dialog_content = "마치...",
  ui_story_5053_50530101_71_dialog_content = "마치 이 세상에 절망을 선사하기 위해 온 검은 천사처럼 말이야.",
  ui_story_5053_50530101_72_dialog_content = "맞아요! <color=#FFB400>「검은 천사」</color>!",
  ui_story_5053_50530101_73_dialog_content = "휴, 아무튼 지금 중요한 건 그게 아니에요.\n지금 바로 여기서 나가는 주문을 외워서 여러분을 내보내 드릴게요!",
  ui_story_5053_50530101_74_dialog_content = "저기...",
  ui_story_5053_50530101_75_dialog_content = "뀨뀨뀨!",
  ui_story_5053_50530101_76_dialog_content = "먼저 외삼촌부터 원래대로 돌려줄 수 있을까?",
  ui_story_5053_50530101_77_dialog_content = "아~ 까먹을 뻔했네요!",
  ui_story_5053_50530101_78_dialog_content = "「무타티오~ 무타티오~ 무타티오!」",
  ui_story_5053_50530101_79_dialog_content = "칼렙 씨를 원래 모습으로 돌려주세요!",
  ui_story_5053_50530101_80_dialog_content = "「아브라카다브라!」",
  ui_story_5053_50530101_81_dialog_content = "<color=#e8d9bb>퍼엉!</color>",
  ui_story_5053_50530101_82_dialog_content = "......",
  ui_story_5053_50530101_83_dialog_content = "「영원한 기억의 수정」의 틈은... 거인국이었단 말인가...",
  ui_story_5053_50530101_84_dialog_content = "아...? 거인국이... 사라졌어?",
  ui_story_5053_50530101_85_dialog_content = "칼렙 씨, 다시 돌아온 걸 환영해요!",
  ui_story_5053_50530101_86_dialog_content = "돌아와...?",
  ui_story_5053_50530101_87_dialog_content = "제가 돌아왔다고요?! 하지만 아직 누나의...\n...빌어먹을!",
  ui_story_5053_50530101_88_dialog_content = "네? 그게 무슨 소리예요?",
  ui_story_5053_50530101_89_dialog_content = "...칼렙 씨, 저 사실 처음부터 이상하다고 생각했어요.",
  ui_story_5053_50530101_90_dialog_content = "멋대로 혼자 움직이질 않나, 가서 「영원한 기억의 수정」을 훔치질 않나...\n대체 뭘 하려던 거예요?",
  ui_story_5053_50530101_91_dialog_content = "<color=#e8d9bb>위잉──</color>",
  ui_story_5053_50530101_92_dialog_content = "뭐죠? 설마 경비병한테 들킨 걸까요?!",
  ui_story_5053_50530101_93_dialog_content = "쟈키니, 무기를 들어...",
  ui_story_5053_50530101_94_dialog_content = "「검은 천사」가 또 나타났어!",
  ui_story_5053_50530101_95_dialog_content = "거기... 있었니?",
  ui_story_5053_50530102_1_dialog_content = "거기... 있었니?",
  ui_story_5053_50530102_2_dialog_content = "「수정이여!」",
  ui_story_5053_50530102_3_dialog_content = "「검은 천사」가 어떻게 쫓아온 거죠?! 우린 시간을 돌렸잖아요!",
  ui_story_5053_50530102_4_dialog_content = "누, 누나 목소리야...",
  ui_story_5053_50530102_5_dialog_content = "여기... 있었구나!",
  ui_story_5053_50530102_6_dialog_content = "「백야! 비호를!」",
  ui_story_5053_50530102_7_dialog_content = "칼렙, 전장에서 쓸데없는 생각은 금물이다!",
  ui_story_5053_50530102_8_dialog_content = "당신이 절 가르칠 필요는 없어요!\n지금 이건 대체...",
  ui_story_5053_50530102_9_dialog_content = "침입자여, 무기를 버려라!",
  ui_story_5053_50530102_10_dialog_content = "감히 성주님의 저택에 침입해 행패를 부리다니, 대단한 배짱이군!",
  ui_story_5053_50530102_11_dialog_content = "──!",
  ui_story_5053_50530102_12_dialog_content = "괴, 괴물인가?! 저게 대체 뭐야?!",
  ui_story_5053_50530102_13_dialog_content = "당장 지원을 요청해!",
  ui_story_5053_50530102_14_dialog_content = "아, 알겠어...",
  ui_story_5053_50530102_15_dialog_content = "다...니엘...!",
  ui_story_5053_50530102_16_dialog_content = "......",
  ui_story_5053_50530102_17_dialog_content = "어, 어째서... 「검은 천사」가 아버님만 노리는 거야?",
  ui_story_5053_50530102_18_dialog_content = "게다가 「검은 천사」가 계속 우리 쪽 몇몇 이름을 부르고 있어.\n설마 아는 사이인 거야?",
  ui_story_5053_50530102_19_dialog_content = "난 전혀 모르는걸...",
  ui_story_5053_50530102_20_dialog_content = "──!",
  ui_story_5053_50530102_21_dialog_content = "「지배자의 칼날!」",
  ui_story_5053_50530102_22_dialog_content = "으윽...",
  ui_story_5053_50530102_23_dialog_content = "지금 그대의 힘, 처음 싸울 때보다는 뒤떨어지는군.",
  ui_story_5053_50530102_24_dialog_content = "하아──!",
  ui_story_5053_50530102_25_dialog_content = "...허나 변함없이 끈질기다.",
  ui_story_5053_50530102_26_dialog_content = "제가 지휘할게요! 감응 능력은 많이 약해졌지만, 전투 보조라면 문제없어요!",
  ui_story_5053_50530102_27_dialog_content = "호의에는 감사하지. 허나 이미 그 역할을 맡을 자가 있다.",
  ui_story_5053_50530102_28_dialog_content = "미아, 이 국면을 어찌 타개할지 알고 있느냐.",
  ui_story_5053_50530102_29_dialog_content = "저, 저요?! 제가 지휘를 하나요...?",
  ui_story_5053_50530102_30_dialog_content = "긴장하지 마라. 나를 네 수중의 체스말로 여겨라.",
  ui_story_5053_50530102_31_dialog_content = "자, 이제 날 어디에 둘 것이냐.",
  ui_story_5053_50530102_32_dialog_content = "음... 아버님은 이대로 「검은 천사」를 유인해서 앞쪽으로 가고...\n제가 후방에서 함께 공격하는 건 어떨까요?",
  ui_story_5053_50530102_33_dialog_content = "부족하다!",
  ui_story_5053_50530102_34_dialog_content = "그, 그럼...",
  ui_story_5053_50530102_35_dialog_content = "네가 쥔 체스말은 나 혼자가 아니지 않느냐!",
  ui_story_5053_50530102_36_dialog_content = "죄송해요... 잘 모르겠어요...",
  ui_story_5053_50530102_37_dialog_content = "미아, 긴장하지 마. 넌 할 수 있어!",
  ui_story_5053_50530102_38_dialog_content = "PlayerName...",
  ui_story_5053_50530102_39_dialog_content = "(이건 기사단 훈련이랑 똑같아. 아버님은 나한테 싸움을 가르쳐 주시려는 걸까?)",
  ui_story_5053_50530102_40_dialog_content = "(그렇다면 아버님을 실망시킬 순 없어... 아니, 기사의 명예를 저버릴 순 없어!)",
  ui_story_5053_50530102_41_dialog_content = "...이제 알겠어요.",
  ui_story_5053_50530102_42_dialog_content = "아버님이 「검은 천사」를 끌어당기는 틈에...\n쟈키니는 여기서, 외삼촌은 반대쪽에서 협공해요.",
  ui_story_5053_50530102_43_dialog_content = "삼각형의 진형으로 「검은 천사」를 포위 공격하면... 쓰러트릴 수 있지 않을까요?",
  ui_story_5053_50530102_44_dialog_content = "헤에, 멋진 작전이네요! 알겠어요~!",
  ui_story_5053_50530102_45_dialog_content = "나쁘지 않은 전술입니다. 그렇게 갑시다.",
  ui_story_5053_50530102_46_dialog_content = "여기... 있었구나...",
  ui_story_5053_50530102_47_dialog_content = "그대는 대체 누구냐, 무엇 때문에 우리를 쫓는 것이냐.",
  ui_story_5053_50530102_48_dialog_content = "다...니엘...!!!",
  ui_story_5053_50530102_49_dialog_content = "(「검은 천사」의 움직임이 갑자기 느려졌잖아? 하지만 지금이 공격의 기회야!)",
  ui_story_5053_50530102_50_dialog_content = "지금이에요, 다 같이 공격해요!",
  ui_story_5053_50530102_51_dialog_content = "미안하게 됐습니다...!",
  ui_story_5053_50530102_52_dialog_content = "「수정이여!」",
  ui_story_5053_50530102_53_dialog_content = "「이게 바로 내 힘이야!」",
  ui_story_5053_50530102_54_dialog_content = "크윽──!",
  ui_story_5053_50530102_55_dialog_content = "전부 명중했어요! 우리 너무 대단한 거 아니에요?",
  ui_story_5053_50530102_56_dialog_content = "아...아파...!",
  ui_story_5053_50530102_57_dialog_content = "너무 괴로워 보여...",
  ui_story_5053_50530102_58_dialog_content = "이럴 때 마음 약해지면 안 돼요!\n저쪽이 먼저 우릴 이유도 없이 계속 공격했잖아요!",
  ui_story_5053_50530102_59_dialog_content = "...그래, 그 말이 맞아... 전장에서 적에게 정을 품으면 안 돼.",
  ui_story_5053_50530102_60_dialog_content = "공격이 효과가 있었나...?",
  ui_story_5053_50530102_61_dialog_content = "아아... 아아악──!",
  ui_story_5053_50530102_62_dialog_content = "어라... 엄청 섬뜩한 비명인데요...",
  ui_story_5053_50530102_63_dialog_content = "이런! 「검은 천사」가 힘을 모으고 있어! 곧 폭발이 일어날 거야!",
  ui_story_5053_50530102_64_dialog_content = "어, 어쩌지...?!",
  ui_story_5053_50530102_65_dialog_content = "미아, 잘했다. 지금부터는 내게 맡겨라.",
  ui_story_5053_50530102_66_dialog_content = "아버님...?",
  ui_story_5053_50530102_67_dialog_content = "모두 물러서라!",
  ui_story_5053_50530102_68_dialog_content = "다...",
  ui_story_5053_50530102_69_dialog_content = "다...니엘...!!!",
  ui_story_5053_50530102_70_dialog_content = "그대는 그토록 나와 싸우고 싶은 것인가?",
  ui_story_5053_50530102_71_dialog_content = "원한다면 들어주도록 하지.",
  ui_story_5053_50530102_72_dialog_content = "「다음에는 그대의 이름을 무덤에 새겨라!」",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5053_50530102_74_dialog_content = "으... 으으...",
  ui_story_5053_50530102_75_dialog_content = "「검은 천사」는 어디 갔습니까?",
  ui_story_5053_50530102_76_dialog_content = "바깥의 오솔길을 따라 도망친 것 같아요.",
  ui_story_5053_50530102_77_dialog_content = "성주님의 방금 그 공격, 정말 하늘도 땅도 다 갈라버릴 것 같았어요!",
  ui_story_5053_50530102_78_dialog_content = "「검은 천사」가 아무리 강해도, 이번엔 분명히 큰 타격을 입었을 거예요.\n아마 멀리 도망가진 못했겠죠?",
  ui_story_5053_50530102_79_dialog_content = "......",
  ui_story_5053_50530102_80_dialog_content = "외삼촌, 그 「검은 천사」가 신경 쓰이시는 건가요?",
  ui_story_5053_50530102_81_dialog_content = "저 목소리는 확실히... 아니, 됐어요. 누나가 괴물일 리가 없잖아요.",
  ui_story_5053_50530102_82_dialog_content = "쟈키니, 어서 주문을 외워라.",
  ui_story_5053_50530102_83_dialog_content = "아... 그렇죠! 계속 방해하던 「검은 천사」가 드디어 사라졌으니까,\n이번에야말로 여러분을 데리고 나가야죠!",
  ui_story_5053_50530102_84_dialog_content = "「아드 프라이센스~ 아드 프라이센스~ 아드 프라이센스~」",
  ui_story_5053_50530102_85_dialog_content = "우리를 현실 세계로 되돌려 주세요!",
  ui_story_5053_50530102_86_dialog_content = "「아브라카다브라!」",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>..................</color>",
  ui_story_5053_50530102_88_dialog_content = "아무 효과도 없는 것 같아...",
  ui_story_5053_50530102_89_dialog_content = "다시 갈게요!",
  ui_story_5053_50530102_90_dialog_content = "「아드 프라이센스~ 아드 프라이센스~ 아드 프라이센스!」",
  ui_story_5053_50530102_91_dialog_content = "우리를 현실 세계로 되돌려 주세요!\n「아브라카다브라!」",
  ui_story_5053_50530102_92_dialog_content = "쟈키니, 그 주문 진짜 맞아?",
  ui_story_5053_50530102_93_dialog_content = "당연하죠! 다들 손 꽉 잡은 거 맞죠? 어디 보자... 잘 잡고 있네요!",
  ui_story_5053_50530102_94_dialog_content = "아까 실패한 건 다들 정신이 없어서 제대로 손을 못 잡은 탓인 줄 알았는데...",
  ui_story_5053_50530102_95_dialog_content = "지금은 왜 손도 잘 잡고 있는데 안 되는 거죠?!",
  ui_story_5053_50530102_96_dialog_content = "직전에 쟈키니가 주문을 외울 땐 이 세계의 「영원한 기억의 수정」을 가지고 있었어.\n혹시 그걸 잊은 건 아니지?",
  ui_story_5053_50530102_97_dialog_content = "아뇨, <color=#FFB400>시간을 되돌릴 때만 이 세계의 「영원한 기억의 수정」이 필요해요</color>.\n그게 바로 엄마가 만든 긴급 대피 장치거든요.",
  ui_story_5053_50530102_98_dialog_content = "이 세계를 떠나는 일반적인 주문엔 없어도 되는 게 맞아요!",
  ui_story_5053_50530102_99_dialog_content = "다른 가능성은 없는가.",
  ui_story_5053_50530102_100_dialog_content = "어쩌면... <color=#FFB400>모여야 할 사람이 아직 다 안 모여서</color>일지도 몰라요...",
  ui_story_5053_50530102_101_dialog_content = "다 안 모였다니?",
  ui_story_5053_50530102_102_dialog_content = "「영원한 기억의 수정」에 들어올 땐 수정을 처음 가동한 사람이 조작하고,\n원래 세계로 돌아갈 땐 들어온 모두가 모이는 게 안전을 위한 조건이에요.",
  ui_story_5053_50530102_103_dialog_content = "들어올 때는 주문으로 이 규칙을 어기긴 했지만... 나갈 땐 그럴 일 없어요!",
  ui_story_5053_50530102_104_dialog_content = "다들 모여 있는 거 맞죠? 저 눈 이상해진 거 아니죠?",
  ui_story_5053_50530102_105_dialog_content = "그럼 설마 우리 말고도 누가 이 안으로 끌려들어 왔다는 거야?",
  ui_story_5053_50530102_106_dialog_content = "아니면... 우리가 들어온 것보다 먼저 이미 누군가 모종의 방법으로\n「영원한 기억의 수정」 속에 들어와 있었을지도 몰라요...",
  ui_story_5053_50530102_107_dialog_content = "하지만 수정을 가동한 사람은 이미 세상을 떠났는데... 그럴 리가 없잖아요?",
  ui_story_5053_50530102_108_dialog_content = "......",
  ui_story_5053_50530102_109_dialog_content = "고, 공작부인님... 직접 오시다니...",
  ui_story_5053_50530102_110_dialog_content = "정말 죄송합니다. 저희의 부족함 때문에 공작부인님의 휴식을 방해하고 말았습니다.",
  ui_story_5053_50530102_111_dialog_content = "괜찮아. 무슨 일인지 말해줄 수 있을까?",
  ui_story_5053_50530102_112_dialog_content = "물론입니다.\n방금 정체불명의 침입자들이 정원으로 들어와 어떤 괴물과 싸웠습니다.",
  ui_story_5053_50530102_113_dialog_content = "그중 한 사람은 용모나 복장 모두 베로니카 전하와 매우 흡사했습니다만,\n저희로서는 확인이 어려웠습니다...",
  ui_story_5053_50530102_114_dialog_content = "베로니카?\n그랬구나, 다들 고생했어.",
  ui_story_5053_50530201_1_dialog_content = "저기... 다들 정말 안 드세요? 안 드실 거면 제가 다 먹어요?",
  ui_story_5053_50530201_2_dialog_content = "그게 잘도 넘어가네...",
  ui_story_5053_50530201_3_dialog_content = "아까 우린 조슈아 부인의 정원에서 싸웠잖아. 이따가 대체 뭐라고 해명하지?",
  ui_story_5053_50530201_4_dialog_content = "릴렉스~ 릴렉스~ 걱정한다고 해결이 되는 것도 아니잖아요.",
  ui_story_5053_50530201_5_dialog_content = "휴... 정말 부럽네. 언제든지 그렇게 낙관적일 수 있다니.",
  ui_story_5053_50530201_6_dialog_content = "조슈아는 남을 몰아세울 위인이 아니다.",
  ui_story_5053_50530201_7_dialog_content = "사람을 보내 우릴 이곳으로 부르고 간식까지 보낸 것은 예로써 대하려는 표현이다.\n우릴 곤란하게 할 생각은 없는 것이다.",
  ui_story_5053_50530201_8_dialog_content = "흥, 그것참 다행이네요.",
  ui_story_5053_50530201_9_dialog_content = "만약 <color=#FFB400>다른 한 사람</color>도 여기 있었다면 우린 진작에 백야성 감옥에 들어갔을 텐데 말이죠.",
  ui_story_5053_50530201_10_dialog_content = "다른 한 사람이요? 누구 얘긴가요?",
  ui_story_5053_50530201_11_dialog_content = "......",
  ui_story_5053_50530201_12_dialog_content = "과거의 나를 말하는 것이다.",
  ui_story_5053_50530201_13_dialog_content = "성주 전하께서도 그 정도 자각은 하고 계셨던 모양이군요.",
  ui_story_5053_50530201_14_dialog_content = "아, 아무튼! 이 세계의 「조슈아」 부인이 나타났다는 건...",
  ui_story_5053_50530201_15_dialog_content = "적어도 이 세계의 「조슈아」 부인은 검은 천사가 아니라는 뜻이 되겠네요.",
  ui_story_5053_50530201_16_dialog_content = "그것들 모두 우리가 지금 걱정해야 할 문제가 아니다.\n쟈키니, 또 누가 「영원한 기억의 수정」 속에 들어왔는지 알아낼 수 있는가?",
  ui_story_5053_50530201_17_dialog_content = "방법이야 물론 있죠.",
  ui_story_5053_50530201_18_dialog_content = "이 세계의 「영원한 기억의 수정」만 있으면 돼요!",
  ui_story_5053_50530201_19_dialog_content = "그 수정만 있으면 시간도 되돌릴 수 있고,\n<color=#FFB400>누가 수정 속 환영이고, 누가 진짜 사람인지도 확인할 수 있어요</color>.",
  ui_story_5053_50530201_20_dialog_content = "그 사람이 어디에 있는지까지는 알 수 없지만요...",
  ui_story_5053_50530201_21_dialog_content = "그리고 한 가지 단점이 있어요.\n한 사람씩 확인해야 해서 시간이 꽤 걸릴 거예요.",
  ui_story_5053_50530201_22_dialog_content = "백야성에 사람이 저렇게 많은데, 하나씩 확인하려면 시간이 얼마나 걸릴까...",
  ui_story_5053_50530201_23_dialog_content = "괜찮아요~ 긴급 대피 장치가 손에 있는 한, 몇 번이든 시간을 되돌릴 수 있잖아요!",
  ui_story_5053_50530201_24_dialog_content = "아, 그치만 이 세계의 작동을 유지하는 루미나를 소모해야 하다 보니...\n함부로 쓸 순 없긴 해요.",
  ui_story_5053_50530201_25_dialog_content = "그렇다면 지금 급선무는 「영원한 기억의 수정」을 찾는 것이로군.\n「검은 천사」의 일은 추후에 다시 이야기하도록 하지.",
  ui_story_5053_50530201_26_dialog_content = "찾는 물건이 이거일까요?",
  ui_story_5053_50530201_27_dialog_content = "앗, 공작부인님... 그거... 「영원한 기억의 수정」이잖아요?!",
  ui_story_5053_50530201_28_dialog_content = "공작부인님, 저희 얘길 듣고 계셨어요?\n어떻게 저희가 「영원한 기억의 수정」을 찾는다는 걸 아셨죠?",
  ui_story_5053_50530201_29_dialog_content = "후훗, 얘, 그렇게 당황할 거 없어. 일단 수정부터 살펴보렴.",
  ui_story_5053_50530201_30_dialog_content = "이건... 마, 마마마말도 안 돼!",
  ui_story_5053_50530201_31_dialog_content = "공작부인님이... <color=#FFB400>「진짜 오로리안」</color>이었단 말이에요?!",
  ui_story_5053_50530201_32_dialog_content = "!!!",
  ui_story_5053_50530201_33_dialog_content = "누나... 누나가 어떻게...? 정말 누나인가요?",
  ui_story_5053_50530201_34_dialog_content = "내가 아니면 누구겠니, 우리 귀여운 천재 군?",
  ui_story_5053_50530201_35_dialog_content = "..................",
  ui_story_5053_50530201_36_dialog_content = "쟈키니, 확실한가?",
  ui_story_5053_50530201_37_dialog_content = "틀림없이 절대로 확실해요! 제 눈에 문제가 없는 한 정말이에요!",
  ui_story_5053_50530201_38_dialog_content = "어머님이... 진짜 어머님?",
  ui_story_5053_50530201_39_dialog_content = "당연히 진짜지.",
  ui_story_5053_50530201_40_dialog_content = "베로니카는 기사단에 막 들어갔을 때와 별 차이가 없구나. 내 기억 속 그대로야.",
  ui_story_5053_50530201_41_dialog_content = "훌쩍... 그, 그건...",
  ui_story_5053_50530201_42_dialog_content = "노라... 그 여자가 베로니카의 몸을 개조했어요...\n그래서 베로니카의 몸은 영원히 13살 때의 모습으로 멈추게 되었죠.",
  ui_story_5053_50530201_43_dialog_content = "하지만... 누나는... 분명히 제 눈으로 직접 확인했는데...",
  ui_story_5053_50530201_44_dialog_content = "아? 무슨 뜻이죠?",
  ui_story_5053_50530201_45_dialog_content = "12년 전 「솔라드 가문의 날」 때, 미아... 즉 베로니카는 기사단 임무를 수행하던 중\n암귀에게 당해 씨앗이 심어졌다.",
  ui_story_5053_50530201_46_dialog_content = "이후 일루미나의 실험실로 보내 「치료」를 진행했으나,\n그 「치료」라는 것은 실제로는 암귀와 반역자가 꾸민 함정이었던 것이다.",
  ui_story_5053_50530201_47_dialog_content = "조슈아는 베로니카를 구하기 위해 홀로 적과 맞섰다.",
  ui_story_5053_50530201_48_dialog_content = "비록 끝내 베로니카를 구해내는 데 성공하였으나,\n조슈아도 모종의 원인 때문에 「씨앗」이 심어지고 말았다...",
  ui_story_5053_50530201_49_dialog_content = "그리고 결국 병에 시달린 끝에...",
  ui_story_5053_50530201_50_dialog_content = "<color=#FFB400>스스로 목숨을 끊었다.</color>",
  ui_story_5053_50530201_51_dialog_content = "허나 그랬던 그대가 지금 「영원한 기억의 수정」 속에 있군.\n해명을 듣고 싶다만.",
  ui_story_5053_50530201_52_dialog_content = "솔라드! 그게 12년 만에 만난 아내를 대하는 태도입니까?!",
  ui_story_5053_50530201_53_dialog_content = "괜찮아, 칼렙. 모두의 안전을 지키려면 다니엘은 항상 경계해야 해.\n다니엘은 틀리지 않았어.",
  ui_story_5053_50530201_54_dialog_content = "...알겠어요, 누나가 그렇게 말한다면야.",
  ui_story_5053_50530201_55_dialog_content = "그럼 다니엘의 이야기를 이어갈게.",
  ui_story_5053_50530201_56_dialog_content = "맞아요. 나는 병에 시달린 끝에...",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>수년 전, 솔라드 가문 저택</color>",
  ui_story_5053_50530201_58_dialog_content = "콜록콜록... 다니엘, 날 죽여줘요.",
  ui_story_5053_50530201_59_dialog_content = "제발, 내게 그런 요구는 하지 말아 줘, 조슈아...",
  ui_story_5053_50530201_60_dialog_content = "내가 「씨앗」의 침식에 저항할수록... 「씨앗」은 날 더 괴롭게 만들어요...",
  ui_story_5053_50530201_61_dialog_content = "확실히 느껴져요. 지금 「씨앗」은 내 몸의 통제권을 빼앗으려 하고 있어요...",
  ui_story_5053_50530201_62_dialog_content = "...그대를 구할 방법을 반드시 찾겠어. 날 믿어줘!",
  ui_story_5053_50530201_63_dialog_content = "그래, 요하네스 의료단... 기억하고 있어?\n요하네스는 명의니까, 방법이 있을 거야.",
  ui_story_5053_50530201_64_dialog_content = "지금 당장 사람을 보내서 요하네스의 행방을 찾을게!",
  ui_story_5053_50530201_65_dialog_content = "푹 쉬고 있어. 꼭 좋은 소식을 가져올 테니까.",
  ui_story_5053_50530201_66_dialog_content = "소용없어요... 다니엘... 그래봤자...",
  ui_story_5053_50530201_67_dialog_content = "아아악──!",
  ui_story_5053_50530201_68_dialog_content = "발악하지 말고 얌전히 몸을 넘겨.",
  ui_story_5053_50530201_69_dialog_content = "마음대로 될 것 같아?",
  ui_story_5053_50530201_70_dialog_content = "내 심장에 칼을 꽂을지언정, 너한테 내 몸을 넘기진 않아!",
  ui_story_5053_50530201_71_dialog_content = "뭐야...?! 그 칼 치워!",
  ui_story_5053_50530201_72_dialog_content = "싫어!",
  ui_story_5053_50530201_73_dialog_content = "저리 치우라고!",
  ui_story_5053_50530201_74_dialog_content = "으윽...",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5053_50530201_76_dialog_content = "「영원한 기억의 수정」...?",
  ui_story_5053_50530201_77_dialog_content = "뭐 하려는 거야?! 그만둬!",
  ui_story_5053_50530201_78_dialog_content = "우리를... 저 지난날의 시간으로 인도하라...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5053_50530201_80_dialog_content = "누나? 괜찮아요? 방금 그 소리는 뭐죠?",
  ui_story_5053_50530201_81_dialog_content = "왜 답이 없는 건데요...? 괜히 겁주지 마요. 저 들어갈 거예요!",
  ui_story_5053_50530201_82_dialog_content = "누, 누나...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>누나!!</size>",
  ui_story_5053_50530201_84_dialog_content = "씨앗은 촉매가 되어, 내 안에 <color=#FFB400>두 개의 인격</color>이 생겨났어요.",
  ui_story_5053_50530201_85_dialog_content = "하나는 평소의 나와 다를 게 없지만, 다른 하나는 괴물처럼 이성이 없고\n광기에 사로잡혀 있어요.",
  ui_story_5053_50530201_86_dialog_content = "그 인격은 점점 커져갔고, 내 몸을 빼앗아 주변 사람들을 해치려고 했어요.",
  ui_story_5053_50530201_87_dialog_content = "절대로 그런 일이 벌어지게 둘 순 없었어요. 그래서 난 내 다른 인격과 싸웠죠.",
  ui_story_5053_50530201_88_dialog_content = "두 인격이 한 몸 안에서 끝없이 싸우면서, 매일 내 머리는 찢어질 듯한 두통에 시달렸어요.",
  ui_story_5053_50530201_89_dialog_content = "하지만 그 괴물은 마치 감각이 없는 것처럼 전혀 영향을 받지 않았고,\n서서히 날 압도하기 시작했어요...",
  ui_story_5053_50530201_90_dialog_content = "그에 반해 난 그 인격과의 다툼 속에서 쇠약해져서 금방이라도 무너질 것 같았어요.\n그렇게 되면 결국 져버리고 말겠죠.",
  ui_story_5053_50530201_91_dialog_content = "그래서 난 방법을 하나 찾았어요.\n비록 나도 이길 수 없게 되지만, 상대를 철저히 패배시킬 방법...",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>그건 바로 우릴 「영원한 기억의 수정」 속에 가두는 거였어요.</color>",
  ui_story_5053_50530201_93_dialog_content = "난 죽음을 각오하고 나와 그 괴물을 이 세계에 가두었어요.",
  ui_story_5053_50530201_94_dialog_content = "우린 몸 하나를 나눠 가지고 있으니까, 나만 이 세계를 떠나는 걸 거부하면,\n괴물도 함께 남을 수밖에 없었죠.",
  ui_story_5053_50530201_95_dialog_content = "우리의 싸움은 정말, 아주 길었어요.",
  ui_story_5053_50530201_96_dialog_content = "자정의 종소리가 끝나고, 규칙을 어긴 우린 이 세계의 일부가 되었어요.",
  ui_story_5053_50530201_97_dialog_content = "우린 기억을 잃고 이 세계의 「조슈아」로 하나가 되었고,\n영원히 같은 날을 반복하며 살아왔어요.",
  ui_story_5053_50530201_98_dialog_content = "여러분이 여기 올 때까지 말이에요.",
  ui_story_5053_50530201_99_dialog_content = "그리고 여러분이 오면서 우리의 기억은 되살아났어요.",
  ui_story_5053_50530201_100_dialog_content = "깨어난 괴물은 나와 떨어지려고 발버둥 쳤죠.",
  ui_story_5053_50530201_101_dialog_content = "그리고 <color=#FFB400>내 모든 힘을 빼앗아</color> 도망쳤고, 「영원한 기억의 수정」에서 나가려 하고 있어요.",
  ui_story_5053_50530201_102_dialog_content = "무척 절망적인 상황이지만, 그래도 이번에는...",
  ui_story_5053_50530201_103_dialog_content = "나도 더는 혼자가 아니에요.",
  ui_story_5053_50530201_104_dialog_content = "......",
  ui_story_5053_50530201_105_dialog_content = "저, 정말 믿을 수 없는 이야기네요...\n그러니까 우릴 공격한 <color=#FFB400>「검은 천사」가 또 다른 조슈아 부인</color>이라는 거죠?",
  ui_story_5053_50530201_106_dialog_content = "「검은 천사」? 그 괴물한테 이름도 지어준 거구나...\n응, 그렇게 이해해도 괜찮아.",
  ui_story_5053_50530201_107_dialog_content = "병상에서 나눴던 대화의 내용을 아는 것은 나와 조슈아뿐이거늘,\n세세한 부분까지 조금도 다르지 않았다.",
  ui_story_5053_50530201_108_dialog_content = "조슈아, 진정 그대란 말인가...",
  ui_story_5053_50530201_109_dialog_content = "드디어 날 믿어주는 거군요, 정말 다행이에요.",
  ui_story_5053_50530201_110_dialog_content = "훌쩍... 어머님... 정말 어머님이셨군요...",
  ui_story_5053_50530201_111_dialog_content = "어머, 얘 좀 봐. 예쁜 얼굴이 또 눈물범벅이잖니.",
  ui_story_5053_50530201_112_dialog_content = "누나... 누나가 여기 있을 줄은 정말 꿈에도 몰랐어요...\n그렇게 오랫동안 찾아다녔는데... 지금까지 왜 못 찾은 걸까요...?",
  ui_story_5053_50530201_113_dialog_content = "정말... 다행이에요... 12년 만에 다시 누나와 얘기할 수 있게 됐네요...",
  ui_story_5053_50530201_114_dialog_content = "(「씨앗」과 두 개의 인격... 미아의 몸에 발생했던 상황과 많이 비슷해.)",
  ui_story_5053_50530201_115_dialog_content = "(하지만 미아의 두 인격은 무엇이든 서로 말할 수 있고, 서로 돕는 친구야.\n반면에 조슈아 부인의 인격은 상반된 목표를 가지고 서로 싸워왔어.)",
  ui_story_5053_50530201_116_dialog_content = "(같은 「씨앗」이라도 사람마다 그 작용에 저렇게 큰 차이가 있는 거였구나.)",
  ui_story_5053_50530201_117_dialog_content = "그런데 다들 방금 「12년 전」이라고 했나요?",
  ui_story_5053_50530201_118_dialog_content = "그럼 설마 나 여기서 12년 동안이나 잠들어 있었던 건가요?",
  ui_story_5053_50530201_119_dialog_content = "그렇다.",
  ui_story_5053_50530201_120_dialog_content = "어쩐지 모습이 완전히 달라졌다 했네요, 다니엘.",
  ui_story_5053_50530201_121_dialog_content = "여러분이 이름을 부르지 않았다면, 나조차도 당신인 줄 몰랐을 거예요.",
  ui_story_5053_50530201_122_dialog_content = "그 눈... 얼굴은... 어쩌다 그렇게 된 건가요?",
  ui_story_5053_50530201_123_dialog_content = "오랜 세월 너무나도 많은 전쟁과 불안정한 정세를 겪어왔다.\n어느 상처가 언제의 것이었는지조차 기억이 나질 않는군.",
  ui_story_5053_50530201_124_dialog_content = "하지만 그대가 나를 떠났던 그날과, 그대의 가슴에 박힌 단검의 서늘함은\n단 한 순간도 잊은 적이 없었다...",
  ui_story_5053_50530201_125_dialog_content = "다니엘...",
  ui_story_5053_50530201_126_dialog_content = "그럼... 공작부인님의 몸은 이미 장례를 치렀겠죠...?",
  ui_story_5053_50530201_127_dialog_content = "그래도 공작부인님이나 「검은 천사」가 「영원한 기억의 수정」에서 나갈 수 있나요?",
  ui_story_5053_50530201_128_dialog_content = "가능합니다.",
  ui_story_5053_50530201_129_dialog_content = "누나의 몸은 <color=#FFB400>애초에 매장되지 않았으니까요</color>.",
  ui_story_5053_50530201_130_dialog_content = "그게 무슨 뜻이냐.",
  ui_story_5053_50530201_131_dialog_content = "흥... 제가 누나를 발견했을 때, 사실 누나는 죽지 않았어요.",
  ui_story_5053_50530201_132_dialog_content = "전 꾀를 약간 써서 누나의 몸을 몰래 집으로 가져가 치료를 계속해 왔던 겁니다.",
  ui_story_5053_50530201_133_dialog_content = "네...? 하지만 그때 백야성의 모두가 어머님의 장례식을 보고 있었는데...\n외삼촌은 대체 어떻게...",
  ui_story_5053_50530201_134_dialog_content = "조슈아의 장례식은 내 손으로 직접 치렀다. 처음부터 끝까지 그럴 틈은 없었을 터.",
  ui_story_5053_50530201_135_dialog_content = "안장 후 무덤을 파내기라도 한 게 아니라면 말이지.",
  ui_story_5053_50530201_136_dialog_content = "어머... 우리 귀여운 천재 군, 대체 어떻게 한 건지 누나한테 말해주겠니?",
  ui_story_5053_50530201_137_dialog_content = "누나가 물어본다면야...\n맞아요, 장례식이 끝난 뒤에 제가 누나 무덤을 팠어요.",
  ui_story_5053_50530201_138_dialog_content = "사람들의 눈을 피하려고 먼 곳부터 무덤까지 통하는 지하 통로를 팠었죠.\n그래서 아무도 의심하지 못했을 거예요.",
  ui_story_5053_50530201_139_dialog_content = "직접 팠다구요...?\n칼렙 씨처럼 품위 있어 보이는 사람이 그런 힘쓰는 일까지 하는 건가요?!",
  ui_story_5053_50530201_140_dialog_content = "훗, 누나를 위해서라면 그까짓 일이 뭐가 대수겠습니까.",
  ui_story_5053_50530201_141_dialog_content = "하지만 외삼촌... 어떻게 장의사와 의사들을 속여 넘기신 거죠?\n설마 그 사람들도 매수하신 건가요...?",
  ui_story_5053_50530201_142_dialog_content = "아니요, 그저 약을 사용했을 뿐이에요.",
  ui_story_5053_50530201_143_dialog_content = "하하... 그땐 저도 놀랐습니다.\n당신네 하이가든의 의사들이 그런 「잔꾀」조차 간파하지 못한다니 말이죠.",
  ui_story_5053_50530201_144_dialog_content = "그러니 누나도 제대로 치료하지 못하는 게 아닙니까.",
  ui_story_5053_50530201_145_dialog_content = "칼렙, 그대가 여명 아카데미에서 교사들과 말다툼을 하던 때에는\n지금처럼 겸손하진 않았지.",
  ui_story_5053_50530201_146_dialog_content = "「여명 아카데미 100년에 한 번 있을 천재」로서,\n그대가 그 지혜를 부디 올바른 곳에 사용해 주었으면 좋겠군.",
  ui_story_5053_50530201_147_dialog_content = "휴, 칼렙... 왜 꼭 그렇게 멋대로 해야만 했던 거니...",
  ui_story_5053_50530201_148_dialog_content = "누나가 솔라드와 아이들 곁을 떠나려 하지 않았으니까요.\n반면에 솔라드는 누나의 삶을 점점 더 힘들게만 만들었죠.",
  ui_story_5053_50530201_149_dialog_content = "전 그저 누나를 지키고 싶었을 뿐이에요.",
  ui_story_5053_50530201_150_dialog_content = "휴... 미안해, 누나가 괜한 걱정을 끼쳤구나.",
  ui_story_5053_50530201_151_dialog_content = "그대가 계속 어리광을 받아 주니 녀석이 언제까지고 어린애인 것이다.",
  ui_story_5053_50530201_152_dialog_content = "칼렙, 군주를 속인 죄는 이곳에서 나간 뒤에 다시 묻겠다.",
  ui_story_5053_50530201_153_dialog_content = "...그럼 「검은 천사」를 쓰러트리면 우리도 여길 떠나고, 어머님도 다시 살려낼 수 있나요?",
  ui_story_5053_50530201_154_dialog_content = "지금까지 알 수 있는 정보로 보았을 때는 그렇습니다.",
  ui_story_5053_50530201_155_dialog_content = "그렇다면 조슈아의 육체 상태는 어떠한가.\n갑작스러운 소생을 견뎌낼 수 있는 것인가.",
  ui_story_5053_50530201_156_dialog_content = "물론 상처 하나 없습니다.\n누나가 혼수상태에 빠진 뒤로, 전 누나의 치료에 제 모든 시간과 힘을 쏟았으니까요.",
  ui_story_5053_50530201_157_dialog_content = "그 성과는 <color=#FFB400>절 보면 아시겠죠</color>.",
  ui_story_5053_50530201_158_dialog_content = "보면 알아요? 어딜요?",
  ui_story_5053_50530201_159_dialog_content = "칼렙, 설령 그것이 조슈아를 위한 일이라고 하더라도,\n나는 그대가 윤리에 어긋나는 실험을 하는 것은 금할 것이다.",
  ui_story_5053_50530201_160_dialog_content = "흥, 그게 당신과 무슨 상관이 있단 말입니까.",
  ui_story_5053_50530201_161_dialog_content = "잠깐만... 저 좀 어지러운데요?! 그러니까 대체 무슨 뜻이냐구요...",
  ui_story_5053_50530201_162_dialog_content = "쟈키니 씨, 제가 올해 몇 살 같습니까?",
  ui_story_5053_50530201_163_dialog_content = "이십 대 초반?",
  ui_story_5053_50530201_164_dialog_content = "하, 바로 그겁니다.",
  ui_story_5053_50530201_165_dialog_content = "저기... 제가 잘못 기억한 게 아니라면, 외삼촌은 아마 곧 마흔 살일 거예요...",
  ui_story_5053_50530201_166_dialog_content = "에엣──?!",
  ui_story_5053_50530201_167_dialog_content = "으엑──?!",
  ui_story_5053_50530201_168_dialog_content = "전 그저 외삼촌이 타고나셔서 그런 거거나, 옷을 잘 입으셔서 그런 줄 알았어요.\n그런데 그게 설마 실험의 결과일 줄은...",
  ui_story_5053_50530201_169_dialog_content = "제가 검증되지도 않은 약을 누나에게 쓸 것 같습니까?",
  ui_story_5053_50530201_170_dialog_content = "그렇다고 저 귀족 놈들처럼 보통 사람들을 해쳐서도 안 되지 않습니까.\n그러니 당연히 제 몸으로 실험을 했을 뿐입니다.",
  ui_story_5053_50530201_171_dialog_content = "세상에... 칼렙, 너란 애는 정말...",
  ui_story_5053_50530201_172_dialog_content = "어, 어머님, 괜찮으세요? 안색이 안 좋아요...",
  ui_story_5053_50530201_173_dialog_content = "괜찮아... 엄마는 이젠 익숙하거든. 아마...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>근데 PlayerName 씨, 칼렙 씨 좀 유치하지 않아요?\n설마 그 약은 정신연령의 성장까지 멈추는 걸까요?</size>",
  ui_story_5053_50530201_175_dialog_content = "쟈키니 씨! 다 들립니다!",
  ui_story_5053_50530201_176_dialog_content = "...아무튼, 누나의 몸에는 문제가 없습니다.\n하지만 체내의 루미나가 자주 폭주하고 있습니다.",
  ui_story_5053_50530201_177_dialog_content = "그 방면으로는 제 연구가 아직 부족해서, 지금까지 해결 방법을 찾지 못했습니다.",
  ui_story_5053_50530201_178_dialog_content = "루미나? 아... 그럼 저한테 공작부인님의 루미나가 어디 있냐고\n물어본 것도 치료 때문이었어요?",
  ui_story_5053_50530201_179_dialog_content = "흥, 그렇습니다. 애초부터 전 그저 누나가 남긴 루미나를 찾아서\n치료 실험에 쓰려고 했던 것뿐입니다.",
  ui_story_5053_50530201_180_dialog_content = "하지만 누나 본인이 계속 「영원한 기억의 수정」 속에 있었을 줄은 몰랐죠...\n그리고 아마 그게 바로 누나의 몸속 루미나가 폭주하는 이유였겠지요.",
  ui_story_5053_50530201_181_dialog_content = "결국 제 가설은 전부 틀렸던 겁니다...",
  ui_story_5053_50530201_182_dialog_content = "칼렙, 그대는 진작에 이 사실을 내게 알렸어야 했다.",
  ui_story_5053_50530201_183_dialog_content = "당신에게요? 누나를 끝없이 괴롭게 만들어 왔던 당신에게 말입니까?",
  ui_story_5053_50530201_184_dialog_content = "휴... 왜 잘 말하다 말고 또 싸우는 걸까? 다른 사람들도 있는데 그만들 해요.",
  ui_story_5053_50530201_185_dialog_content = "미안해요, 누나...",
  ui_story_5053_50530201_186_dialog_content = "조슈아의 육체에 문제가 없다면야, 서둘러 데리고 나가는 것이 좋겠지.",
  ui_story_5053_50530201_187_dialog_content = "이제 본론으로 돌아가서, 「검은 천사」를 상대할 방법을 논의해야 한다.",
  ui_story_5053_50530201_188_dialog_content = "그래요, 그럼 나와 「검은 천사」에 대한 얘기를 계속해 볼게요.",
  ui_story_5053_50530201_189_dialog_content = "나한테 있어서 「검은 천사」는 쓰러트릴 수 없는 상대예요.",
  ui_story_5053_50530201_190_dialog_content = "우린 <color=#FFB400>하나의 육체를 공유하며, 생사를 함께하고 있으니까요</color>.\n「검은 천사」를 소멸시키려면 제삼자의 도움이 필요해요.",
  ui_story_5053_50530201_191_dialog_content = "하지만 여러분도 조심해야 해요. 「검은 천사」는 여러분도 사냥하고 있으니까요.",
  ui_story_5053_50530201_192_dialog_content = "사냥이요?",
  ui_story_5053_50530201_193_dialog_content = "맞아, 「검은 천사」는 이미 나와의 싸움이 지겨워졌거든.\n이제 내게서 벗어나 독립된 존재가 되어 내 몸을 지배하고 싶어 해.",
  ui_story_5053_50530201_194_dialog_content = "현실 세계라면 그건 어려운 일이었을 거야.",
  ui_story_5053_50530201_195_dialog_content = "하지만 그 괴물은 「영원한 기억의 수정」을 가동한 내 일부니까,\n이 안에서는 <color=#FFB400>살아 있는 오로리안을 죽이고 루미나를 얻어 완전해질 수가 있어</color>.",
  ui_story_5053_50530201_196_dialog_content = "쟈키니, 저 말이 사실인가.",
  ui_story_5053_50530201_197_dialog_content = "음~ 믿기 힘든 이야기지만, 「영원한 기억의 수정」 속이라면 가능성이 있어요.",
  ui_story_5053_50530201_198_dialog_content = "「영원한 기억의 수정」은 겉보기엔 그저 기억을 재생하는 장치일 뿐이지만,\n그 안의 원리는 무척 심오하거든요.",
  ui_story_5053_50530201_199_dialog_content = "그래서 저희 엄마도 여왕 폐하의 분부를 받아서 이거 하나만 만들고,\n그 뒤엔 관련 자료를 다 숨겨버렸던 거예요...",
  ui_story_5053_50530201_200_dialog_content = "지금까지의 정보를 정리해 본다면, 앞으로 기다리고 있는 결말은 두 가지네요.",
  ui_story_5053_50530201_201_dialog_content = "하나는 우리가 「검은 천사」를 쓰러트리고, 공작부인님을 데리고 여길 떠나는 것.",
  ui_story_5053_50530201_202_dialog_content = "다른 하나는 우리가 「검은 천사」의 손에 죽고,\n괴물이 현실 세계에서 부활하게 만드는 것, 맞죠?",
  ui_story_5053_50530201_203_dialog_content = "맞아, 똑똑한 아이네. 넌 PlayerName 맞지?",
  ui_story_5053_50530201_204_dialog_content = "맞아요. 그러고 보니까 공작부인님은 저랑 쟈키니의 이름도 이미 알고 계시고,\n「미아」라는 이름에도 놀라지 않으시네요.",
  ui_story_5053_50530201_205_dialog_content = "혹시 공작부인님도 시간을 되돌리기 전의 기억이 있으신 건가요?",
  ui_story_5053_50530201_206_dialog_content = "맞아, 시간을 되돌릴 때 <color=#FFB400>나도 함께 있었거든</color>.",
  ui_story_5053_50530201_207_dialog_content = "그리고... 이제 다시는 가족들과 떨어지고 싶지 않아.",
  ui_story_5053_50530201_208_dialog_content = "제가 꼭 「검은 천사」를 쓰러트리고 누나를 데리고 나갈게요.\n그러니까 이제 슬퍼하지 마요.",
  ui_story_5053_50530201_209_dialog_content = "저도...! 저도 반드시 어머님을 구해낼 거예요!",
  ui_story_5053_50530201_210_dialog_content = "그래, 너흴 믿어.",
  ui_story_5053_50530201_211_dialog_content = "「검은 천사」는 이성이 없는 괴물이지만, 아주 교활한 녀석이야.",
  ui_story_5053_50530201_212_dialog_content = "녀석이 먼저 모습을 드러내게 만들 미끼가 필요해.",
  ui_story_5053_50530201_213_dialog_content = "다니엘, 당신에게 부탁해도 될까요?",
  ui_story_5053_50530201_214_dialog_content = "물론이다. 그토록 중요하고 위험한 역할이라면 내가 맡는 것이 가장 좋겠지.",
  ui_story_5053_50530201_215_dialog_content = "하지만 어떻게 유인해야 하지?",
  ui_story_5053_50530201_216_dialog_content = "아무것도 안 해도 돼요. 왜냐하면 그 괴물은... <color=#FFB400>당신을 조금 싫어하거든요</color>.",
  ui_story_5053_50530201_217_dialog_content = "아까도 당신이 힘으로 물리치지 않았다면,\n분명히 검은 천사에게 그 자리에서 찢겨버렸을 거예요.",
  ui_story_5053_50530201_218_dialog_content = "그리고 그건 이 세계의 젊은 당신도 마찬가지예요.\n「검은 천사」는 축제를 주관하고 있는 젊은 당신을 공격할 수도 있어요.",
  ui_story_5053_50530201_219_dialog_content = "비록 또 다른 당신을 죽여봤자 아무 소용도 없다는 걸 알지만,\n녀석은 참지 못하고 그렇게 할 거예요.",
  ui_story_5053_50530201_220_dialog_content = "...알겠다. 그렇다면 젊은 시절의 나를 찾고,\n그 곁에서 「검은 천사」가 나타나길 기다리도록 하지.",
  ui_story_5053_50530201_221_dialog_content = "잠시만요, 아버님. 그건 너무 위험해요... 혹시나 다치기라도 하시면...",
  ui_story_5053_50530201_222_dialog_content = "로니는 정말 가족을 생각하는 아이구나.",
  ui_story_5053_50530201_223_dialog_content = "하지만 지금은 긴급 상황이야. 대국을 더 중요하게 생각해야 해.",
  ui_story_5053_50530201_224_dialog_content = "너희 아버지를 믿으렴, 알겠니?",
  ui_story_5053_50530201_225_dialog_content = "네...",
  ui_story_5053_50530201_226_dialog_content = "퍼레이드가 끝난 뒤에는 광장에서 개막식을 할 차례였죠?",
  ui_story_5053_50530201_227_dialog_content = "그럼 광장 근처에서 매복할까요?",
  ui_story_5053_50530201_228_dialog_content = "좋은 생각이야. 하지만 쟈키니는 나와 함께 남았으면 좋겠어.",
  ui_story_5053_50530201_229_dialog_content = "어? 왜요? 저 무시하시면 안 돼요.\n저 이래 봬도 PlayerName 씨보다 훨씬 강하다구요!",
  ui_story_5053_50530201_230_dialog_content = "크흠...",
  ui_story_5053_50530201_231_dialog_content = "응, 알고 있어. 하지만 넌 「영원한 기억의 수정」을 조종해야 하잖니.",
  ui_story_5053_50530201_232_dialog_content = "만약 다른 사람에게 무슨 일이 생긴다면,\n시간을 되돌려서 원래 상태로 되돌릴 수 있을 거야.",
  ui_story_5053_50530201_233_dialog_content = "하지만 너한테 무슨 일이 생기면 돌이킬 수 없게 돼...",
  ui_story_5053_50530201_234_dialog_content = "그, 그것도 그렇네요...",
  ui_story_5053_50530201_235_dialog_content = "그럼 저랑 미아, PlayerName, 그리고 미끼가 되실 성주님까지,\n모두 광장으로 가서 「검은 천사」를 쓰러트리죠.",
  ui_story_5053_50530201_236_dialog_content = "쟈키니 씨, 그리고 전투 능력을 잃은 누나는 여기서 좋은 소식을 기다려 주세요.",
  ui_story_5053_50530201_237_dialog_content = "...쟈키니 씨, 누나를 반드시 잘 지켜드려야 합니다.",
  ui_story_5053_50530201_238_dialog_content = "알겠다니까요! 왜 다들 하나같이 내 실력을 의심하는 거야...",
  ui_story_5053_50530201_239_dialog_content = "의외로군, 칼렙. 난 그대가 어떻게든 조슈아 곁에 남을 줄 알았다만.",
  ui_story_5053_50530201_240_dialog_content = "지금은 「검은 천사」를 없애고 누나를 빨리 밖으로 데려가는 게 우선이잖습니까.\n제가 그 정도도 이해하지 못할 거라 생각하셨습니까?",
  ui_story_5053_50530201_241_dialog_content = "저, 저기... 시간이 없으니까 어서 가요...",
  ui_story_5053_50530201_242_dialog_content = "맞아요! 얼른 가죠!",
  ui_story_5053_50530201_243_dialog_content = "당신들! 밀지 마세요!",
  ui_story_5053_50530201_244_dialog_content = "다녀오세요! 몸조심하시구요~",
  ui_story_5053_50530201_245_dialog_content = "조슈아, 이번에는 결코 그대를 다시 잃지 않을 것이다. 약속하지.",
  ui_story_5053_50530201_246_dialog_content = "네, 당신을 믿어요.",
  ui_story_5053_50530201_247_dialog_content = "반드시 지켜줘요.",
  ui_story_5053_50530301_1_dialog_content = "퍼레이드도 끝났네. 이제 곧 축제가 시작될 거야.",
  ui_story_5053_50530301_2_dialog_content = "지금 가도 좋은 자리 잡을 수 있으려나?",
  ui_story_5053_50530301_3_dialog_content = "얼른 가자!",
  ui_story_5053_50530301_4_dialog_content = "그저 형식주의에 불과한 식전이 무슨 대단한 볼거리라고 저러는지 모르겠군요.",
  ui_story_5053_50530301_5_dialog_content = "어딜 가도 사람이 이렇게 많은데, 이래서야 어떻게 「검은 천사」를 감시합니까!",
  ui_story_5053_50530301_6_dialog_content = "관람석에 다가가 매복하면 되는 것이다.",
  ui_story_5053_50530301_7_dialog_content = "그러고 보니 마침 이 세계의 당신도 「검은 천사」의 표적이잖습니까.\n두 분이 나란히 관람석에 서면 더 효율적이지 않겠습니까?",
  ui_story_5053_50530301_8_dialog_content = "저기... 제가 관람석에 서는 게 좋을 것 같아요.\n이 세계 사람들도 저는 알아볼 수 있으니까요.",
  ui_story_5053_50530301_9_dialog_content = "아버님이 가신다면 또 불필요한 소동이 벌어질지도 몰라요...",
  ui_story_5053_50530301_10_dialog_content = "일리가 있네.\n근데 만약 「검은 천사」가 관람석의 성주님을 습격하면 미아 너 혼자 막을 수 있겠어?",
  ui_story_5053_50530301_11_dialog_content = "나...난 혼자가 아냐.",
  ui_story_5053_50530301_12_dialog_content = "이 세계의 「아버님」도 분명히 날 지켜주실 거야.",
  ui_story_5053_50530301_13_dialog_content = "게다가 관람석은 시야가 좋으니까, 만약 내가 「검은 천사」를 찾으면\n바로 모두에게 위치를 알려줄 수 있어...",
  ui_story_5053_50530301_14_dialog_content = "음... 찾게 되면 모두가 보이는 곳에 서서 방향을 알려줄게!",
  ui_story_5053_50530301_15_dialog_content = "앗... 죄, 죄송해요, 아버님... 제 생각이 너무 미숙했나요?",
  ui_story_5053_50530301_16_dialog_content = "아니다. 잘 생각했다. 네 말대로 하기로 하자.",
  ui_story_5053_50530301_17_dialog_content = "네? 정말요...?",
  ui_story_5053_50530301_18_dialog_content = "고마워요, 아버님... 그럼 다녀올게요. 모두 제 신호를 기다려 주세요!",
  ui_story_5053_50530301_19_dialog_content = "겨우 하루 지났을 뿐인데, 미아가 저렇게 용감해지고 자기 주관도 생겼다니\n정말 다행이네요.",
  ui_story_5053_50530301_20_dialog_content = "PlayerName, 지금 감상에 젖을 때가 아닙니다.\n누나를 망친 악마를 놓치는 일이 없게 눈 똑바로 뜨고 찾으세요!",
  ui_story_5053_50530301_21_dialog_content = "아, 알겠어요!",
  ui_story_5053_50530301_22_dialog_content = "카렌, 축제가 곧 시작된다. 어서 자리로 돌아와 앉거라.",
  ui_story_5053_50530301_23_dialog_content = "네, 아버님.",
  ui_story_5053_50530301_24_dialog_content = "...아버님, 카렌.",
  ui_story_5053_50530301_25_dialog_content = "언니?! 베로니카 언니!",
  ui_story_5053_50530301_26_dialog_content = "베로니카...? 어째서 네가 여기 있는 것이냐.",
  ui_story_5053_50530301_27_dialog_content = "어, 어머님께서 돌아와서 가문의 날 축제에 참가하라고 하셨거든요.",
  ui_story_5053_50530301_28_dialog_content = "네 어머니는 만나고 왔느냐.",
  ui_story_5053_50530301_29_dialog_content = "네... 몸은 조금 불편하지만, 걱정하지 말라고 하셨어요.",
  ui_story_5053_50530301_30_dialog_content = "호오? 베로니카 공주 아니십니까.\n오랜만에 뵙는 것 같은데, 그간 별고는 없었는지요?",
  ui_story_5053_50530301_31_dialog_content = "베로니카 공주는 기사단에 들어가 움브라톤으로 향한 것이 아니었나?",
  ui_story_5053_50530301_32_dialog_content = "...축전에 참가하고 싶어서 잠시 휴가를 내고 돌아왔어요.",
  ui_story_5053_50530301_33_dialog_content = "그러신가.\n하긴, 「솔라드 가문의 날」이니, 공주도 참석해야 마땅하겠지.",
  ui_story_5053_50530301_34_dialog_content = "허허, 안타깝게도 우리 일족은 지금도 움브라톤에 주둔하고 있어\n그런 복은 누릴 수가 없다네.",
  ui_story_5053_50530301_35_dialog_content = "베로니카 언니는 솔라드 가문의 일원이에요.\n가문의 날 축제에 참가하러 돌아오는 건 당연하죠!",
  ui_story_5053_50530301_36_dialog_content = "카렌, 물러서라. 하메스 공작에게 무례를 범하지 마라.",
  ui_story_5053_50530301_37_dialog_content = "아버님, 카렌을 탓하지 마세요. 모두 갑자기 나타난 제 잘못인걸요.",
  ui_story_5053_50530301_38_dialog_content = "참, 저도 하메스 공작님께 묻고 싶은 게 있었어요. 부인께서는 잘 지내시나요?",
  ui_story_5053_50530301_39_dialog_content = "부인 말인가? 잘 지내고 있네만.",
  ui_story_5053_50530301_40_dialog_content = "공작님의 손자분이 휴가를 신청할 때마다 항상\n공작부인께서 위독하다 해서 걱정이 되었거든요.",
  ui_story_5053_50530301_41_dialog_content = "잘 지내고 계신다면... 안심이에요.",
  ui_story_5053_50530301_42_dialog_content = "...그렇군, 마음 써 주어 고맙네.",
  ui_story_5053_50530301_43_dialog_content = "하메스 공작도 가끔은 가족을 더 살피는 시간을 갖는 게 좋겠군.",
  ui_story_5053_50530301_44_dialog_content = "베로니카 공주께서는 며칠 사이에 많이 바뀌셨군요.\n분명 기사단에서 다양한 경험을 하신 것이겠지요.",
  ui_story_5053_50530301_45_dialog_content = "그럴 수도 있겠지. 그저 그것을 가지고 자만하지 않았으면 좋겠는데 말이야.",
  ui_story_5053_50530301_46_dialog_content = "그게 무슨 말씀이십니까, 베로니카 공주만 그리 엄히 대하실 필요는 없지 않습니까.",
  ui_story_5053_50530301_47_dialog_content = "고마워요, 트로이 공작님. 하지만 아버님 말씀이 맞아요.\n전 앞으로도 계속 겸허한 마음으로 배워야만 해요.",
  ui_story_5053_50530301_48_dialog_content = "그렇습니까...\n아무래도 기사단 일이 공주의 성장에 정말 큰 도움이 된 모양입니다.",
  ui_story_5053_50530301_49_dialog_content = "축전이 곧 시작된다. 모두 자리에 앉도록 하지.",
  ui_story_5053_50530301_50_dialog_content = "언니, 아까 진짜 멋있었어! 원로원 할아범들 상대로도 하나도 안 무서워했잖아!",
  ui_story_5053_50530301_51_dialog_content = "헤헷, 그랬어? 사실 조금은 무서웠는데...",
  ui_story_5053_50530301_52_dialog_content = "카렌도 참 용감하네. 혼자 아버님이랑 퍼레이드에 나오고 말이야.",
  ui_story_5053_50530301_53_dialog_content = "아니... 사실 카렌은 어머님이랑 떨어지고 싶지 않았어...",
  ui_story_5053_50530301_54_dialog_content = "근데 마차를 탈 때 아버님께서 어머님이 아프시니까,\n카렌 혼자 축제에 참가하라고 하셔서...",
  ui_story_5053_50530301_55_dialog_content = "(그랬구나. 어머님은 우리랑 만나려고 아프다는 이유로\n카렌과 아버님을 떼어 놓으셨던 거구나.)",
  ui_story_5053_50530301_56_dialog_content = "(카렌의 마음엔 상처를 주고 말았지만... 그래도 이 모든 건 현실이 아냐. 괜찮아...)",
  ui_story_5053_50530301_57_dialog_content = "(중요한 건 대국이니까, 마음에 두지 말아야 하는데...\n...아니, 그런 건 난 역시 못 하겠어.)",
  ui_story_5053_50530301_58_dialog_content = "카렌, 우리 돌아가면 같이 어머님이랑 놀까?",
  ui_story_5053_50530301_59_dialog_content = "그래도 돼? 어머님 휴식에 방해가 되진 않을까?",
  ui_story_5053_50530301_60_dialog_content = "괜찮아. 어머님은 카렌을 가장 좋아하니까, 카렌이 곁에 있어주면 건강해지실 거야.",
  ui_story_5053_50530301_61_dialog_content = "카렌도 어머님이랑 언니가 너무 좋아! 아버님도 좋아!",
  ui_story_5053_50530301_62_dialog_content = "돌아가면 어머님께 과일도 드리고, 퍼레이드에서 있었던 일도 이야기할래!",
  ui_story_5053_50530301_63_dialog_content = "후훗, 역시 카렌은 참 착하다니까.",
  ui_story_5053_50530301_64_dialog_content = "(다행이야. 카렌이 다시 기운을 되찾았어.)",
  ui_story_5053_50530301_65_dialog_content = "뭔가 보입니까?",
  ui_story_5053_50530301_66_dialog_content = "미아가 관람석에 올라갔지만, 모습은 보이지 않아요...\n젊은 솔라드 씨가 연설을 준비하는 것 같아요.",
  ui_story_5053_50530301_67_dialog_content = "아직까진 「검은 천사」의 모습은 안 보이네요.",
  ui_story_5053_50530301_68_dialog_content = "여기는 시야가 너무 안 좋군요. 장소를 바꾸는 게 어떻습니까?",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>콰지지직!</color>",
  ui_story_5053_50530301_70_dialog_content = "이건...",
  ui_story_5053_50530301_71_dialog_content = "칼렙 씨, 장소를 바꿀 필요는 없을 것 같은데요...",
  ui_story_5053_50530301_72_dialog_content = "두 사람, 어서 피해라!",
  ui_story_5053_50530301_73_dialog_content = "여기... 있었구나...",
  ui_story_5053_50530302_1_dialog_content = "「솔라드 가문의 날」 축제의 개막을 선언한다!",
  ui_story_5053_50530302_2_dialog_content = "이어서 「결투 의식」을 거행한다.",
  ui_story_5053_50530302_3_dialog_content = "(왜 아직도 안 나타나는 거지...?)",
  ui_story_5053_50530302_4_dialog_content = "(다들 저 방향에 있어야 할 텐데... 왜 모습이 안 보이는 걸까...?)",
  ui_story_5053_50530302_5_dialog_content = "(설마... 「검은 천사」가 벌써 PlayerName 쪽을 습격했나?)",
  ui_story_5053_50530302_6_dialog_content = "(어떻게 하지? 무슨 핑계로 관람석을 내려가지?)",
  ui_story_5053_50530302_7_dialog_content = "언니, 뭐 찾고 있어?",
  ui_story_5053_50530302_8_dialog_content = "아, 아무것도 아냐... 카렌, 저기 봐.\n결투 의식이 시작됐어. 멋진 승부가 될 것 같아.",
  ui_story_5053_50530302_9_dialog_content = "언제쯤 카렌도 의식에 참가할 수 있을까...?\n카렌의 검술도 저 사람들보다 전혀 모자랄 게 없는데.",
  ui_story_5053_50530302_10_dialog_content = "어? 이상하네. 결투 중이던 경비병들이 왜 멈췄지?",
  ui_story_5053_50530302_11_dialog_content = "게다가 이쪽으로 오고 있어...",
  ui_story_5053_50530302_12_dialog_content = "무슨 특별한 연출이라도 있는 걸까?",
  ui_story_5053_50530302_13_dialog_content = "으음?",
  ui_story_5053_50530302_14_dialog_content = "(아버님도 의아해하시는 표정이잖아... 무슨 일인지 모르시는 것 같아.)",
  ui_story_5053_50530302_15_dialog_content = "(이 당시 나는 여기 없었으니까, 이때 무슨 일이 있었는진 알 수 없지만...\n지금 이건 분명히 뭔가 이상해.)",
  ui_story_5053_50530302_16_dialog_content = "......",
  ui_story_5053_50530302_17_dialog_content = "(설마...?!)",
  ui_story_5053_50530302_18_dialog_content = "...큰일이에요, 아버님! 암살 계획이 앞당겨졌어요!",
  ui_story_5053_50530302_19_dialog_content = "...어째서 네가 암살 일을 알고 있는 것이냐? 게다가... 앞당겨졌다고?",
  ui_story_5053_50530302_20_dialog_content = "그건... 말씀드리자면 얘기가 길어요...",
  ui_story_5053_50530302_21_dialog_content = "그대들이 여긴 왜 오는 것이냐! 여긴 그대들이 올 곳이 아니다!",
  ui_story_5053_50530302_22_dialog_content = "......",
  ui_story_5053_50530302_23_dialog_content = "무엄하다! 감히 공작인 내 물음에도 답하지 않다니!",
  ui_story_5053_50530302_24_dialog_content = "의도가 불순해 보이는군... 하메스 공작, 물러서시오!",
  ui_story_5053_50530302_25_dialog_content = "베로니카, 카렌을 지켜라!",
  ui_story_5053_50530302_26_dialog_content = "아버님! 위험해요!",
  ui_story_5053_50530302_27_dialog_content = "이야압!",
  ui_story_5053_50530302_28_dialog_content = "그까짓 실력으로 감히 내게 맞서려 하다니.",
  ui_story_5053_50530302_29_dialog_content = "「모든 것을 지배한다!」",
  ui_story_5053_50530302_30_dialog_content = "으윽...",
  ui_story_5053_50530302_31_dialog_content = "뭐냐, 그대도 한번 해 보고 싶은가?",
  ui_story_5053_50530302_32_dialog_content = "하압!",
  ui_story_5053_50530302_33_dialog_content = "받아라──!",
  ui_story_5053_50530302_34_dialog_content = "으윽...",
  ui_story_5053_50530302_35_dialog_content = "선 채로 내 검을 받다니... 말해라, 누가 보낸 것이냐!",
  ui_story_5053_50530302_36_dialog_content = "기다...려...",
  ui_story_5053_50530302_37_dialog_content = "이제 와서 용서를 구해봤자 늦었다!",
  ui_story_5053_50530302_38_dialog_content = "언니, 아버님이 왜 저 악당이랑 귓속말하시는 거야?",
  ui_story_5053_50530302_39_dialog_content = "아니야... 저건 아버님이 상대를 위협하고 있다기보다는...\n마치 상대가 아버님의 검을 붙잡고 있는 것 같잖아...",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>콰지직!</color>",
  ui_story_5053_50530302_41_dialog_content = "흐음?",
  ui_story_5053_50530302_42_dialog_content = "하...하하! 이제... 곧...",
  ui_story_5053_50530302_43_dialog_content = "저 사람... 얼굴이 왜 저렇게 일그러져 있지...?",
  ui_story_5053_50530302_44_dialog_content = "왜 다쳤는데 웃고 있는 거야? 이상한 사람이네...",
  ui_story_5053_50530302_45_dialog_content = "(어째서... 이런 힘이... <color=#FFB400>검을 뽑을 수가 없다니</color>!)",
  ui_story_5053_50530302_46_dialog_content = "그렇다면... 「모든 것을」...",
  ui_story_5053_50530302_47_dialog_content = "왔...다...",
  ui_story_5053_50530302_48_dialog_content = "아버님! 하늘을 보세요!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>크오오──!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "?!",
  ui_story_5053_50530302_51_dialog_content = "어, 엄청난 바람이야! 카렌이 날아갈 것 같아!",
  ui_story_5053_50530302_52_dialog_content = "카렌! 언니 여기 있어!",
  ui_story_5053_50530302_53_dialog_content = "...<color=#FFB400>드래곤</color>? 카르티마... 설마 여길 통째로 날려버릴 심산이었나?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>크아아아──!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "카렌, 베로니카!",
  ui_story_5053_50530302_56_dialog_content = "어서 도망쳐라! 빨리!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>콰아아앙──!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "아아악──!",
  ui_story_5053_50530401_2_dialog_content = "훗, 고작 그 정도냐!",
  ui_story_5053_50530401_3_dialog_content = "「씨앗」의 산물 주제에 감히 누나의 목소리로 날 속이려 하다니...",
  ui_story_5053_50530401_4_dialog_content = "누나가 맛본 고통을 그대로 갚아주마!",
  ui_story_5053_50530401_5_dialog_content = "하압──!",
  ui_story_5053_50530401_6_dialog_content = "......",
  ui_story_5053_50530401_7_dialog_content = "칼렙! 함부로 쫓아가선 안 된다!",
  ui_story_5053_50530401_8_dialog_content = "죽어버려!",
  ui_story_5053_50530401_9_dialog_content = "...아아악!",
  ui_story_5053_50530401_10_dialog_content = "뭐야?!",
  ui_story_5053_50530401_11_dialog_content = "칼렙 씨!",
  ui_story_5053_50530401_12_dialog_content = "칼...렙...?",
  ui_story_5053_50530401_13_dialog_content = "내 이름은 네가 멋대로 부를 수 있는 게 아니다...",
  ui_story_5053_50530401_14_dialog_content = "지금이에요!",
  ui_story_5053_50530401_15_dialog_content = "「모든 별이여! 흔들려라!」",
  ui_story_5053_50530401_16_dialog_content = "아아악...!",
  ui_story_5053_50530401_17_dialog_content = "다...니엘...",
  ui_story_5053_50530401_18_dialog_content = "다...",
  ui_story_5053_50530401_19_dialog_content = "주변이 원래대로 돌아왔어요!",
  ui_story_5053_50530401_20_dialog_content = "사라졌어...? 죽은 건가...",
  ui_story_5053_50530401_21_dialog_content = "...이상하군, 저쪽을 봐라.",
  ui_story_5053_50530401_22_dialog_content = "으아아악──!",
  ui_story_5053_50530401_23_dialog_content = "살려줘!",
  ui_story_5053_50530401_24_dialog_content = "광장에 있던 군중들이 도망치고 있다니... 설마 반란이 시작된 겁니까?",
  ui_story_5053_50530401_25_dialog_content = "이상해요... 우리가 개입하지 않으면, 반란은 암살 시도 다음에나 일어날 텐데요...",
  ui_story_5053_50530401_26_dialog_content = "아니...",
  ui_story_5053_50530401_27_dialog_content = "하늘을 봐라!",
  ui_story_5053_50530401_28_dialog_content = "크오오──!",
  ui_story_5053_50530401_29_dialog_content = "저건 카르티마 가문의 그 드래곤이잖아요?!",
  ui_story_5053_50530401_30_dialog_content = "드래곤이 어째서 성안에 있는 겁니까?",
  ui_story_5053_50530401_31_dialog_content = "세상에! 백야성 안에 어째서 저런 게...",
  ui_story_5053_50530401_32_dialog_content = "이럴 땐 너희 경비병들이 우릴 지켜야 하는 거 아냐? 뭘 멍하니 있어?!",
  ui_story_5053_50530401_33_dialog_content = "......",
  ui_story_5053_50530401_34_dialog_content = "잠깐만, 너, 너희... 뭘 하려는 거야?",
  ui_story_5053_50530401_35_dialog_content = "죽여라... 죽여라... 죽여라...",
  ui_story_5053_50530401_36_dialog_content = "으아악──",
  ui_story_5053_50530401_37_dialog_content = "「지배자의 칼날!」",
  ui_story_5053_50530401_38_dialog_content = "무기도 없는 백성을 습격하다니 기사의 이름이 부끄럽지 않느냐!\n카르티마 가문은 이미 그 정도까지 타락한 것이냐!",
  ui_story_5053_50530401_39_dialog_content = "...으......",
  ui_story_5053_50530401_40_dialog_content = "여, 여기 이 사람 아직 살아있어요!",
  ui_story_5053_50530401_41_dialog_content = "죽여...",
  ui_story_5053_50530401_42_dialog_content = "...뭐라고요?",
  ui_story_5053_50530401_43_dialog_content = "다...니엘...",
  ui_story_5053_50530401_44_dialog_content = "죽여라... 죽여라... 침입자를 죽여라!",
  ui_story_5053_50530401_45_dialog_content = "PlayerName, 어서 피해라!",
  ui_story_5053_50530401_46_dialog_content = "저, 저 사람 갑자기 왜 저런 거죠...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>콰아아앙──!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "어, 엄청난 진동이에요! 이번엔 또 뭐죠?",
  ui_story_5053_50530401_49_dialog_content = "관람석 쪽이 폭발했습니다!",
  ui_story_5053_50530401_50_dialog_content = "성주님이 습격당했다!",
  ui_story_5053_50530401_51_dialog_content = "어서 도망쳐!",
  ui_story_5053_50530401_52_dialog_content = "습격...? 미아!",
  ui_story_5053_50530401_53_dialog_content = "미아가 아직 관람석에 있었다면... 서, 설마... 말도 안 돼...",
  ui_story_5053_50530401_54_dialog_content = "누나는 아직 저택에 있어요! 반란군이 몰려간다면 누나는...",
  ui_story_5053_50530401_55_dialog_content = "PlayerName, 그대는 칼렙와 함께 돌아가라!",
  ui_story_5053_50530401_56_dialog_content = "만약 내가 미아를 데리고 그대들에게 돌아가지 않는다면...\n쟈키니에게 시간을 되돌리라고 해라. 결코 망설이지 마라!",
  ui_story_5053_50530401_57_dialog_content = "성주님!!!",
  ui_story_5053_50530401_58_dialog_content = "(대체 뭐가 어떻게 된 거야?! 설마 「영원한 기억의 수정」이 고장 난 건가?)",
  ui_story_5053_50530401_59_dialog_content = "(아니면 「검은 천사」가 아직 살아있고, 무슨 수를 쓴 건가...?)",
  ui_story_5053_50530401_60_dialog_content = "멍하니 있지 마세요! 포위를 돌파하는 게 먼저입니다!",
  ui_story_5053_50530401_61_dialog_content = "죽여라... 죽여라... 죽여라...",
  ui_story_5053_50530402_1_dialog_content = "하압!",
  ui_story_5053_50530402_2_dialog_content = "으윽...",
  ui_story_5053_50530402_3_dialog_content = "빌어먹을, 이 미쳐버린 역적들이... 노인이여, 도와주어 고맙군.",
  ui_story_5053_50530402_4_dialog_content = "공주들은 어디 있는가.",
  ui_story_5053_50530402_5_dialog_content = "공주들? 죽은 자를 신경 쓰느니 어떻게 살아남을지나 생각하는 게 좋을 거다.",
  ui_story_5053_50530402_6_dialog_content = "죽은 자라니? 그게 무슨 뜻이냐!",
  ui_story_5053_50530402_7_dialog_content = "...카렌, 베로니카 공주, 그리고 성주님은 드래곤의 공격을 정면으로 맞고...\n<color=#FFB400>이미 다 돌아가셨다!</color>",
  ui_story_5053_50530402_8_dialog_content = "...어디 있지? 베로니카 공주는 어디에 있냔 말이다!",
  ui_story_5053_50530402_9_dialog_content = "아직 관람석에 있을 거다.\n뭐냐, 설마 이런 상황에서 시신이라도 거두어 주겠다는 거냐?",
  ui_story_5053_50530402_10_dialog_content = "...고맙군.",
  ui_story_5053_50530402_11_dialog_content = "어리석긴... 이미 잃어버린 것에 미련을 가지면 자기 목숨만 버리게 될 뿐이다.",
  ui_story_5053_50530402_12_dialog_content = "누나!",
  ui_story_5053_50530402_13_dialog_content = "공작부인님! 쟈키니! 다들 어디 있어요?",
  ui_story_5053_50530402_14_dialog_content = "왜 아무 반응이 없는 거지... 누나!",
  ui_story_5053_50530402_15_dialog_content = "칼렙, 난 여기 있어.",
  ui_story_5053_50530402_16_dialog_content = "아... 무사했군요, 다행이에요... 또 누나를 잃어버리는 줄 알았잖아요...",
  ui_story_5053_50530402_17_dialog_content = "반란이 앞당겨졌어요. 지금 바로 누나를 안전한 곳으로 데려갈게요.",
  ui_story_5053_50530402_18_dialog_content = "쟈키니 씨는 어디 있죠? 이럴 때 멋대로 돌아다니다니...",
  ui_story_5053_50530402_19_dialog_content = "칼렙, 조급해하지 말고 하나씩 얘기해 줘.",
  ui_story_5053_50530402_20_dialog_content = "땀을 많이 흘렸구나. 옷도 다 구겨졌잖니. 이리 와, 내가 손봐줄게.",
  ui_story_5053_50530402_21_dialog_content = "네? 아, 그런 건 제가 해도...",
  ui_story_5053_50530402_22_dialog_content = "고, 고마워요, 누나.",
  ui_story_5053_50530402_23_dialog_content = "공작부인님은 무사하셨네요. 근데 쟈키니는 어디 갔죠?",
  ui_story_5053_50530402_24_dialog_content = "쟈키니! 어디 있어?!",
  ui_story_5053_50530402_25_dialog_content = "으윽...",
  ui_story_5053_50530402_26_dialog_content = "누...누나?",
  ui_story_5053_50530402_27_dialog_content = "왜 그러니? 칼렙.",
  ui_story_5053_50530402_28_dialog_content = "이, 이게 무슨...",
  ui_story_5053_50530402_29_dialog_content = "어...째서...",
  ui_story_5053_50530402_30_dialog_content = "칼렙 씨...? 가슴에 왜 상처가 있어요?!",
  ui_story_5053_50530402_31_dialog_content = "오다가 다친 건가요?!\n...아, 아니야... 대체 무슨...",
  ui_story_5053_50530402_32_dialog_content = "왜 다 커서도 여전히 바닥에 앉는 걸 좋아하는 걸까?",
  ui_story_5053_50530402_33_dialog_content = "넌 아직도 참 어린애 같구나, 칼렙.",
  ui_story_5053_50530402_34_dialog_content = "정말 실망스러워.",
  ui_story_5053_50530402_35_dialog_content = "어...째서...",
  ui_story_5053_50530402_36_dialog_content = "누...나...",
  ui_story_5053_50530402_37_dialog_content = "미아...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5053_50530402_39_dialog_content = "이 시간을 되돌릴 수 있다는 것은 알고 있다...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_5053_50530402_41_dialog_content = "허나 결코 네가 이런 일을 겪게 만들고 싶지는 않았다...",
  ui_story_5053_50530402_42_dialog_content = "난 너를 내 곁에서 떠나보내고, 네게 미움을 받더라도...\n그저 네가 무사히 살아갈 수만 있다면, 그것으로 족하다 여겼었다...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>..................</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>크오오──!</size>",
  ui_story_5053_50530402_45_dialog_content = "내 가족을 죽이고, 이젠 나도 죽이려 하는 것이냐.",
  ui_story_5053_50530402_46_dialog_content = "그대가 내 가족들에게 준 고통을 곱절로 갚아 주마...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>크아아아──!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>죽어라!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>또각, 또각...</color>",
  ui_story_5053_50530402_50_dialog_content = "(왜... 왜... 어째서... 대체 왜?!)",
  ui_story_5053_50530402_51_dialog_content = "(왜 공작부인님이 칼렙 씨를 죽인 거지? 자기 친동생이잖아!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>또각, 또각, 또각...</color>",
  ui_story_5053_50530402_53_dialog_content = "(설마 이 세계 사람들이 전부 미쳐버린 건가?)",
  ui_story_5053_50530402_54_dialog_content = "(아니면 내가 계속 악몽을 꾸고 있는 거야?!)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>또각, 또각, 또각, 또각...</color>",
  ui_story_5053_50530402_56_dialog_content = "(갔나?)",
  ui_story_5053_50530402_57_dialog_content = "(계속 테이블 밑에 숨어있을 수도 없고... 이제 어떡하지?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>또각, 또각.</color>",
  ui_story_5053_50530402_59_dialog_content = "(발소리가... 멈췄어?)",
  ui_story_5053_50530402_60_dialog_content = "찾.았.다~",
  ui_story_5053_50530402_61_dialog_content = "으악?!",
  ui_story_5053_50530402_62_dialog_content = "어머, 숨바꼭질 같은 건 카렌도 이젠 안 하는데 말이야.",
  ui_story_5053_50530402_63_dialog_content = "PlayerName 너도 이젠 어린애가 아니잖아.\n내가 얼마나 더 놀아주길 바라는 거야?",
  ui_story_5053_50530402_64_dialog_content = "하아... 하아...",
  ui_story_5053_50530402_65_dialog_content = "도망치지 마. 도망칠수록 네 죽음이 더 고통스러워질 뿐이야.",
  ui_story_5053_50530402_66_dialog_content = "미아, 칼렙... 정말 멋진 루미나를 가지고 있었구나.\n이렇게 힘이 넘쳤던 적은 처음이야.",
  ui_story_5053_50530402_67_dialog_content = "그럼... 아이테르의 루미나를 흡수하면 어떤 느낌일까?\n나도 다른 사람의 마음을 읽을 수 있게 되는 걸까?",
  ui_story_5053_50530402_68_dialog_content = "절대 그렇게 두지 않아!",
  ui_story_5053_50530402_69_dialog_content = "하긴, 이 세계에서 난 애초에 다른 사람을 조종할 수 있는걸.",
  ui_story_5053_50530402_70_dialog_content = "이 얼마나 단순한 관계니? 참 편하다니까.",
  ui_story_5053_50530402_71_dialog_content = "하아... 하아...",
  ui_story_5053_50530402_72_dialog_content = "(이 앞에는 문이 하나뿐이야. 막다른 골목이 아니었으면 좋겠는데!)",
  ui_story_5053_50530402_73_dialog_content = "거긴... 훗, 그게 바로 아이테르의 직감인 거구나.",
  ui_story_5053_50530402_74_dialog_content = "참 잘 고르네.",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5053_50530402_77_dialog_content = "쟈키니...?!",
  ui_story_5053_50530402_78_dialog_content = "(몸이 차가워... 숨도 안 쉬잖아...)",
  ui_story_5053_50530402_79_dialog_content = "죽을 자리를 아주 잘 골랐어, PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "북방의 점술사는 「영원한 기억의 수정」을 조종할 수 있잖아.\n그래서 제일 먼저 죽였어.",
  ui_story_5053_50530402_81_dialog_content = "아니면 뭐 하러 그 애만 남으라고 했겠어?",
  ui_story_5053_50530402_82_dialog_content = "...조슈아 씨, 정말 모르겠어요. 대체 왜 이런 짓을 하신 거죠?",
  ui_story_5053_50530402_83_dialog_content = "왜 쟈키니와 자기 동생... 그리고 절 죽여야 하는 건가요?",
  ui_story_5053_50530402_84_dialog_content = "그게 그렇게 이해가 어려워?\n난 너희 몸의 힘이 필요해.",
  ui_story_5053_50530402_85_dialog_content = "너희한테 원한은 없어. 이 모든 건 그저 필요한 희생일 뿐이야.",
  ui_story_5053_50530402_86_dialog_content = "...모르겠어요. 당신이 정말 조슈아 씨인 게 맞아요?",
  ui_story_5053_50530402_87_dialog_content = "당신... 대체 누구죠?",
  ui_story_5053_50530402_88_dialog_content = "내가 바로 조슈아야. 진짜 조슈아라고!",
  ui_story_5053_50530402_89_dialog_content = "눈 똑바로 뜨고 잘 봐 둬. 죽기 전에 내 모습을 영원히 기억하렴.",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>휘익──!</color>",
  ui_story_5053_50530402_91_dialog_content = "음...?",
  ui_story_5053_50530402_92_dialog_content = "PlayerName 씨... 빠, 빨리 저한테 와요...",
  ui_story_5053_50530402_93_dialog_content = "쟈키니?!",
  ui_story_5053_50530402_94_dialog_content = "살아 있었구나! 난 또 네가 벌써...",
  ui_story_5053_50530402_95_dialog_content = "잊었어요...? 전 어릴 적부터 각지를 여행한 점술사라구요...",
  ui_story_5053_50530402_96_dialog_content = "짐승 앞에서 죽은 척하는 정도는 식은 죽 먹기라구요... 콜록, 콜록...",
  ui_story_5053_50530402_97_dialog_content = "쟈키니!",
  ui_story_5053_50530402_98_dialog_content = "...다른 사람들은요?",
  ui_story_5053_50530402_99_dialog_content = "......",
  ui_story_5053_50530402_100_dialog_content = "다들...\n크읏... 말도 안 돼...!",
  ui_story_5053_50530402_101_dialog_content = "북방의 점술로 환각을 만들었던 건가...\n하긴, 그러니 「영원한 기억의 수정」 같은 것도 만들 수 있었겠지.",
  ui_story_5053_50530402_102_dialog_content = "참 역겨운 잔재주네.",
  ui_story_5053_50530402_103_dialog_content = "미안하지만 전 어렸을 때부터 말 잘 듣는 아이였거든요...!",
  ui_story_5053_50530402_104_dialog_content = "그럼 지금도 순순히 내 말을 들어!",
  ui_story_5053_50530402_105_dialog_content = "수정구슬아! 우릴 지켜줘!",
  ui_story_5053_50530402_106_dialog_content = "PlayerName 씨, 「영원한 기억의 수정」을 주세요.",
  ui_story_5053_50530402_107_dialog_content = "손을 수정 위에 놓으세요. 만약 제가 끝까지 못 버틴다 해도...",
  ui_story_5053_50530402_108_dialog_content = "절대 손 놓지 마세요.",
  ui_story_5053_50530402_109_dialog_content = "쟈키니... 알겠어!",
  ui_story_5053_50530402_110_dialog_content = "「레트로, 레트로, 레트로!」",
  ui_story_5053_50530402_111_dialog_content = "시간을 기점으로 되돌려 주세요...",
  ui_story_5053_50530402_112_dialog_content = "「아브라카다브라」... 으윽...!",
  ui_story_5053_50530402_113_dialog_content = "아...",
  ui_story_5053_50530402_114_dialog_content = "쟈키니! 쟈키니──!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>──두 번째 회귀 후──</color>",
  ui_story_5053_50530501_1_dialog_content = "성주 전하, 퍼레이드 준비를 마쳤습니다.",
  ui_story_5053_50530501_2_dialog_content = "마차는 이미 입구에서 대기하고 있습니다. 언제든지 출발하실 수 있습니다.",
  ui_story_5053_50530501_3_dialog_content = "......",
  ui_story_5053_50530501_4_dialog_content = "전하, 아직 공작부인님이 걱정되시나요?",
  ui_story_5053_50530501_5_dialog_content = "조슈아는 줄곧 건강했고, 몸이 불편함을 호소하는 일은 드물었다.\n특히 오늘 같은 특별한 날이라면 더욱 그러했지.",
  ui_story_5053_50530501_6_dialog_content = "공작부인께서는 최근 각 귀족 부인들에게 성주님의 정책을 전파하려고\n심혈을 기울여 오셨습니다.",
  ui_story_5053_50530501_7_dialog_content = "안심하십시오. 공작부인님은 제가 잘 모시겠습니다.",
  ui_story_5053_50530501_8_dialog_content = "아, 으으...",
  ui_story_5053_50530501_9_dialog_content = "(여긴...?)",
  ui_story_5053_50530501_10_dialog_content = "(잠깐만, 여기... 아직도 낮이잖아?)",
  ui_story_5053_50530501_11_dialog_content = "(도망치다가 여기서 쟈키니를 발견하고, 그다음엔...)",
  ui_story_5053_50530501_12_dialog_content = "(쟈키니, 날 지켜줬구나. 고마워...)",
  ui_story_5053_50530501_13_dialog_content = "(하지만 쟈키니는 지금 여기 없어. 설마 또 처음처럼 다른 곳에 떨어져 버린 건가?)",
  ui_story_5053_50530501_14_dialog_content = "(조슈아 부인은 대체 왜 우릴 공격한 걸까... 설마 진짜 조슈아 부인이 아닌 건가?)",
  ui_story_5053_50530501_15_dialog_content = "(쟈키니는 「영원한 기억의 수정」으로 조슈아 부인이 우리처럼\n<color=#FFB400>환영이 아닌 진짜 오로리안</color>인 걸 확인했어.)",
  ui_story_5053_50530501_16_dialog_content = "내가 바로 조슈아야. 진짜 조슈아라고.",
  ui_story_5053_50530501_17_dialog_content = "(자신을 진짜라고 강조한 건, 뭔가 다른 의미가 있는 걸까?)",
  ui_story_5053_50530501_18_dialog_content = "(전혀 모르겠어... 하지만 지금 가장 중요한 건...\n만약 정말 조슈아 부인이 문제가 있는 거면, 우린 대체 어떻게 여기서 나가지?)",
  ui_story_5053_50530501_19_dialog_content = "(으... 대체 이게 다 뭐냐고... 왜 나만 여기 있는 거야?!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>콰지직...</color>",
  ui_story_5053_50530501_21_dialog_content = "무슨 소리지? 저건...?!",
  ui_story_5053_50530501_22_dialog_content = "여기... 있었구나?",
  ui_story_5053_50530501_23_dialog_content = "「검은 천사」가 어떻게 쫓아온 거죠?! 우린 시간을 돌렸잖아요!",
  ui_story_5053_50530501_24_dialog_content = "누, 누나 목소리야...",
  ui_story_5053_50530501_25_dialog_content = "여기... 있었구나!",
  ui_story_5053_50530501_26_dialog_content = "「백야! 비호를!」",
  ui_story_5053_50530501_27_dialog_content = "칼렙, 전장에서 쓸데없는 생각은 금물이다!",
  ui_story_5053_50530501_28_dialog_content = "──!",
  ui_story_5053_50530501_29_dialog_content = "「지배자의 칼날!」",
  ui_story_5053_50530501_30_dialog_content = "당신을... 증오해...",
  ui_story_5053_50530501_31_dialog_content = "으윽!",
  ui_story_5053_50530501_32_dialog_content = "공격이 빨라...! 성주님! 조심하세요!",
  ui_story_5053_50530501_33_dialog_content = "그대는 그토록 나와 싸우고 싶은 것인가?",
  ui_story_5053_50530501_34_dialog_content = "원한다면 들어주도록 하지.",
  ui_story_5053_50530501_35_dialog_content = "다...니엘...!",
  ui_story_5053_50530501_36_dialog_content = "(다들 또 「검은 천사」랑 싸우고 있어... 시간은 확실히 처음으로 돌아갔어!)",
  ui_story_5053_50530501_37_dialog_content = "(일단 모두를 도와야 해!)",
  ui_story_5053_50530501_38_dialog_content = "...여기, 있었군.",
  ui_story_5053_50530501_39_dialog_content = "경비병? 마침 잘...",
  ui_story_5053_50530501_40_dialog_content = "수상한 인물... 처리한다...",
  ui_story_5053_50530501_41_dialog_content = "(어? 이 사람들... 뭔가 이상한데?!)",
  ui_story_5053_50530501_42_dialog_content = "뭐라고요?",
  ui_story_5053_50530501_43_dialog_content = "조슈아 부인... 누군가가... 침입했습니다...",
  ui_story_5053_50530501_44_dialog_content = "침입자를 잡아라... 죽여라... 잡아라... 죽여라!",
  ui_story_5053_50530501_45_dialog_content = "(이 사람들도 이성을 잃은 것 같은데... 광장에 있던 사람들이랑 똑같잖아?!)",
  ui_story_5053_50530501_46_dialog_content = "아아아악!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5053_50530502_2_dialog_content = "으윽... 큭...",
  ui_story_5053_50530502_3_dialog_content = "「검은 천사」는 어디 갔습니까?",
  ui_story_5053_50530502_4_dialog_content = "바깥의 오솔길을 따라 도망친 것 같아요...",
  ui_story_5053_50530502_5_dialog_content = "성주님의 방금 그 공격, 정말 하늘도 땅도 다 갈라버릴 것 같았어요!",
  ui_story_5053_50530502_6_dialog_content = "「검은 천사」가 아무리 강해도, 이번엔 분명히 큰 타격을 입었을 거예요.\n아마 멀리 도망가진 못했겠죠?",
  ui_story_5053_50530502_7_dialog_content = "......",
  ui_story_5053_50530502_8_dialog_content = "외삼촌, 그 「검은 천사」가 신경 쓰이시는 건가요?",
  ui_story_5053_50530502_9_dialog_content = "저 목소리는 확실히... 아니, 됐어요. 누나가 괴물일 리가 없잖아요.",
  ui_story_5053_50530502_10_dialog_content = "잠깐만요, 자꾸 뭔가 빠트린 것 같은 느낌이 드는데...\n아, 혹시 PlayerName 못 보셨나요?",
  ui_story_5053_50530502_11_dialog_content = "아, 맞네요! PlayerName 씨는 또 어딜 간 거예요?!",
  ui_story_5053_50530502_12_dialog_content = "어머, 다들 여기 있었구나.",
  ui_story_5053_50530502_13_dialog_content = "하아... 하아... 따돌렸나?",
  ui_story_5053_50530502_14_dialog_content = "저기다... 저기 있다!",
  ui_story_5053_50530502_15_dialog_content = "잡아라... 죽여라... 침입자!",
  ui_story_5053_50530502_16_dialog_content = "(제길! 저 경비병들, 정신은 이상한 주제에 엄청 끈질기네!)",
  ui_story_5053_50530502_17_dialog_content = "아니지, 그래, 저기다...!",
  ui_story_5053_50530502_18_dialog_content = "(...아, 찾았다!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_5053_50530502_20_dialog_content = "(이건... 물자 수송 마차인가? 축제 준비에 쓰는 것 같은데...\n여기라면 녀석들도 못 찾겠지.)",
  ui_story_5053_50530502_21_dialog_content = "저긴, 없다... 다른 곳을...",
  ui_story_5053_50530502_22_dialog_content = "저... 거리로 가자...",
  ui_story_5053_50530502_23_dialog_content = "음? 누굴 찾고 있는 거지? 어째 상태가 좀 이상해 보이는데...",
  ui_story_5053_50530502_24_dialog_content = "그러게요. 설마 오늘 같은 날 소란 피우는 사람이 있겠어요?\n게다가 이제 곧 퍼레이드도 시작될 거고 말이에요.",
  ui_story_5053_50530502_25_dialog_content = "정말 기대되네요~",
  ui_story_5053_50530502_26_dialog_content = "(휴... 일단은 따돌린 것 같네...)",
  ui_story_5053_50530502_27_dialog_content = "(아까 지나가던 사람들이 말한 걸 보면... 아직 퍼레이드 시작 전인 것 같은데?)",
  ui_story_5053_50530502_28_dialog_content = "(시간이 좀 있겠어. 다시 한번 상황을 정리해 보자.)",
  ui_story_5053_50530502_29_dialog_content = "(확실히 생각해 볼 문제들이 몇 개 있어...)",
  ui_story_5053_50530502_30_option_content = "(현재 상황은...)",
  ui_story_5053_50530502_31_dialog_content = "(지금은 아직 퍼레이드가 시작되기 전이야. 그럼 다들 이미 조슈아 부인을 만났겠지.)",
  ui_story_5053_50530502_32_dialog_content = "(앞으로 일어날 수 있는 상황은 두 가지...\n중요한 건 <color=#FFB400>다들 두 번째 시간 회귀 전까지 있었던 일을 기억하고 있는지</color>야.)",
  ui_story_5053_50530502_33_dialog_content = "(만약 이전 기억이 있다면, 지금쯤 조슈아 부인이랑 싸우고 있거나 도망치고 있겠지...)",
  ui_story_5053_50530502_34_dialog_content = "(그런 상황이라면 분명히 다들 날 찾고 있을 거야.\n그리고 난 백야성의 지리에 익숙하지 않으니까, 섣불리 움직이지 않는 편이 좋아.)",
  ui_story_5053_50530502_35_dialog_content = "(만약 이전 기억이 없다면, 아마 이번에도 또 조슈아 부인의 함정에 빠졌을 거야...)",
  ui_story_5053_50530502_36_dialog_content = "(시간을 되돌리기 전처럼 쟈키니만 남고 다른 사람들은 광장으로 향하겠지.)",
  ui_story_5053_50530502_37_dialog_content = "(지금 난 광장 근처에 있어. 그럼 여기서 다들 오길 기다리는 게 최선의 선택일 거야.)",
  ui_story_5053_50530502_38_dialog_content = "(그럼 쟈키니는... 젠장! 지금으로선 모두와 합류한 뒤에 쟈키니를 구하러 가는 수밖에 없어!)",
  ui_story_5053_50530502_39_option_content = "(「기억」...)",
  ui_story_5053_50530502_40_dialog_content = "(쟈키니는 점술을 사용할 때 반드시 <color=#FFB400>엄격하게 규칙을 지켜야 한다</color>고 했어.)",
  ui_story_5053_50530502_41_dialog_content = "(그리고 처음 시간을 되돌릴 땐 <color=#FFB400>꼭 서로 손을 잡아야 한다</color>고 했었고 말이야.)",
  ui_story_5053_50530502_42_dialog_content = "(근데 조슈아 부인은 처음 시간을 되돌렸을 때 우리랑 같이 있었고,\n그래서 첫 번째 시간 회귀 이전의 일을 기억한다고 말했어.)",
  ui_story_5053_50530502_43_dialog_content = "(그럼 첫 회귀 때 조슈아 부인도 몰래 우리 손을 잡았던 걸까?\n그래서 기억이 남았던 건가?)",
  ui_story_5053_50530502_44_dialog_content = "(만약 그런 거라면, 두 번째 회귀 때 「영원한 기억의 수정」을 잡은 건\n나랑 쟈키니뿐이었으니까...)",
  ui_story_5053_50530502_45_dialog_content = "(조슈아 부인이나 다른 사람들은 전부 두 번째 회귀 이전의 일은 모를 수도 있지 않을까?)",
  ui_story_5053_50530502_46_dialog_content = "(그럼 이 모든 진상을 아는 사람은 나랑 쟈키니뿐이게 되는 건가...)",
  ui_story_5053_50530502_47_dialog_content = "(그랬으면 좋겠지만...)",
  ui_story_5053_50530502_48_option_content = "(경비병, 드래곤, 「검은 천사」...)",
  ui_story_5053_50530502_49_dialog_content = "(저 경비병들은 왜 날 잡으려고 하는 거지?)",
  ui_story_5053_50530502_50_dialog_content = "(저 사람들 표정, 광장에서 소란을 피웠던 사람들이랑 비슷했어.\n꼭 무슨 병에 걸렸거나... 아니면 누군가한테 조종당하는 것 같았어.)",
  ui_story_5053_50530502_51_dialog_content = "(경비병들은 마치 날 다른 사람들이랑 떼어놓으려는 것처럼 계속 쫓아다녀서\n내가 저택에서 멀어지게 만들었어.)",
  ui_story_5053_50530502_52_dialog_content = "(「영원한 기억의 수정」 속에서 난 감응 능력을 사용할 수 없어.\n그래서 다들 정원에서 싸우는 동안 위층의 일도 눈치채지 못했어.)",
  ui_story_5053_50530502_53_dialog_content = "(그 때문에 나도 모두랑 합류할 기회를 놓쳤고...)",
  ui_story_5053_50530502_54_dialog_content = "(만약 조슈아 부인이 기억하고 있다면, 저 추격병들은 날 죽여서 입을 막으려는 거겠지.)",
  ui_story_5053_50530502_55_dialog_content = "(기억하지 못한다면, 아마 무리에서 벗어난 사람부터 죽일 생각일 거야.)",
  ui_story_5053_50530502_56_dialog_content = "(맞아. 맨 처음에 쟈키니를 우리랑 떨어지게 만든 것처럼.)",
  ui_story_5053_50530502_57_dialog_content = "(「검은 천사」와의 싸움도 아마 조슈아 부인이 판을 짜둔 거겠지.\n우릴 흩어지게 만들고 쟈키니를 먼저 죽이려고 말이야.)",
  ui_story_5053_50530502_58_dialog_content = "(날 쫓아오는 경비병을 조슈아 부인이 보낸 거라면...)",
  ui_story_5053_50530502_59_dialog_content = "(광장의 미쳐버린 사람들도, 그 검은 드래곤도 조슈아 부인이 계획한 걸지도 몰라.)",
  ui_story_5053_50530502_60_dialog_content = "(그럼 첫 회귀 이후로 일어난 모든 게 전부 그 사람이 꾸민 일이라는 얘기가 돼...\n그게 진짜라면 정말 소름 끼치게 무서운 일이잖아.)",
  ui_story_5053_50530502_61_dialog_content = "(근데 「검은 천사」는? 조슈아 부인이랑 대체 무슨 관계인 거지?)",
  ui_story_5053_50530502_62_dialog_content = "(설마 모든 게 그 둘이 짜고 꾸민 연극일까? 아니면 다른 진상이 숨어 있는 걸까...?)",
  ui_story_5053_50530502_63_dialog_content = "(이 문제는 아직 정보가 너무 부족해.)",
  ui_story_5053_50530502_64_dialog_content = "(휴... 잔뜩 생각해 봤지만 결국 지금 내가 할 수 있는 건\n여기서 모두가 오길 기다리는 것뿐이야...)",
  ui_story_5053_50530502_65_dialog_content = "(모두와 합류한 뒤에 진상을 말해주고, 다 같이 쟈키니를 구하러 가야 해...)",
  ui_story_5053_50530502_66_dialog_content = "(다들 꼭 무사해야 할 텐데...)",
  ui_story_5053_50530601_1_dialog_content = "그러니까 다시 말해서...",
  ui_story_5053_50530601_2_dialog_content = "우리가 「검은 천사」를 쓰러트리고, 공작부인님을 데리고 여길 떠나거나.",
  ui_story_5053_50530601_3_dialog_content = "아니면 우리가 「검은 천사」의 손에 죽고,\n괴물이 현실 세계에서 부활하게 만들거나...인 거죠?",
  ui_story_5053_50530601_4_dialog_content = "그래, 맞아.",
  ui_story_5053_50530601_5_dialog_content = "......",
  ui_story_5053_50530601_6_dialog_content = "탈출 계획은 이해했어요. 근데...",
  ui_story_5053_50530601_7_dialog_content = "PlayerName 씨는 어디 간 거죠? 엄청 걱정된다구요.",
  ui_story_5053_50530601_8_dialog_content = "오래 떨어져 있을수록 무슨 일이 생길지 모르잖아요.",
  ui_story_5053_50530601_9_dialog_content = "그 아이의 상황은 나도 잘 모르겠어.\n대신 경비병을 보내서 찾게 할 테니까 너무 걱정하지 말렴.",
  ui_story_5053_50530601_10_dialog_content = "지금 우리에게 주어진 시간은 한정돼 있어.\n모두가 무사히 나가려면 우선 저 괴물부터 쓰러트려야 한다고 생각해.",
  ui_story_5053_50530601_11_dialog_content = "그럼 얼른 다 같이 「검은 천사」를 처치하러 가요!",
  ui_story_5053_50530601_12_dialog_content = "아니, 쟈키니는 나와 함께 여기 남아줘.",
  ui_story_5053_50530601_13_dialog_content = "어? 왜요? 제 수정구슬도 전투에서 큰 도움이 된다구요!",
  ui_story_5053_50530601_14_dialog_content = "응, 알고 있어. 하지만 넌 「영원한 기억의 수정」을 조종해야 하잖니.",
  ui_story_5053_50530601_15_dialog_content = "만약 다른 사람에게 무슨 일이 생긴다면,\n시간을 되돌려서 원래 상태로 되돌릴 수 있을 거야.",
  ui_story_5053_50530601_16_dialog_content = "하지만 너한테 무슨 일이 생기면 돌이킬 수 없게 돼...",
  ui_story_5053_50530601_17_dialog_content = "그, 그것도 그렇네요...",
  ui_story_5053_50530601_18_dialog_content = "저, 저기... 어머님과 쟈키니가 여기 남는다면 카렌도 불러오는 게 좋을 것 같아요.",
  ui_story_5053_50530601_19_dialog_content = "어머님도 저도 없이 아버님이랑만 있으면 그 앤 분명히 외로울 거예요.\n그러면 조금 가엾잖아요...",
  ui_story_5053_50530601_20_dialog_content = "그래. 그럼 이따가 하인을 보내서 방에 돌아가 쉬고 있으라고 할게.",
  ui_story_5053_50530601_21_dialog_content = "어머님 곁에 함께 두지 않으시는 건가요...?\n줄곧 기대하고 있었던 날인데, 그냥 방으로 가라고 하시면...",
  ui_story_5053_50530601_22_dialog_content = "카렌은 오래전부터 퍼레이드를 기다려 왔어요.\n어머님 곁에 있을 수 없다면 속상해할 거예요...",
  ui_story_5053_50530601_23_dialog_content = "로니, 「영원한 기억의 수정」 속 모든 건 환상일 뿐이야. 진짜가 아니란다.",
  ui_story_5053_50530601_24_dialog_content = "우린 대국을 더 중요하게 생각해야 해.\n사소한 일 때문에 우리의 가장 중요한 목적이 영향을 받게 해선 안 돼.",
  ui_story_5053_50530601_25_dialog_content = "으음...",
  ui_story_5053_50530601_26_dialog_content = "누나 말이 맞아요. 여기서 일어나는 일은 모두 환상일 뿐이에요.\n미아, 감정적으로 행동해선 안 돼요.",
  ui_story_5053_50530601_27_dialog_content = "아, 알겠어요. 죄송해요... 제가 아직 미숙한 탓이에요...",
  ui_story_5053_50530601_28_dialog_content = "......",
  ui_story_5053_50530601_29_dialog_content = "조슈아의 말에도 일리가 있다. 가장 중요한 것은 모두의 안전이다.\n그렇다면 칼렙도 남는 게 좋겠군.",
  ui_story_5053_50530601_30_dialog_content = "PlayerName 쪽은 내가 직접 찾도록 하지. 모두가 무사히 모이도록 하는 것이 먼저다.",
  ui_story_5053_50530601_31_dialog_content = "당신이 시간을 쓸 필요는 없어요. 경비병을 보내서 찾아도 되잖아요.",
  ui_story_5053_50530601_32_dialog_content = "하지만 저 괴물은 모두가 힘을 모으지 않으면 이길 가능성은 낮아요.",
  ui_story_5053_50530601_33_dialog_content = "어느 쪽 일이 더 중요한지 당신이라면 판단할 수 있을 거라 믿어요.\n이성적으로 생각해요, 다니엘.",
  ui_story_5053_50530601_34_dialog_content = "그대는 여전히 이해타산에 밝군.\n그 말을 들으니 그 옛날 우리의 첫 만남이 떠오르는군그래.",
  ui_story_5053_50530601_35_dialog_content = "......",
  ui_story_5053_50530601_36_dialog_content = "지금이 부부싸움 할 시간은 아니지 않습니까?\n애초부터 우린 지금 시간이 없단 말입니다.",
  ui_story_5053_50530601_37_dialog_content = "내가 무엇을 해야 할지는 누구보다 스스로 잘 알고 있다.\n다른 이의 안배는 필요 없다.",
  ui_story_5053_50530601_38_dialog_content = "미아, 가자.",
  ui_story_5053_50530601_39_dialog_content = "아, 알겠습니다. 아버님...",
  ui_story_5053_50530601_40_dialog_content = "뭡니까? 저 사람! 갑자기 혼자 이상하게 굴고...",
  ui_story_5053_50530601_41_dialog_content = "......",
  ui_story_5053_50530601_42_dialog_content = "미아, 조슈아의 일로 마음이 좋지 않은 것이냐.",
  ui_story_5053_50530601_43_dialog_content = "아, 그게, 음... 확실히 조금 그래요...",
  ui_story_5053_50530601_44_dialog_content = "아마 제 자신의 문제일 거예요...\n떨어져 있던 시간이 길어서 그런지... 어머님이 왠지 멀게 낯설게 느껴졌어요...",
  ui_story_5053_50530601_45_dialog_content = "그렇다면 네가 생각하는 네 어머니 조슈아는 어떤 사람이지?",
  ui_story_5053_50530601_46_dialog_content = "어머님은... 제가 본 사람 중에 가장 상냥하고, 너그럽고...\n누구보다도 아이들을 사랑해 주시는 분이에요.",
  ui_story_5053_50530601_47_dialog_content = "음. 내가 아는 조슈아 또한 햇살처럼 다정하면서도,\n굳은 의지와 진실한 마음, 과감한 결단력을 지닌 여인이다.",
  ui_story_5053_50530601_48_dialog_content = "아버님...!",
  ui_story_5053_50530601_49_dialog_content = "미아, 스스로를 더 믿어주어라.\n그리고 네 마음속 그 상냥하고 강인한 어머니를 믿어라.",
  ui_story_5053_50530601_50_dialog_content = "스스로를 더 믿는 건가요...",
  ui_story_5053_50530601_51_dialog_content = "비록 네게는 여전히 서툰 점이 있으나, 이번일과 같은 예상 밖의 상황에서\n너는 네 강인함과 용감한 면모를 충분히 보여주었다.",
  ui_story_5053_50530601_52_dialog_content = "이제 네 성장을 인정해야 할 때가 온 것 같구나.",
  ui_story_5053_50530601_53_dialog_content = "앞으로는 나도 네게 섣불리 간섭하지 않고, 네 의견을 존중할 것이다.",
  ui_story_5053_50530601_54_dialog_content = "네 어머니나 카렌, 그리고 다른 어떠한 일도 더는 두려워할 필요가 없다.",
  ui_story_5053_50530601_55_dialog_content = "네가 옳다고 여기는 길을 용감히 걸어가거라. 나는 너를 믿는다.",
  ui_story_5053_50530601_56_dialog_content = "(아버님이... 날 격려해 주시는 거야?)",
  ui_story_5053_50530601_57_dialog_content = "(이런 말을 해 주신 적은 한 번도 없었는데... 왠지... 무척 기쁜걸...)",
  ui_story_5053_50530601_58_dialog_content = "고마워요, 아버님. 더 용감해질 수 있게 노력할게요.",
  ui_story_5053_50530601_59_dialog_content = "그럼 아까 작전대로 전 관람석에 가 볼게요.\n「검은 천사」를 발견하면 곧바로 말씀드릴게요.",
  ui_story_5053_50530601_60_dialog_content = "알겠다, 미아. 조심하거라.",
  ui_story_5053_50530601_61_dialog_content = "(미아 쪽은 당분간 문제가 없을 것이다. 허나 PlayerName 그대는\n이러한 상황에서 어딜 간 것이냐.)",
  ui_story_5053_50530601_62_dialog_content = "(그의 실종에 강렬한 위화감이 느껴지는군. 대체...)",
  ui_story_5053_50530601_63_dialog_content = "여...기...",
  ui_story_5053_50530601_64_dialog_content = "여기... 있었구나!",
  ui_story_5053_50530601_65_dialog_content = "(이 목소리는...)",
  ui_story_5053_50530601_66_dialog_content = "다...니...엘...!",
  ui_story_5053_50530601_67_dialog_content = "아아아악──!",
  ui_story_5053_50530601_68_dialog_content = "설마 이런 곳에 나타날 줄이야.",
  ui_story_5053_50530601_69_dialog_content = "뭐, 적어도 다른 이들에게 해를 입히진 않겠군.",
  ui_story_5053_50530601_70_dialog_content = "아파... 죽여... 죽여버릴 거야...!",
  ui_story_5053_50530601_71_dialog_content = "조슈아의 목소리로 날 현혹할 생각 따위는 마라.",
  ui_story_5053_50530701_1_dialog_content = "으... 아아!",
  ui_story_5053_50530701_2_dialog_content = "(미아와 칼렙이 없는 지금, 전력은 막상막하로 보이는군.\n다만, 암귀의 수가 적지 않다는 점은 전황에 영향을 줄 것이다.)",
  ui_story_5053_50530701_3_dialog_content = "「백야! 비호를!」",
  ui_story_5053_50530701_4_dialog_content = "나와 거의 호각을 이루고 있군. 이제 만족하는가?",
  ui_story_5053_50530701_5_dialog_content = "다...니...엘...!",
  ui_story_5053_50530701_6_dialog_content = "당...신을... 증오...해...!",
  ui_story_5053_50530701_7_dialog_content = "어...째서...",
  ui_story_5053_50530701_8_dialog_content = "괴...로...워! 왜... 날... 배신했어!",
  ui_story_5053_50530701_9_dialog_content = "함께... 미래를... 만들자고... 당신이...그랬...잖아! 당신이...!",
  ui_story_5053_50530701_10_dialog_content = "어...째...서... 가족을...... 날... 희생시킨... 거야!",
  ui_story_5053_50530701_11_dialog_content = "아...파...!",
  ui_story_5053_50530701_12_dialog_content = "대체 무슨 소리를 하는 것이냐.",
  ui_story_5053_50530701_13_dialog_content = "진...작... 이럴... 줄... 알았다면...",
  ui_story_5053_50530701_14_dialog_content = "당신에게... 마...음을... 갖지... 말았어야...",
  ui_story_5053_50530701_15_dialog_content = "당...신을... 선택...하지... 말았...어야... 했어!",
  ui_story_5053_50530701_16_dialog_content = "?!",
  ui_story_5053_50530701_17_dialog_content = "조슈아...?!",
  ui_story_5053_50530701_18_dialog_content = "어찌 이런 일이 가능하단 말이냐...",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "아...! 베로...니카가... 위험...해...",
  ui_story_5053_50530701_21_dialog_content = "어딜 가는 것이냐!",
  ui_story_5053_50530701_22_dialog_content = "크오오──!",
  ui_story_5053_50530701_23_dialog_content = "괘씸한 놈들! 방해된다!",
  ui_story_5053_50530701_24_dialog_content = "(젊은 솔라드 씨의 연설이 끝났어. 이제 곧 결투 의식이 시작될 거야...)",
  ui_story_5053_50530701_25_dialog_content = "(사건이 발생한 시간대로 보면, 이제 곧 드래곤이 나타날 거고,\n사람들과 병사들이 다 같이 미쳐버리겠지...)",
  ui_story_5053_50530701_26_dialog_content = "(그 혼란을 틈타서 관람석에 올라가면 될 거야!\n반드시 모두와 합류해서 조슈아 부인에 대한 일을 말해줘야 해!)",
  ui_story_5053_50530701_27_dialog_content = "크오오──!",
  ui_story_5053_50530701_28_dialog_content = "꺄아아아악!",
  ui_story_5053_50530701_29_dialog_content = "저, 저게 뭐야?!",
  ui_story_5053_50530701_30_dialog_content = "살려줘! 빠, 빨리 도망쳐!",
  ui_story_5053_50530701_31_dialog_content = "(좋아! 이 틈을 타서 단번에 성주님 쪽에 합류해서──)",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5053_50530701_33_dialog_content = "뭐야...! 저, 저건?!",
  ui_story_5053_50530701_34_dialog_content = "크오오──!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>콰아앙!!!</color>",
  ui_story_5053_50530701_36_dialog_content = "아...! 아아악!",
  ui_story_5053_50530701_37_dialog_content = "(대체 어떻게 된 거야? 저거 「검은 천사」잖아?)",
  ui_story_5053_50530701_38_dialog_content = "(공중에서 뭘 하고 있는 거지? 드래곤의 공격을 막는 건가?)",
  ui_story_5053_50530701_39_dialog_content = "드래곤인가?!",
  ui_story_5053_50530701_40_dialog_content = "드래곤 만세! 드래곤 만세!",
  ui_story_5053_50530701_41_dialog_content = "반란군... 카르티마 가문인가?",
  ui_story_5053_50530701_42_dialog_content = "이럴 때 모습을 드러내다니, 대단한 배짱이로군.",
  ui_story_5053_50530701_43_dialog_content = "(하지만 저 공중의 검은 괴물은 대체...)",
  ui_story_5053_50530701_44_dialog_content = "어, 언니... 이게 무슨 일이야...?",
  ui_story_5053_50530701_45_dialog_content = "카렌, 내 뒤에 숨어!",
  ui_story_5053_50530701_46_dialog_content = "(저건 「검은 천사」잖아... 어떻게 된 거지?)",
  ui_story_5053_50530701_47_dialog_content = "이게 대체 무슨...",
  ui_story_5053_50530701_48_dialog_content = "베로니카, 카렌, 물러서라!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>퍼어엉──</color>",
  ui_story_5053_50530701_50_dialog_content = "(드래곤의 화염에 맞았어... 아니, 아니야. 검은 천사가 드래곤의 화염을 막아준 거야...)",
  ui_story_5053_50530701_51_dialog_content = "(하지만 대체 왜...?)",
  ui_story_5053_50530701_52_dialog_content = "언니... 저 괴물이 우리 대신 드래곤의 공격을 막아준 것 같아!",
  ui_story_5053_50530701_53_dialog_content = "기, 기절한 것 같은데?",
  ui_story_5053_50530701_54_dialog_content = "(정말 모르겠어... 왜 「검은 천사」가...)",
  ui_story_5053_50530701_55_dialog_content = "미아!",
  ui_story_5053_50530701_56_dialog_content = "미아! 괜찮아?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? 난 괜찮아. 걱정마... 근데 왜 여기 있어?",
  ui_story_5053_50530701_58_dialog_content = "여, 여기... 있다...!",
  ui_story_5053_50530701_59_dialog_content = "죽여라... 죽여라... 침입자를 죽여라!",
  ui_story_5053_50530701_60_dialog_content = "제길! 또 저 녀석들이야?!",
  ui_story_5053_50530701_61_dialog_content = "저 경비병들... 왠지 상태가 이상해 보이는데?!",
  ui_story_5053_50530701_62_dialog_content = "드래곤 만세! 드래곤 만세!",
  ui_story_5053_50530701_63_dialog_content = "돌격하라!",
  ui_story_5053_50530701_64_dialog_content = "PlayerName! 조심해! 반란군이 달려오고 있어!",
  ui_story_5053_50530701_65_dialog_content = "미아, 자세한 건 나중에 얘기할게.\n지금은 상황이 안 좋으니까 일단 싸우자!",
  ui_story_5053_50530701_66_dialog_content = "드래곤이든, 검은 괴물이든 좋다.\n감히 오늘 같은 날에 솔라드 가문의 권위에 도전하다니!",
  ui_story_5053_50530701_67_dialog_content = "크오오!",
  ui_story_5053_50530701_68_dialog_content = "조심하게! 일단 「검은 천사」는 상관하지 말게.",
  ui_story_5053_50530701_69_dialog_content = "지금까지의 적과는 다를 테니, 단숨에 쓰러트릴 생각은 거두는 게 좋을 것이네.",
  ui_story_5053_50530701_70_dialog_content = "그대는 또 누구인가...?",
  ui_story_5053_50530701_71_dialog_content = "힘을 모아 나와 함께 드래곤을 상대하게!",
  ui_story_5053_50530701_72_dialog_content = "고작 드래곤 따위.",
  ui_story_5053_50530701_73_dialog_content = "「백야의 빛이여!」",
  ui_story_5053_50530701_74_dialog_content = "그어어── 크오오!",
  ui_story_5053_50530701_75_dialog_content = "(아니?! 목구멍을 뚫은 상처가 곧바로 나은 건가?!)",
  ui_story_5053_50530701_76_dialog_content = "빠른 치유 능력인가... 아니면... 「불사성」을 지닌 것이란 말인가...?",
  ui_story_5053_50530701_77_dialog_content = "(그럴 리가, 대체 누가 저런 막강한 힘을 부여할 수 있단 말이냐. 설마 마임 그자가?)",
  ui_story_5053_50530701_78_dialog_content = "......",
  ui_story_5053_50530701_79_dialog_content = "조심하게. 다음 공격이 곧 올 테니.",
  ui_story_5053_50530801_1_dialog_content = "으으... 하아... 하아아...",
  ui_story_5053_50530801_2_dialog_content = "죽여라... 죽여라, 죽여라... 침입자를... 죽여라!",
  ui_story_5053_50530801_3_dialog_content = "죽여라아아아아!",
  ui_story_5053_50530801_4_dialog_content = "미쳐버린 경비병들이 더 많아졌잖아! 미아, 버틸 수 있겠어?",
  ui_story_5053_50530801_5_dialog_content = "너무 끔찍해... 전부 눈이 하얗게 변했고, 표정도 정말 이상해...",
  ui_story_5053_50530801_6_dialog_content = "...난 괜찮아. 하지만 지금도 적이 점점 더 많아지고 있어!",
  ui_story_5053_50530801_7_dialog_content = "방금 전까지 도망치던 평민이 얼마 뒤엔 저들과 한패가 돼 있어...\n그리고 이미 쓰러트렸던 반란군들까지...",
  ui_story_5053_50530801_8_dialog_content = "마치 전염병처럼...",
  ui_story_5053_50530801_9_dialog_content = "왠지 놈들한테 공격을 당하면 저렇게 되는 것 같아.\n미아, 놈들이랑 절대 가까이 붙으면 안 돼!",
  ui_story_5053_50530801_10_dialog_content = "하지만 이대로는 끝이 없어. 언젠간 체력이 다 떨어질 거야!",
  ui_story_5053_50530801_11_dialog_content = "이것도 그 사람의 계획인 건가...?! 누구 우리 도와주러 올 사람 없어?!\n아... 성주님!",
  ui_story_5053_50530801_12_dialog_content = "아버님은 지금 드래곤이랑 싸우고 계셔... 벗어나긴 힘드실 거야!",
  ui_story_5053_50530801_13_dialog_content = "(아버님, 대체 어떻게 해야 할까요...)",
  ui_story_5053_50530801_14_dialog_content = "네 어머니나 카렌, 그리고 다른 어떠한 일도 더는 두려워할 필요가 없다.",
  ui_story_5053_50530801_15_dialog_content = "네가 옳다고 여기는 길을 용감히 걸어가거라. 나는 너를 믿는다.",
  ui_story_5053_50530801_16_dialog_content = "(내 판단을 믿는 거야... 자신을 믿어...)",
  ui_story_5053_50530801_17_dialog_content = "히포카──!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>콰아앙!!!</color>",
  ui_story_5053_50530801_19_dialog_content = "어, 엄청나!",
  ui_story_5053_50530801_20_dialog_content = "히포카, 내 부름에 답해줘서 고마워. 다시는... 널 잃지 않을게...!",
  ui_story_5053_50530801_21_dialog_content = "미아, 너도 대단해! 감염된 경비병들을 거의 다 쓰러트렸잖아!",
  ui_story_5053_50530801_22_dialog_content = "도움이 돼서 다행이야... 얼른 아버님을 도우러 가자!",
  ui_story_5053_50530801_23_dialog_content = "...미아... 잠깐만...",
  ui_story_5053_50530801_24_dialog_content = "...하아, 하아... 하아...",
  ui_story_5053_50530801_25_dialog_content = "어...언니...",
  ui_story_5053_50530801_26_dialog_content = "카, 카렌?! 머리에... 피?!",
  ui_story_5053_50530801_27_dialog_content = "저 미쳐버린 경비병한테 당한 거야?! 설마 그럼 카렌도...",
  ui_story_5053_50530801_28_dialog_content = "미아, 가까이 가면 안 돼! 카렌의 눈이 경비병들이랑 똑같아졌어!",
  ui_story_5053_50530801_29_dialog_content = "카렌, 장창 내려놓고... 언니한테 와.",
  ui_story_5053_50530801_30_dialog_content = "착하지...?",
  ui_story_5053_50530801_31_dialog_content = "......",
  ui_story_5053_50530801_32_dialog_content = "언니, 나... 너무 아파...",
  ui_story_5053_50530801_33_dialog_content = "무서워하지 마. 언니가 상처 치료해 줄게. 그러니까 그 창 내려놔, 알겠지?",
  ui_story_5053_50530801_34_dialog_content = "아니, 머리가... 아파...!",
  ui_story_5053_50530801_35_dialog_content = "이상한 목소리가 들려... 나보고 언니를 죽이래... 싫어!",
  ui_story_5053_50530801_36_dialog_content = "카렌, 괜찮아... 언니가 지켜줄게!",
  ui_story_5053_50530801_37_dialog_content = "가까이 오지 마!",
  ui_story_5053_50530801_38_dialog_content = "...나는... 카렌 드 솔라드, 고결한 솔라드 가문의 딸... 백야성의 수호자...",
  ui_story_5053_50530801_39_dialog_content = "카렌은... 절대 가족들을 해치는 일 따윈 하지 않아! 절대로...!",
  ui_story_5053_50530801_40_dialog_content = "으...으윽! 카렌은... 언니를 해치지 않을 거야... 그러니까...",
  ui_story_5053_50530801_41_dialog_content = "미안해, 언니... 카렌은 이제... 언니 곁에 있을 수 없어...",
  ui_story_5053_50530801_42_dialog_content = "안 돼! 그거 내려놔! 안 된다고 했잖아! 멈춰!",
  ui_story_5053_50530801_43_dialog_content = "카렌!!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5053_50530801_45_dialog_content = "창으로... 목을...",
  ui_story_5053_50530801_46_dialog_content = "...카렌이... 스스로...",
  ui_story_5053_50530801_47_dialog_content = "......",
  ui_story_5053_50530801_48_dialog_content = "아... 아...",
  ui_story_5053_50530801_49_dialog_content = "아아아아아악──!",
  ui_story_5053_50530801_50_dialog_content = "아니야! 싫어어어어어어어!",
  ui_story_5053_50530801_51_dialog_content = "미아! 미아, 정신 차려! 이건 현실이 아니야...\n이 세계의 카렌은 그저 환영일 뿐이야!",
  ui_story_5053_50530801_52_dialog_content = "카렌! 날 떠나지 마... 안 돼... 카렌... 날 혼자 두지 말아줘... 카렌... 제발...",
  ui_story_5053_50530801_53_dialog_content = "미아! 정신 차려! 내 목소리 들려? 미아!",
  ui_story_5053_50530801_54_dialog_content = "(내 목소리가 전혀 들리지 않는 것 같아... 설마 병이 재발한 건가...?!)",
  ui_story_5053_50530801_55_dialog_content = "아아아아아악!",
  ui_story_5053_50530801_56_dialog_content = "뜨, 뜨거워!",
  ui_story_5053_50530801_57_dialog_content = "(미아의 힘이 폭주하기 시작했잖아?!)",
  ui_story_5053_50530801_58_dialog_content = "......",
  ui_story_5053_50530801_59_dialog_content = "뭐, 뭘 하려는 거야...?!",
  ui_story_5053_50530801_60_dialog_content = "울지... 말렴...",
  ui_story_5053_50530801_61_dialog_content = "로니... 울지 말렴... 우리 아가...",
  ui_story_5053_50530801_62_dialog_content = "괜찮아... 슬퍼하지 마...",
  ui_story_5053_50530801_63_dialog_content = "아...",
  ui_story_5053_50530801_64_dialog_content = "장미 한 송이를...♪ 귀여운 우리... 아이에게 선물하자...♪",
  ui_story_5053_50530801_65_dialog_content = "산들바람이... 그 뺨을 어루만지고...\n네 웃는 얼굴은... 세상에 하나뿐인... 보물...♪",
  ui_story_5053_50530801_66_dialog_content = "장미 한 송이를...♪ 소중한 아빠와... 엄마에게 선물하자...♪",
  ui_story_5053_50530801_67_dialog_content = "무슨 일이 있어도... 우린 영원히... 서로의 사랑이야...♪",
  ui_story_5053_50530801_68_dialog_content = "로니... 봐... 엄마야...",
  ui_story_5053_50530801_69_dialog_content = "어머님...? 어머님...",
  ui_story_5053_50530801_70_dialog_content = "으아아아아앙!",
  ui_story_5053_50530801_71_dialog_content = "카렌이, 카렌이...",
  ui_story_5053_50530801_72_dialog_content = "카렌의 손이... 아까까지 그렇게 따뜻했던 손이... 피를 흘리고...",
  ui_story_5053_50530801_73_dialog_content = "어머님... 흐아아앙...",
  ui_story_5053_50530801_74_dialog_content = "괜찮아... 그냥 나쁜 꿈이야...",
  ui_story_5053_50530801_75_dialog_content = "로니는... 나쁜 꿈을... 꾸고 있을 뿐이야...",
  ui_story_5053_50530801_76_dialog_content = "울고 싶으면... 원하는 만큼... 울렴...",
  ui_story_5053_50530801_77_dialog_content = "엄마가... 곁에 있으니까...",
  ui_story_5053_50530801_78_dialog_content = "......",
  ui_story_5053_50530801_79_dialog_content = "따뜻한 품... 그리운 자장가...",
  ui_story_5053_50530801_80_dialog_content = "정말 어머님이셨군요...",
  ui_story_5053_50530801_81_dialog_content = "어머님... 정말... 보고 싶었어요...",
  ui_story_5053_50530801_82_dialog_content = "나도... 보고... 싶었단다...",
  ui_story_5053_50530801_83_dialog_content = "(「검은 천사」가 상냥하게 미아를 위로하고 있어...)",
  ui_story_5053_50530801_84_dialog_content = "(이성이 없는 괴물이 아니었던 거야?!\n잠깐... 그 조슈아 부인이 한 말이 전부 거짓말이라면...)",
  ui_story_5053_50530801_85_dialog_content = "...미아, 괜찮아? 일어날 수 있겠어?",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... 미안해, 아까는 진정할 수가 없었어...",
  ui_story_5053_50530801_87_dialog_content = "널 다치게 만든 건 아니지...?",
  ui_story_5053_50530801_88_dialog_content = "그럴 리가 없잖아. 아무 일도 없었어. 네가 무사하면 그걸로 됐어.",
  ui_story_5053_50530801_89_dialog_content = "하지만 이 「검은 천사」... 대체 어떻게 된 거지? 전혀 모르겠잖아...",
  ui_story_5053_50530801_90_dialog_content = "이제 확실하게 알겠어. 이쪽이야말로 어머님이야.",
  ui_story_5053_50530801_91_dialog_content = "「검은 천사」가... 조슈아 부인이라고...?!",
  ui_story_5053_50530801_92_dialog_content = "이해하기 힘들단 건 알아. 하지만 내 느낌이 말해주고 있어.\n이 「검은 천사」야말로 어머님이라고...",
  ui_story_5053_50530801_93_dialog_content = "또 다른 어머님은 「검은 천사」가 이성을 잃은 괴물이라고 했어.\n하지만 「검은 천사」의 포옹은 이렇게나 다정한걸.",
  ui_story_5053_50530801_94_dialog_content = "반면에 저택에 계셨던 어머님은 왠지 모르게 낯선 느낌이었어...",
  ui_story_5053_50530801_95_dialog_content = "...아니, 이해할 수 있어. 오히려 그렇게 보면 모든 의문이 풀리거든.",
  ui_story_5053_50530801_96_dialog_content = "응? PlayerName, 그게 무슨 뜻이야?",
  ui_story_5053_50530801_97_dialog_content = "한마디로 설명하긴 힘들어. 어쨌든 지금 쟈키니가 위험해. 빨리 돌아가야 돼!",
  ui_story_5053_50530801_98_dialog_content = "자세한 건 가면서 얘기할게!",
  ui_story_5053_50530801_99_dialog_content = "쟈키니? 쟈키니라면 걱정할 필요 없어.\n칼렙 외삼촌도 같이 계시니까 외삼촌이 지켜주실 거야.",
  ui_story_5053_50530801_100_dialog_content = "칼렙 씨도 쟈키니랑 같이 있다고?",
  ui_story_5053_50530801_101_dialog_content = "응, 아버님께서 외삼촌한테 남으라고 하셨거든. 왜 그러셨는지는 모르겠지만...",
  ui_story_5053_50530801_102_dialog_content = "아니, 칼렙 씨가 같이 있더라도 아마 똑같을 거야.",
  ui_story_5053_50530801_103_dialog_content = "저택의 그 「조슈아 부인」은 정말 무서운 사람이야.\n그 어떤 수단도 가리지 않고 우릴 전부 다 죽일 거야.",
  ui_story_5053_50530801_104_dialog_content = "뭐...뭐라고...?!",
  ui_story_5053_50530801_105_dialog_content = "미아, 지금 일어나는 일들은 이미 처음이 아니야!",
  ui_story_5053_50530801_106_dialog_content = "!!",
  ui_story_5053_50530801_107_dialog_content = "칼렙이... 위험해...",
  ui_story_5053_50530801_108_dialog_content = "칼...렙... 내... 동생...",
  ui_story_5053_50530801_109_dialog_content = "동생이... 위험해...",
  ui_story_5053_50530801_110_dialog_content = "그러니까... 시간이 이미 두 번 회귀했다는 거야...?",
  ui_story_5053_50530801_111_dialog_content = "지금 당장 돌아가야 해! 아버님을 찾으러 가자!",
  ui_story_5053_50530801_112_dialog_content = "아버님!",
  ui_story_5053_50530801_113_dialog_content = "성주님! 지금 당장 저택으로 돌아가서 칼렙 씨랑 쟈키니를 구해야 해요!\n자세한 건 가면서 말씀드릴게요!",
  ui_story_5053_50530801_114_dialog_content = "다...니엘...",
  ui_story_5053_50530801_115_dialog_content = "...아무래도 내가 생각했던 것보다 상황이 더 복잡한 모양이군.",
  ui_story_5053_50530801_116_dialog_content = "허나 나는 지금 이곳을 떠날 수 없다.",
  ui_story_5053_50530801_117_dialog_content = "저 드래곤은 그 어떠한 상처라도 빠르게 회복하고 있다. 치명상조차도 말이다.",
  ui_story_5053_50530801_118_dialog_content = "저런 불길한 성질은 「불사성」이라고 하는 것이다.",
  ui_story_5053_50530801_119_dialog_content = "그 전설에나 존재할 수 있는 특성은 오직 「영원한 기억의 수정」 속\n환영만이 가질 수 있겠지.",
  ui_story_5053_50530801_120_dialog_content = "어째서 그런...",
  ui_story_5053_50530801_121_dialog_content = "아마 「조슈아」 부인의 소행일 거예요.\n성주님, 그럼 여기 남아서 드래곤을 막아 주시겠어요?",
  ui_story_5053_50530801_122_dialog_content = "「조슈아」인가... 알겠다. 저택 쪽은 그대들에게 맡기겠다.",
  ui_story_5053_50530801_123_dialog_content = "베로니카, 어째서 피신하지 않은 것이냐.\n네 옆의 그건...",
  ui_story_5053_50530801_124_dialog_content = "......",
  ui_story_5053_50530801_125_dialog_content = "아버님... 급한 일이 있어서 저택에 다녀와야 할 것 같아요.\n부디 절 막지 말아 주세요.",
  ui_story_5053_50530801_126_dialog_content = "지금의 이 상황보다 더 시급한 일은 없다.",
  ui_story_5053_50530801_127_dialog_content = "게다가 네가 내력을 알 수 없는 자들과 어울려 다니는 것은 더더욱 허락할 수 없다.",
  ui_story_5053_50530801_128_dialog_content = "귀하는 이미 내력을 알 수 없는 이 노인과 함께 싸우지 않았는가.",
  ui_story_5053_50530801_129_dialog_content = "어찌 이제 와서 그 문제를 마음에 둔단 말인가.",
  ui_story_5053_50530801_130_dialog_content = "......",
  ui_story_5053_50530801_131_dialog_content = "걱정하지 않아도 좋네. 나도 PlayerName도 모두 베로니카 공주의 동료일세.\n귀하의 가족은 우리가 지키겠네.",
  ui_story_5053_50530801_132_dialog_content = "귀하는 백야성의 온 백성을 지켜야 할 책임이 있네.\n모든 이를 지켜야 한다는 말일세.",
  ui_story_5053_50530801_133_dialog_content = "그리할 필요는 없다. 백야성에는 싸움에 능한 「미즈 로트」가 있고,\n내 아내 또한 별 볼 일 없는 이가 아니니, 그대들을 수고롭게 할 일은 없을 것이다.",
  ui_story_5053_50530801_134_dialog_content = "게다가 저런 괴물처럼 보이는 것을 내가 신뢰할 수는 없지.",
  ui_story_5053_50530801_135_dialog_content = "......",
  ui_story_5053_50530801_136_dialog_content = "그 점이라면 안심해도 좋을 것이네.\n이쪽은 내 아내일세.",
  ui_story_5053_50530801_137_dialog_content = "뭐라...?!",
  ui_story_5053_50530801_138_dialog_content = "......!",
  ui_story_5053_50530801_139_dialog_content = "(아버님... 역시 아버님도 이쪽이 진짜 어머님이라고 생각하셨군요!)",
  ui_story_5053_50530801_140_dialog_content = "크흠, 귀하가 반려자를 택하는 안목은 참 독특하다고 말하지 않을 수 없겠군.",
  ui_story_5053_50530801_141_dialog_content = "피차일반일세.",
  ui_story_5053_50530801_142_dialog_content = "미아, PlayerName, 서둘러라. 시간이 없다.",
  ui_story_5053_50530801_143_dialog_content = "네!",
  ui_story_5053_50530801_144_dialog_content = "칼렙...",
  ui_story_5053_50530801_145_dialog_content = "어머님도... 같이 가실 건가요?",
  ui_story_5053_50530801_146_dialog_content = "칼렙을... 지켜야 해...",
  ui_story_5053_50530801_147_dialog_content = "네, 같이 외삼촌을 지키러 가요!",
  ui_story_5053_50530901_1_dialog_content = "칼렙 씨, 밖엔 좀 어때요?",
  ui_story_5053_50530901_2_dialog_content = "아까 귀가 찢어질 것 같은 큰 소리가 났어요. 뭔가 안 좋은 예감이 들어요...",
  ui_story_5053_50530901_3_dialog_content = "네, 왜인지는 모르겠지만 드래곤이 예상보다 빨리 나타났습니다.",
  ui_story_5053_50530901_4_dialog_content = "지금쯤 광장은 대혼란에 빠져 있겠죠.",
  ui_story_5053_50530901_5_dialog_content = "그럼 다들 지금 엄청 위험한 거 아니에요?",
  ui_story_5053_50530901_6_dialog_content = "성주님이랑 미아 씨, 그리고 어디 있는지도 알 수 없는 PlayerName 씨도...",
  ui_story_5053_50530901_7_dialog_content = "걱정할 필요 없어. 다니엘이 잘 해결할 거야.",
  ui_story_5053_50530901_8_dialog_content = "저택 쪽도... 좋아. 마침 때맞춰 왔네.",
  ui_story_5053_50530901_9_dialog_content = "......",
  ui_story_5053_50530901_10_dialog_content = "이미 대책을 세워뒀던 거군요, 역시 누나라니까요.",
  ui_story_5053_50530901_11_dialog_content = "쟈키니 씨, 걱정 안 하셔도 돼요.",
  ui_story_5053_50530901_12_dialog_content = "아, 알겠어요...",
  ui_story_5053_50530901_13_dialog_content = "참, 쟈키니, 혹시 방문 좀 잠가줄 수 있을까?",
  ui_story_5053_50530901_14_dialog_content = "아, 그렇죠! 문을 잠가야 좀 더 안전할 테니까요. 알겠어요~",
  ui_story_5053_50530901_15_dialog_content = "칼렙, 한 가지 궁금한 게 있어. 왜 날 구하고 싶은 거니?",
  ui_story_5053_50530901_16_dialog_content = "음? 누나는 제 친누나잖아요. 누나를 구하는 건 당연한 일 아닌가요?",
  ui_story_5053_50530901_17_dialog_content = "...「혈육의 정」 때문인 거니?",
  ui_story_5053_50530901_18_dialog_content = "당연하죠. 제게는 이 세상의 모든 게 변수로 가득해요.\n하지만 오직 누나와 저, 아버지만은...",
  ui_story_5053_50530901_19_dialog_content = "우리 가족의 유대만은 결코 변하지 않아요.\n세월이 얼마나 지나더라도, 전 그렇게 믿어요.",
  ui_story_5053_50530901_20_dialog_content = "그래? 동기야 어쨌든, 적어도 내 육체를 구해준 건 감사해야겠지.",
  ui_story_5053_50530901_21_dialog_content = "잘했어, 칼렙.",
  ui_story_5053_50530901_22_dialog_content = "누나...!",
  ui_story_5053_50530901_23_dialog_content = "확실히 이 세상은 변수로 가득해.\n하지만 아무리 시간이 지나도 변하지 않는 게 있어...",
  ui_story_5053_50530901_24_dialog_content = "12년이 지났어. 지금의 백야성은 어떤 모습으로 변했니?",
  ui_story_5053_50530901_25_dialog_content = "옛날 그대로예요.\n그 벌레 같은 귀족들은 여전히 현실에 안주하고 변화를 거부하고 있죠.",
  ui_story_5053_50530901_26_dialog_content = "귀족들에게 물어뜯긴 백야성은 이제 찬란한 껍데기만 남은 채,\n안에서부터 밖까지 전부 썩어버렸어요.",
  ui_story_5053_50530901_27_dialog_content = "역시 그렇구나... 그럼 솔라드 가문은?",
  ui_story_5053_50530901_28_dialog_content = "솔라드? 백야성보다 더 엉망이에요.",
  ui_story_5053_50530901_29_dialog_content = "그때 녀석이 누나에게 했던 그 많은 그럴싸한 맹세들 중에,\n지금까지 실현된 게 대체 몇 개나 있었죠?",
  ui_story_5053_50530901_30_dialog_content = "「백야성을 철저하게 개혁해서 이 땅을 가장 공평하고 자유로운 곳으로 바꾸겠다」더니...",
  ui_story_5053_50530901_31_dialog_content = "지금은 고작 저 썩어빠진 귀족들에 맞서는 것만으로도 온 힘을 써버렸는데,\n뭘 바꾼다는 게 가당키나 한 소린가요?",
  ui_story_5053_50530901_32_dialog_content = "게다가 가족들도 녀석의 나약함 때문에 뿔뿔이 흩어졌어요.\n누나를 이렇게 만들고, 심지어 베로니카와 카렌까지 말려들게 만들었다고요.",
  ui_story_5053_50530901_33_dialog_content = "저기... 전 정치 같은 건 잘 모르지만, 칼렙 씨도 너무 극단적인 것 같은데요.",
  ui_story_5053_50530901_34_dialog_content = "그 성가신 귀족 노인네들을 상대하면서, 백성들에게 위대하고 의지할 만한\n군주의 모습을 보여줄 수 있는 것도 대단한 거 아닌가요?",
  ui_story_5053_50530901_35_dialog_content = "쟈키니 씨, 당신 같은 외부인이 볼 수 있는 건 결국 저 빛나는 껍데기뿐이에요.\n당신이 진짜 백야성에 대해 뭘 얼마나 안다는 겁니까?",
  ui_story_5053_50530901_36_dialog_content = "하지만 북방의 여왕 폐하조차 성주님을... 휴, 됐어요!\n전 경비병이랑 수다나 떨다 올게요!",
  ui_story_5053_50530901_37_dialog_content = "그럼 나는 어떠니? 솔라드를 선택한 나도 실패한 걸까?",
  ui_story_5053_50530901_38_dialog_content = "무, 물론 누나는 별개죠! 누나는 솔라드의 감언이설에 속았을 뿐이에요.\n누나는 피해자라고요!",
  ui_story_5053_50530901_39_dialog_content = "만약에... 어디까지나 만약이지만... 만약 누나가 솔라드를 떠나고 싶다면,\n전 언제나 누나를 환영할 거예요.",
  ui_story_5053_50530901_40_dialog_content = "혹시나 백야성이 싫으시다면 다른 곳으로 가서 살아도 돼요!",
  ui_story_5053_50530901_41_dialog_content = "그럴 필요는 없어, 칼렙. 난 백야성이 이대로 썩어가는 걸 내버려 둘 순 없어.\n나는 내 일생 동안 반드시 여길 바꾸고 말 거야.",
  ui_story_5053_50530901_42_dialog_content = "......",
  ui_story_5053_50530901_43_dialog_content = "그래도 네 말은 맞아. 다니엘은 이미 가망이 없어.\n난 그 사람에게 이미 철저히 실망했거든.",
  ui_story_5053_50530901_44_dialog_content = "누나...! 이제야 녀석과 이혼할 생각이 든 건가요?",
  ui_story_5053_50530901_45_dialog_content = "칼렙, 너처럼 공공연하게 솔라드에게 반기를 드는 사람은 이제 그리 많지 않아.",
  ui_story_5053_50530901_46_dialog_content = "아무래도 나와 그 남자의 교육이 헛되진 않은 모양이구나.",
  ui_story_5053_50530901_47_dialog_content = "그 남자...? 설마 아버지 말씀이신가요?\n...왜 갑자기 아버지를 그렇게 남처럼 부르시는 거죠...?",
  ui_story_5053_50530901_48_dialog_content = "이제 네게 모든 진실을 알려줄 때가 된 것 같아.\n경비병, 붙잡아.",
  ui_story_5053_50530901_49_dialog_content = "......",
  ui_story_5053_50530901_50_dialog_content = "으앗! 아, 아프잖아요! 지금 뭐 하자는 거예요?",
  ui_story_5053_50530901_51_dialog_content = "무슨 진실이요...? 누나... 쟈키니 씨한테 뭘 하려는 거죠...?",
  ui_story_5053_50530901_52_dialog_content = "칼렙, <color=#FFB400>난 네 친누나가 아냐</color>.",
  ui_story_5053_50530901_53_dialog_content = "아...?",
  ui_story_5053_50530901_54_dialog_content = "오래전, 내 가문은 솔라드 가문의 통치에 반대했고,\n전임 성주, 그러니까 다니엘의 아버지에게 숙청당했어.",
  ui_story_5053_50530901_55_dialog_content = "그때 다른 여러 가문도 함께 살해당했고, 살아남은 건 어린 나와 몇 명의 사람뿐이었어.",
  ui_story_5053_50530901_56_dialog_content = "우린 모두 솔라드 가문을 증오했고, 한마음으로 자신의 가문을 위해 복수를 맹세했어.",
  ui_story_5053_50530901_57_dialog_content = "그리고 난 어느 유족의 가정에 들어갔고, 솔라드 가문의 손에 죽은\n그 집의 딸을 대신해서 하이가든에 갈 수 있었어.",
  ui_story_5053_50530901_58_dialog_content = "잠깐만요... 유족의 가정...? <color=#FFB400>솔라드 가문의 손에 죽은 딸</color>...? 대체 무슨...",
  ui_story_5053_50530901_59_dialog_content = "그래, 그 사람이 바로 네 누나 「<color=#FFB400>조슈아</color>」야.\n네 친누나와 어머님은 이미 오래전에 돌아가셨어.",
  ui_story_5053_50530901_60_dialog_content = "두 사람은 심지어 솔라드 가문에 그 어떤 불만도 없었고,\n그저 공교롭게도 그날 숙청된 가문의 친구를 보러 갔을 뿐이었어.",
  ui_story_5053_50530901_61_dialog_content = "...아버지는... 이 사실을 알고 계셨나요...?",
  ui_story_5053_50530901_62_dialog_content = "당연하지. 딸을 바꿔치기하는 계획은 그 남자가 세운 거였으니까.",
  ui_story_5053_50530901_63_dialog_content = "노, 농담이죠? 그 성실하고 정직한 아버지가 어떻게 그런...",
  ui_story_5053_50530901_64_dialog_content = "그게 바로 증오의 힘이란다, 칼렙.",
  ui_story_5053_50530901_65_dialog_content = "우리가 협력해서 널 키운 건 「가족」이라서가 아니라 복수에 대한 갈망 때문이야.",
  ui_story_5053_50530901_66_dialog_content = "네 아버지는 암살에 실패하자 스스로 목숨을 끊었어.\n그건 너와 날 지켜서 복수의 불씨를 남기기 위해서였어.",
  ui_story_5053_50530901_67_dialog_content = "그때 난 다니엘의 거듭되는 간청을 봐서 그 사람에게 솔라드 가문을 바꿀 기회를 줬어.",
  ui_story_5053_50530901_68_dialog_content = "게다가 그 사람이 선거에 이기게 도와서 새로운 성주로 만들어 주기까지 했어.",
  ui_story_5053_50530901_69_dialog_content = "...난 그 사람 아버지처럼 무고한 사람까지 해칠 도살자는 아니었으니까.",
  ui_story_5053_50530901_70_dialog_content = "하지만 내가 틀렸어. 이 모든 게 다니엘의 무능 때문에 아무 의미도 없게 돼버렸어.\n그리고 이젠 솔라드 가문이 우리의 분노를 느끼게 해줄 때가 됐어.",
  ui_story_5053_50530901_71_dialog_content = "칼렙, <color=#FFB400>쟈키니</color>를 죽여.",
  ui_story_5053_50530901_72_dialog_content = "...뭐라고요? 누나... 지금 뭐라고...",
  ui_story_5053_50530901_73_dialog_content = "여기서 나가려면 밖에서 들어온 자의 루미나가 필요해.\n바깥엔 아직 내가 이루지 못한 사명이 있어.",
  ui_story_5053_50530901_74_dialog_content = "안 돼요...! 쟈키니 씨는 그 모든 것과 아무 상관도 없잖아요!\n누나도 무고한 사람은 죽이고 싶진 않다고 했잖아요!",
  ui_story_5053_50530901_75_dialog_content = "이건 「필요한 희생」이야.",
  ui_story_5053_50530901_76_dialog_content = "당신... 미쳤어요?! 그 상냥한 조슈아 부인은 어디 간 거죠?",
  ui_story_5053_50530901_77_dialog_content = "그건 제가 묻고 싶다고요... 가족이 아니라니... 혈육의 정이 없다니... 웃기지 마...\n쟈키니 씨, 지금 이 사람이 정말 환영이 아닌 게 확실합니까?!",
  ui_story_5053_50530901_78_dialog_content = "진짜 아니에요! 제가 변신 점술 같은 걸 쓰지도 않았구요!",
  ui_story_5053_50530901_79_dialog_content = "칼렙, 진실을 알고도 계속해서 못 본 척할 생각이야?\n네 아버지와 어머니, 누나의 희생을 저버리려고?",
  ui_story_5053_50530901_80_dialog_content = "............",
  ui_story_5053_50530901_81_dialog_content = "뭐, 좋아. 우리 교육이 아직 부족했던 모양이네. 쟈키니는 내가 처리할게.",
  ui_story_5053_50530901_82_dialog_content = "하지만 나중에 넌 네 손으로 직접 다니엘과 다른 사람들을 없애서 네 결의를 보여야 해.\n이건 내가 너한테 주는 마지막 기회야.",
  ui_story_5053_50530901_83_dialog_content = "모두 죽이겠다고요?! 크윽! 이거 놔! 그렇게 될 줄 알고?!",
  ui_story_5053_50530901_84_dialog_content = "증오하려면 솔라드를 증오하렴. 북방의 사절 아가씨, 그럼 잘 가.",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5053_50530901_86_dialog_content = "...누나 말이 맞아요. 비록 지금 누나는 그토록 낯설게 변했지만...\n전 본능적으로 알 수 있어요. 누나는 제가 가장 사랑하는 누나예요.",
  ui_story_5053_50530901_87_dialog_content = "그래서 전 반드시 누나를 막을 거예요.\n절대로 누나가 스스로 후회할 일을 하게 만들진 않을 거라고요!",
  ui_story_5053_50530901_88_dialog_content = "후회? 자상한 누나 연기를 하면서 네 배짱 없는 아버지를 대신해 널 돌봐온 건\n네가 우리의 의지를 확실하게 계승하길 원해서였어.",
  ui_story_5053_50530901_89_dialog_content = "으윽...!",
  ui_story_5053_50530901_90_dialog_content = "그런데 네가 날 배신하다니... 너도 날 배신했어!",
  ui_story_5053_50530901_91_dialog_content = "아니에요... 전 누나를 배신한 적 없어요!",
  ui_story_5053_50530901_92_dialog_content = "아, 손이 저리네... 무장 해제술이라, 역시 넌 잔꾀밖에 못 부리는구나!",
  ui_story_5053_50530901_93_dialog_content = "이렇게 된 이상 저도 누나한테 진실을 하나 말해줄게요.\n전 항상 솔라드가 누나의 짝이 될 자격이 없다고 했었죠. 하지만 전 줄곧 알고 있었어요...",
  ui_story_5053_50530901_94_dialog_content = "전 그저 단순히 누나 남편과 아이들이 싫은 것뿐이었어요!\n저들이 제 유일한 가족을 빼앗아 갔으니까요!",
  ui_story_5053_50530901_95_dialog_content = "설령 피가 이어져 있지 않더라도...\n전 지금까지 절 키워준 누나를 진심으로 사랑하고 있어요!",
  ui_story_5053_50530901_96_dialog_content = "아무리 재능이 있어도, 넌 결국 누나를 떠날 수 없는 다 큰 아기일 뿐이야!\n방해하지 마!",
  ui_story_5053_50530901_97_dialog_content = "맞아요! 전 계속 철없는 채죠... 비웃고 싶으면 얼마든지 비웃어요!",
  ui_story_5053_50530901_98_dialog_content = "하지만... 그런 저조차 누나가 아이들과 남편을 얼마나 사랑하는지 알고 있어요.\n그건 제가 아무리 노력해도 바꿀 수 없는 사실이에요!",
  ui_story_5053_50530901_99_dialog_content = "전부 위장일 뿐이라고 말했잖아!",
  ui_story_5053_50530901_100_dialog_content = "으윽... 미안해요, 누나. 이번만큼은 믿어줄 수 없어요.",
  ui_story_5053_50530901_101_dialog_content = "누나가 힘들어하는 일이 없도록, 전 반드시 누나의 소중한 가족들을 지킬 거예요.\n제 목숨을 걸어야 한다 해도 말이에요!",
  ui_story_5053_50530901_102_dialog_content = "좋아, 그럼 네 목숨과 루미나를 받아 갈게.",
  ui_story_5053_50530901_103_dialog_content = "아...?!",
  ui_story_5053_50530901_104_dialog_content = "아...안 돼! 칼렙 씨!!",
  ui_story_5053_50530901_105_dialog_content = "...전부 네가 선택한 거야.",
  ui_story_5053_50530901_130_dialog_content = "칼렙 씨!!",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>퍼어엉──</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>아아아악──!</size>",
  ui_story_5053_50530901_133_dialog_content = "윽!",
  ui_story_5053_50530901_134_dialog_content = "으억──!",
  ui_story_5053_50530901_135_dialog_content = "?!",
  ui_story_5053_50530901_136_dialog_content = "...역겨운 괴물이 하필 이럴 때... 쳇!",
  ui_story_5053_50530901_138_dialog_content = "칼렙 씨! 조금만 버텨요! 칼렙 씨!!",
  ui_story_5053_50530901_139_dialog_content = "칼...렙...!",
  ui_story_5053_50530901_140_dialog_content = "하... 분명히 한 번에 죽일 수 있으면서...\n거 봐요... 여전히 마음 약한 누나잖아요...",
  ui_story_5053_50530901_141_dialog_content = "이런... 상처가 너무 깊어서... 피가 안 멈춰요...",
  ui_story_5053_50530901_143_dialog_content = "어두워... 아무것도 안 보여요...",
  ui_story_5053_50530901_145_dialog_content = "안... 돼...",
  ui_story_5053_50530901_146_dialog_content = "누나... 누나예요...?",
  ui_story_5053_50530901_147_dialog_content = "칼...렙...",
  ui_story_5053_50530901_148_dialog_content = "누나는... 여기... 있어...",
  ui_story_5053_50530901_149_dialog_content = "저...정말요...? 콜록!",
  ui_story_5053_50530901_150_dialog_content = "누나...... 검을... 내려놓은... 거죠...?",
  ui_story_5053_50530901_151_dialog_content = "다행...이야...",
  ui_story_5053_50530901_152_dialog_content = "......",
  ui_story_5053_50530901_153_dialog_content = "칼렙 씨! 칼렙 씨!!",
  ui_story_5053_50530901_155_dialog_content = "칼...렙...!!",
  ui_story_5053_50530901_156_dialog_content = "안...돼... 제발...!",
  ui_story_5053_50530901_157_dialog_content = "<size=50>아아아아아악!</size>",
  ui_story_5053_50531001_1_dialog_content = "휴우... 휴우...",
  ui_story_5053_50531001_2_dialog_content = "PlayerName, 괜찮아? 못 달리겠으면 조금 쉬자.",
  ui_story_5053_50531001_3_dialog_content = "괜찮아, 「검은 천사」를 따라잡느라 좀 힘들었거든... 근데 진짜 빠르네!",
  ui_story_5053_50531001_4_dialog_content = "처음엔 우리랑 같이 가고 있었는데, 갑자기 뭔가 느낀 것처럼 급하게 날아가 버렸어...",
  ui_story_5053_50531001_5_dialog_content = "사실 아까 「검은 천사」가 널 구하러 갔을 때도 저런 느낌이었어.\n그래서.. 지금 쟈키니 쪽이 걱정이야...",
  ui_story_5053_50531001_6_dialog_content = "응... 거의 다 왔어! 꼭 무사해야 할 텐데...",
  ui_story_5053_50531001_7_dialog_content = "미아, 쟈키니가 두 번째 회귀 이전의 일을 전혀 기억 못 하는 게 확실해?",
  ui_story_5053_50531001_8_dialog_content = "응, 맞아. 우리도 쟈키니도 기억이 없었어...\n그래서 다들 저 「어머님」 말을 믿었던 거야.",
  ui_story_5053_50531001_9_dialog_content = "솔직히 PlayerName 네 말을 들은 지금도 난 조금 믿기가 힘들어...",
  ui_story_5053_50531001_10_dialog_content = "그러니까 내 눈으로 직접 진실을 확인하고 싶어...!",
  ui_story_5053_50531001_11_dialog_content = "(쟈키니도 기억을 못 하는데 왜 난 기억하고 있는 거지? 대체 이게 무슨...)",
  ui_story_5053_50531001_12_dialog_content = "저택의 분위기가 이상해. 경비병들은 다 어디로 간 걸까?",
  ui_story_5053_50531001_13_dialog_content = "땅이 희미하게 흔들리고 있어... 미아! 조심해!",
  ui_story_5053_50531001_14_dialog_content = "?!",
  ui_story_5053_50531001_15_dialog_content = "으아아──! 침입자... 저항자를... 죽여라──!",
  ui_story_5053_50531001_16_dialog_content = "으어어──!",
  ui_story_5053_50531001_17_dialog_content = "죽여라──! 죽여라──! 죽여라──!",
  ui_story_5053_50531001_18_dialog_content = "또 저 정신 나간 경비병들이야!",
  ui_story_5053_50531001_19_dialog_content = "꺄아악! 살려줘어어!",
  ui_story_5053_50531001_20_dialog_content = "저건... 쟈키니?!",
  ui_story_5053_50531001_21_dialog_content = "쟈키니가 경비병들한테 쫓기고 있어! 미아, 빨리 포위를 돌파하자!",
  ui_story_5053_50531001_22_dialog_content = "적이 너무 많아! 히포...",
  ui_story_5053_50531001_23_dialog_content = "베로니카 전하, 비켜주세요──!",
  ui_story_5053_50531001_24_dialog_content = "?!",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5053_50531001_26_dialog_content = "으억...!",
  ui_story_5053_50531001_27_dialog_content = "크아아악!",
  ui_story_5053_50531001_28_dialog_content = "(블랑 씨?! 강하다...! 마치 춤을 추듯이 순식간에 경비병을 쓰러트려 버렸어!)",
  ui_story_5053_50531001_29_dialog_content = "미즈 로트! 뒤에 조심해요!",
  ui_story_5053_50531001_30_dialog_content = "걱정 마세요, 베로니카 전하.",
  ui_story_5053_50531001_31_dialog_content = "이건 「나이트워치」의 의무예요.\n백야성은 그 누구도 멋대로 유린할 수 있는 곳이 아니니까요.",
  ui_story_5053_50531001_32_dialog_content = "제가 있는 한, 백야성의 질서를 어지럽히는 일은 허락하지 않아요.",
  ui_story_5053_50531001_33_dialog_content = "「만물은 백야 아래에──」",
  ui_story_5053_50531001_34_dialog_content = "으윽──!",
  ui_story_5053_50531001_35_dialog_content = "크아악!",
  ui_story_5053_50531001_36_dialog_content = "베로니카 전하, 쟈키니 양, 다치신 곳은 없으신가요?",
  ui_story_5053_50531001_37_dialog_content = "네... 전 괜찮아요.",
  ui_story_5053_50531001_38_dialog_content = "와줘서 고마워요. 우리만 있었다면 저 많은 적을 쓰러트리긴 힘들었을 거예요.",
  ui_story_5053_50531001_39_dialog_content = "전하, 대체 어떻게 된 거죠? 보아하니 반란군처럼 보이진 않는데요.",
  ui_story_5053_50531001_40_dialog_content = "아, 아니에요. 반란군이 아니라... 지금 정말 큰일이 났거든요.\n이 사람들은 전부 조슈아 부인이...",
  ui_story_5053_50531001_41_dialog_content = "어머, 정말 적반하장이네. 미즈 로트, 때맞춰 잘 왔어.",
  ui_story_5053_50531001_42_dialog_content = "이 불청객들은 전부 PlayerName, 쟈키니 두 사람이 꾸민 일이야.\n게다가 달콤한 말로 로니를 현혹시켜 버렸어.",
  ui_story_5053_50531001_43_dialog_content = "베로니카는 이미 저들에게 완전히 넘어가서 가망이 없게 됐어.\n엄마로서 정말 실망스럽네.",
  ui_story_5053_50531001_44_dialog_content = "어쩔 수 없지, 미즈 로트. 세 사람을 처리해, 이건 명령이야.",
  ui_story_5053_50531001_45_dialog_content = "......",
  ui_story_5053_50531001_46_dialog_content = "어머님... 그게 무슨 말씀이세요?!\n역시 PlayerName 말이 맞았어...",
  ui_story_5053_50531001_47_dialog_content = "미즈 로트, 지금 눈앞에 있는 건 진짜 「조슈아 부인」이 아니에요!\n저도 사실 뭐가 어떻게 된 건진 잘 모르겠지만...",
  ui_story_5053_50531001_48_dialog_content = "그래도 꼭 믿어주세요. 지금 그 사람은 당신이 아는 그 조슈아 부인이 아니라구요!",
  ui_story_5053_50531001_49_dialog_content = "저도 솔라드 가문의 이름을 걸고 맹세할게요.\nPlayerName의 말은 사실이에요.",
  ui_story_5053_50531001_50_dialog_content = "어머님에 대해서는 당신이 가장 잘 알고 있잖아요...\n어머님이 어떻게 방금 같은 그런 말을 하겠어요?!",
  ui_story_5053_50531001_51_dialog_content = "......",
  ui_story_5053_50531001_52_dialog_content = "뭘 망설이고 있어? 내가 널 어떻게 가르쳤는지 잊어버린 거니?",
  ui_story_5053_50531001_53_dialog_content = "암살자는 주인과 같은 이상을 품어야만 해.\n이상과 대의를 관철하기 위해서라면, 그 어떤 대가도 치를 수 있어야 한다고.",
  ui_story_5053_50531001_54_dialog_content = "백야성의 미래를 위한 길에 불필요한 감정은 장애물이 될 뿐이야.\n넌 그런 데 미련을 두는 사람이 아니잖아, 그렇지?",
  ui_story_5053_50531001_55_dialog_content = "(뭐야, 블랑 씨가 조슈아 부인의 제자였다고?)",
  ui_story_5053_50531001_56_dialog_content = "...맞아요. 선생님. 이 모든 건 「백야성의 미래」를 위해서죠.",
  ui_story_5053_50531001_57_dialog_content = "...?!",
  ui_story_5053_50531001_58_dialog_content = "저 모든 아이들이 평등하게 웃을 수 있는 세계를 실현하기 위해,\n전 모든 장애물을 제거하겠어요. 설령 그것이 당신일지라도.",
  ui_story_5053_50531001_59_dialog_content = "......",
  ui_story_5053_50531001_60_dialog_content = "역시 내 제자답네. 감히 내게 무기를 겨누다니, 그 용기는 칭찬해 줄게.",
  ui_story_5053_50531001_61_dialog_content = "좋아, 그럼 너도 오늘 저들과 함께 여기서 죽어버려!",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5053_50531001_63_dialog_content = "으윽──!",
  ui_story_5053_50531001_64_dialog_content = "(곤란하네요... 선생님의 공격이 너무 빨라요...!)",
  ui_story_5053_50531001_65_dialog_content = "미즈 로트?!",
  ui_story_5053_50531001_66_dialog_content = "PlayerName 님, 어서 베로니카 전하와 쟈키니 양을 데리고 도망치세요!",
  ui_story_5053_50531001_67_dialog_content = "저도 이 사람을 상대로 버틸 자신은 없어요. 그러니 당장 도망쳐요!",
  ui_story_5053_50531001_68_dialog_content = "하, 하지만...",
  ui_story_5053_50531001_69_dialog_content = "쓸데없는 생각은 하지 마세요.\n지금 가장 중요한 건 당신들의 안전이에요! 어서요!",
  ui_story_5053_50531001_70_dialog_content = "...어쩔 수 없겠어. 미아, 쟈키니, 도망치자!",
  ui_story_5053_50531001_71_dialog_content = "(미즈 로트, 부디 무사하길...!)",
  ui_story_5053_50531002_1_dialog_content = "에잇! 또 문 막을 만한 거 있어?",
  ui_story_5053_50531002_2_dialog_content = "아니, 방금 그 의자가 마지막이야.",
  ui_story_5053_50531002_3_dialog_content = "으음... 이상해요! 너무 이상하잖아요!",
  ui_story_5053_50531002_4_dialog_content = "PlayerName 씨 말이 사실이라면 이미 시간이 또 한 번 회귀했다는 거잖아요.",
  ui_story_5053_50531002_5_dialog_content = "첫 번째는 다 같이 손을 잡고 있었고, 제 주문도 정확했어요.\n그래서 우린 시간을 되돌리기 전의 기억을 가지고 있었죠...",
  ui_story_5053_50531002_6_dialog_content = "근데 두 번째는 저도 함께였는데, 제 기억은 남지 않았어요...",
  ui_story_5053_50531002_7_dialog_content = "맞아, 이유가 뭐야?",
  ui_story_5053_50531002_8_dialog_content = "...아, 왠지 알 것 같아요.",
  ui_story_5053_50531002_9_dialog_content = "「영원한 기억의 수정」 속 루미나가 이제 얼마 남지 않은 거예요!",
  ui_story_5053_50531002_10_dialog_content = "에엣?!",
  ui_story_5053_50531002_11_dialog_content = "음... 아무래도 저희나 적이나 너무 심하게 군 모양이에요.",
  ui_story_5053_50531002_12_dialog_content = "지금 남은 루미나로는 이제 「영원한 기억의 수정」의 모든 기능을\n유지할 수 없게 된 거죠.",
  ui_story_5053_50531002_13_dialog_content = "근데 왜 PlayerName 씨는 다 기억하고 있는 걸까요?",
  ui_story_5053_50531002_14_dialog_content = "그리고 두 명의 조슈아 부인도... 생각할수록 모르겠어요.",
  ui_story_5053_50531002_15_dialog_content = "설마 저택에 있는 「조슈아 부인」은 다른 사람이 부인인 척하는 걸까요?",
  ui_story_5053_50531002_16_dialog_content = "나도 전혀 모르겠어.\n하지만 아버님은 아직 광장에서 드래곤과 싸우고 계셔. 너무 걱정돼...",
  ui_story_5053_50531002_17_dialog_content = "우리에겐 이제 선택지가 얼마 없어. 차라리 다시 시간을 되돌리자.",
  ui_story_5053_50531002_18_dialog_content = "안 돼요! 만약 우리 모두 기억이 없다면 당신 혼자 조슈아 부인을 상대해야 돼요.\n그건 너무 위험하잖아요!",
  ui_story_5053_50531002_19_dialog_content = "맞아, 저 「어머님」이 상대라면 너 혼자서는 무리야.",
  ui_story_5053_50531002_20_dialog_content = "일단 물건을 잔뜩 쌓아서 문을 막았으니까, 시간은 조금 벌 수 있을 거예요.\n제가 점술서를 좀 살펴볼게요...",
  ui_story_5053_50531002_21_dialog_content = "「북방의 점술은 고대 오로리안의 부락에서 기원했다」...\n고대 오로리안... 고대 오로리안...",
  ui_story_5053_50531002_22_dialog_content = "아! 그렇네요! 이 점술은 오로리안이 만든 거고, 오로리안에게 쓰는 거예요!\n근데 PlayerName 씨는 아이테르잖아요!",
  ui_story_5053_50531002_23_dialog_content = "어쩌면 종족의 차이가 원인일 수도 있지 않을까요?\n왜냐하면 이 책엔 오로리안 외의 종족에 대한 설명은 전혀 없거든요.",
  ui_story_5053_50531002_24_dialog_content = "그런 건가... 그럼 내 감응 능력이 많이 약해진 것도 그거랑 관계가 있을까?",
  ui_story_5053_50531002_25_dialog_content = "으음~ PlayerName 씨, 혹시 일루미나 연방의 게임을 해 본 적 있나요?",
  ui_story_5053_50531002_26_dialog_content = "게임을 다시 실행하면 「캐릭터」는 기억을 잃어버리지만,\n「플레이어」는 그럴 일이 없죠.",
  ui_story_5053_50531002_27_dialog_content = "그럼 내가 지금 게임 속 「플레이어」라는 거야?",
  ui_story_5053_50531002_28_dialog_content = "맞아요! 당신은 규칙의 제한을 받지 않는 「플레이어」인 거예요!",
  ui_story_5053_50531002_29_dialog_content = "그러니까 다음 회귀 전까지, 우린 앞으로 당신이 어떻게 행동할지\n치밀하게 계획을 세워야 해요.",
  ui_story_5053_50531002_30_dialog_content = "맞아, 아무 준비도 없이 다음 회귀를 시작한다면 무척 위험할 거야.",
  ui_story_5053_50531002_31_dialog_content = "그렇네... 그럼 계획을 세워보자.",
  ui_story_5053_50531002_32_dialog_content = "지금 가장 큰 위협은 「조슈아」 부인이야.",
  ui_story_5053_50531002_33_dialog_content = "하지만 조슈아 부인이 둘이라니, 뭐가 어떻게 된 걸까? 난 아직도 잘 모르겠어.",
  ui_story_5053_50531002_34_dialog_content = "둘 다 조슈아 부인이라고 하면 헷갈리잖아요.\n한쪽은 이미 「검은 천사」라고 부르고 있으니까...",
  ui_story_5053_50531002_35_dialog_content = "다른 한쪽은 「하얀 악마」라고 부르죠!",
  ui_story_5053_50531002_37_dialog_content = "「하얀 악마」...... 어머님을 그런 식으로 부르고 싶진 않지만,\n확실히 지금의 저 어머님에게는 무척 어울리는 호칭이네.",
  ui_story_5053_50531002_38_dialog_content = "「하얀 악마」의 행동이나, 「하얀 악마」가 알고 있는 정보를 보면,\n다른 사람이 어머님 행세를 하고 있는 건 아냐.",
  ui_story_5053_50531002_39_dialog_content = "「씨앗」은 그게 심어진 사람의 인격을 분열시킬 수 있어...\n왠지 내 입장에선 어머님을 이해할 수 있을 것 같아.",
  ui_story_5053_50531002_40_dialog_content = "마치 나랑 바바 야가가 마음은 같지만 두 가지 모습을 보이는 것처럼 말이야.\n우린 서로 누가 좋고 나쁜지 단정할 수 없어.",
  ui_story_5053_50531002_41_dialog_content = "바바 야가는 때론 조금 극단적이지만, 결코 나쁜 아이는 아니야.\n그건 PlayerName 너도 잘 알 거야.",
  ui_story_5053_50531002_42_dialog_content = "그럼 「검은 천사」랑 「하얀 악마」도 나랑 같은 경우 아닐까?",
  ui_story_5053_50531002_43_dialog_content = "예를 들면 「검은 천사」가 한 짓은 확실히 이상했지만,\n광장에선 오히려 우릴 구해주기도 했어.",
  ui_story_5053_50531002_44_dialog_content = "어쩌면 그냥 어떤 면에서 자길 제어하지 못하는 걸지도 몰라.",
  ui_story_5053_50531002_45_dialog_content = "음... 그렇게 보면 「검은 천사」는 바바 야가랑 비슷할 수도 있겠네.\n하지만 「하얀 악마」는 미아랑 전혀 다르잖아.",
  ui_story_5053_50531002_46_dialog_content = "그 사람은 감정이 전혀 없는 냉혹한 암살자 같았어.\n설마 조슈아 부인한테 실제로 그런 면이 있었단 말이야?",
  ui_story_5053_50531002_47_dialog_content = "그건... 나도 모르겠어. 어머님은 줄곧 선량하고 자상한 분이셨고,\n그런 면은 단 한 번도 보여주신 적 없었어...",
  ui_story_5053_50531002_48_dialog_content = "저기... 잠깐 끼어들어도 될지 모르겠는데요...",
  ui_story_5053_50531002_49_dialog_content = "조슈아 부인은 과거에 확실히 냉혹한 암살자였다고 자기 입으로 인정했어요...",
  ui_story_5053_50531002_50_dialog_content = "오래전, 내 가문은 솔라드 가문의 통치에 반대했고,\n전임 성주, 그러니까 다니엘의 아버지에게 숙청당했어.",
  ui_story_5053_50531002_51_dialog_content = "그때 다른 여러 가문도 함께 살해당했고, 살아남은 건 어린 나와 몇 명의 사람뿐이었어.",
  ui_story_5053_50531002_52_dialog_content = "우린 모두 솔라드 가문을 증오했고, 한마음으로 자신의 가문을 위해 복수를 맹세했어.",
  ui_story_5053_50531002_53_dialog_content = "그리고 난 어느 유족의 가정에 들어갔고, 솔라드 가문의 손에 죽은\n그 집의 딸을 대신해서 하이가든에 갈 수 있었어.",
  ui_story_5053_50531002_54_dialog_content = "뭐...?! 그런 일이 가능해?! 그분은 성주님의 부인이잖아?!",
  ui_story_5053_50531002_55_dialog_content = "거짓말일 수도 있어!",
  ui_story_5053_50531002_56_dialog_content = "물론 저도 믿기 힘들어요...",
  ui_story_5053_50531002_57_dialog_content = "......",
  ui_story_5053_50531002_58_dialog_content = "미아, 너도 안 믿지?!",
  ui_story_5053_50531002_59_dialog_content = "아니, 사실... 그게 진짜라면 내가 가지고 있던 몇 가지 의문도 풀리거든.",
  ui_story_5053_50531002_60_dialog_content = "어머님은 무척 대단한 분이셨어. 위대하다고까지 말할 수 있다고 생각해.",
  ui_story_5053_50531002_61_dialog_content = "어머님은 백야성 성주의 부인이라는 지위에 있으면서도 항상 초심을 잃지 않고,\n선량한 마음씨와 이성적인 사고를 지켜오셨어...",
  ui_story_5053_50531002_62_dialog_content = "집에선 아버님과 우릴 돌보고, 밖에선 공작부인으로서의 강인한 의지를 보여주셨고 말이야.",
  ui_story_5053_50531002_63_dialog_content = "어머님은 단 한 순간도 그 어떤 명예나 부에 눈이 멀지 않으셨고,\n수많은 선택의 순간마다 언제나 당신을 희생하는 길만을 택하셨어.",
  ui_story_5053_50531002_64_dialog_content = "그건 절대 평범하고 부유한 가정의 귀족 아가씨가 해낼 수 있는 일이 아냐.",
  ui_story_5053_50531002_65_dialog_content = "슬픈 과거의 경험, 오랜 시간의 희생... 자신의 마음을 억누르지만,\n그 누구에게도 이해받지 못하는...",
  ui_story_5053_50531002_66_dialog_content = "그런 어머님의 고통은 내 고통보다 몇천 배, 몇만 배는 더 컸을 거야.",
  ui_story_5053_50531002_67_dialog_content = "그래서 난 사실 어머님의 마음속에 증오로 가득한 「하얀 악마」가 살고 있다고 해도,\n이해할 수 있다고 생각해.",
  ui_story_5053_50531002_68_dialog_content = "그랬구나...",
  ui_story_5053_50531002_69_dialog_content = "조슈아 부인은 정말 대단하시네요... 하지만... 너무 불쌍해요.",
  ui_story_5053_50531002_70_dialog_content = "근데 내 추측이 사실이라면, 왜 바바 야가는 내 몸에서 분열되지 않은 걸까?",
  ui_story_5053_50531002_71_dialog_content = "그러게, 그건 확실히 너랑 조슈아 부인이 다른 점이야.",
  ui_story_5053_50531002_72_dialog_content = "미아랑 바바 야가는 친구고, 바바 야가는 항상 널 지키고 있어.",
  ui_story_5053_50531002_73_dialog_content = "어쩌면 바바 야가는 혹시 네가 이 세계에서 분열되길 바라지 않아서\n일부러 안 나오고 있는 게 아닐까?",
  ui_story_5053_50531002_74_dialog_content = "반면에 조슈아 부인은 두 인격이 서로 대립하고 있어서 그렇고 말이야.",
  ui_story_5053_50531002_75_dialog_content = "그, 그런 걸까... 그런 거라면 다행이고...\n난 또 내가 멋대로 드레스를 갈아입어서 바바 야가가 화난 줄 알았어...",
  ui_story_5053_50531002_76_dialog_content = "그 애가 그렇게 날 배려해 주는 거라면, 돌아가서 제대로 고맙다고 해야겠네...",
  ui_story_5053_50531002_77_dialog_content = "아무튼 아까 「하얀 악마」가 했던 말로 보면...",
  ui_story_5053_50531002_78_dialog_content = "우리 모두 아무도 안 다치고 여기서 나가고 싶다면,\n저 둘을 함께 데리고 나가는 수밖에 없어요.",
  ui_story_5053_50531002_79_dialog_content = "「하얀 악마」... 이번 건 거짓말 아니겠죠...?",
  ui_story_5053_50531002_80_dialog_content = "거짓말은 아닌 것 같아. 첫 회귀 전 부인이 보였던 행동과 말이 맞으니까.",
  ui_story_5053_50531002_81_dialog_content = "대신 우리도 부인한테 다른 비장의 카드가 있을 가능성을 대비해야 돼...",
  ui_story_5053_50531002_82_dialog_content = "......",
  ui_story_5053_50531002_83_dialog_content = "미아?",
  ui_story_5053_50531002_84_dialog_content = "지금 저런 어머님이 여기서 나가시면...\n현실 세계에선 어떻게 되실지 생각하고 있었어...",
  ui_story_5053_50531002_85_dialog_content = "계속해서 죽느니만도 못한 고통을 느끼면서 살아가시거나...\n아니면... 암귀가 되어 버리실까...?",
  ui_story_5053_50531002_86_dialog_content = "그건... 좋은 쪽으로 생각하는 수밖에 없어.",
  ui_story_5053_50531002_87_dialog_content = "적어도 지금은 성주님이나 칼렙 씨, 그리고 나랑 쟈키니도 있잖아.",
  ui_story_5053_50531002_88_dialog_content = "모두가 힘을 합치면 분명히 지금보다는 좋아질 거야.",
  ui_story_5053_50531002_89_dialog_content = "그리고 그 모든 건 이 세계에서 벗어나는 것부터 시작이야!",
  ui_story_5053_50531002_90_dialog_content = "...응, 맞아!",
  ui_story_5053_50531002_91_dialog_content = "근데 저 둘을 동시에 데리고 나가는 건 쉽지 않을 텐데요.\n「하얀 악마」가 얌전히 따라올 것 같진 않아요.",
  ui_story_5053_50531002_92_dialog_content = "게다가 다른 자신을 보고 역겨운 괴물이라고까지 했는데,\n다시 하나가 되려고 하진 않을 거예요...",
  ui_story_5053_50531002_93_dialog_content = "맞아, 그러니까 우릴 전부 죽이려는 거지.",
  ui_story_5053_50531002_94_dialog_content = "지금 생각할 수 있는 최선의 방법은 힘으로 데리고 나가는 것밖에 없어.",
  ui_story_5053_50531002_95_dialog_content = "하지만 드래곤이랑 경비병들도 우릴 막을 거야...",
  ui_story_5053_50531002_96_dialog_content = "쟈키니, 혹시 드래곤이나 경비병들이 미쳐버린 이유도 알아?",
  ui_story_5053_50531002_97_dialog_content = "음, 어디 보자... 아, 찾았어요.\n「영원한 기억의 수정」을 가동한 자는 내부 세계에 어느 정도 개입할 수 있다고 해요.",
  ui_story_5053_50531002_98_dialog_content = "엄마도 진짜, 왜 이렇게 긴가민가하게 써 둔 거야?!",
  ui_story_5053_50531002_99_dialog_content = "이렇게 된 이상 제 머릿속 지식으로 답을 찾는 수밖에 없겠네요. 으음...",
  ui_story_5053_50531002_100_dialog_content = "「영원한 기억의 수정」은 <color=#FFB400>거울 호수의 물</color>이랑 <color=#FFB400>가동자의 루미나</color>를 동력으로\n내부의 세계를 구성하고 있어요.",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>가동자의 루미나</color>는... 조슈아 부인의 루미나죠!\n그러니까 지금 보이는 환영들은 전부 조슈아 부인의 루미나로 만들어진 거예요.",
  ui_story_5053_50531002_102_dialog_content = "전에 부인이 힘을 빼앗겼다는 말 하지 않았어요?",
  ui_story_5053_50531002_103_dialog_content = "맞아...",
  ui_story_5053_50531002_104_dialog_content = "게다가 모두의 루미나를 흡수해서 더 강해진다고도 했어.",
  ui_story_5053_50531002_105_dialog_content = "이제 알겠어요! 그런 거였네요!",
  ui_story_5053_50531002_106_dialog_content = "「하얀 악마」는 힘의 절반을 「검은 천사」에게 빼앗겼어요.",
  ui_story_5053_50531002_107_dialog_content = "그리고 남아있을 수도 있는 나머지 절반의 힘은...\n「영원한 기억의 수정」 속 환영을 제어하는 데 쓰이고 있을 거예요!",
  ui_story_5053_50531002_108_dialog_content = "저 환영들은 애초에 전부 조슈아 부인의 루미나로 이루어진 거니까요...",
  ui_story_5053_50531002_109_dialog_content = "그러니 자신의 루미나로 간섭... 아니지, 환영을 「오염」시킬 수 있을 거예요!",
  ui_story_5053_50531002_110_dialog_content = "그럼 결국 「하얀 악마」가 했던 말은 죄다 거짓말이었다는 거잖아요?\n잘도 우릴 속였네요!",
  ui_story_5053_50531002_111_dialog_content = "그런 말도 안 되는 일이 가능하단 말이야?\n잠깐만... 그럼 밖에서 싸우고 있는 미즈 로트는...!",
  ui_story_5053_50531002_112_dialog_content = "...아주 위험한 상황일지도 모르겠네요.",
  ui_story_5053_50531002_113_dialog_content = "무서워... 어떻게 그렇게 치밀하고 잔인할 수 있는 거지...",
  ui_story_5053_50531002_114_dialog_content = "난 지금까지 어머님에게서 공포란 걸 느껴본 적이 없었어.\n하지만 만약 어머님이 원래의 그 상냥함을 잃는다면...",
  ui_story_5053_50531002_115_dialog_content = "저렇게 무서운 사람이 되어버리시는 걸까...?",
  ui_story_5053_50531002_116_dialog_content = "드래곤과 광기에 빠진 사람들은 모두 「하얀 악마」의 체스말이야.\n저들을 쓰러트리고 「하얀 악마」의 힘을 소모시키는 것 외에...",
  ui_story_5053_50531002_117_dialog_content = "우리가 우위에 설 수 있는 방법이 더 없을까?\n...아, 떠올랐어.",
  ui_story_5053_50531002_118_dialog_content = "이번 시간대에서 「검은 천사」는 솔라드 씨 외의 가족들한테 우호적이었어.\n게다가 「하얀 악마」는 「검은 천사」를 못 죽여.",
  ui_story_5053_50531002_119_dialog_content = "그럼 만약 「검은 천사」를 우리 편으로 만들 수 있다면, 승산은 많이 높아질 거야.",
  ui_story_5053_50531002_120_dialog_content = "그거 꽤나 대담한 발상이네요! 그런 PlayerName 씨 스타일, 전 마음에 들어요~",
  ui_story_5053_50531002_121_dialog_content = "근데 PlayerName 씨... 지금 꼭 말해둬야 할 게 있어요.",
  ui_story_5053_50531002_122_dialog_content = "지금 「영원한 기억의 수정」의 루미나라면, 다음 회귀가 마지막이 될 거예요.",
  ui_story_5053_50531002_123_dialog_content = "그러니까... 다른 선택지는 없어요. 이번에 돌아가면 무조건 성공해야 돼요!",
  ui_story_5053_50531002_124_dialog_content = "무, 무조건 성공인가... 알겠어...",
  ui_story_5053_50531002_125_dialog_content = "PlayerName, 회귀한 뒤에 추격병을 피해서 곧바로 「하얀 악마」의 정체를\n모두에게 밝히는 건 어떨까?",
  ui_story_5053_50531002_126_dialog_content = "와... 미아 씨가 PlayerName 씨보다 대담할 줄은 몰랐네요....\n왠지 제 머릿속 미아 씨의 이미지가 좀 바뀔 것 같아요.",
  ui_story_5053_50531002_127_dialog_content = "그, 그래?",
  ui_story_5053_50531002_128_dialog_content = "응, 나도 그건 위험이 너무 크다고 생각해.",
  ui_story_5053_50531002_129_dialog_content = "난 내 몸을 지킬 힘이 없어. 날 없애는 건 「하얀 악마」한테는 쉬운 일이야.",
  ui_story_5053_50531002_130_dialog_content = "게다가 너희도 기억이 없는 상황에서 그런 충격적인 얘기를 듣고\n바로 납득하긴 어려울 거야.",
  ui_story_5053_50531002_131_dialog_content = "확실히 그렇긴 해... 특히 외삼촌은 분명히 쉽게 믿지 않을 거야.",
  ui_story_5053_50531002_132_dialog_content = "하지만 우리 일은 PlayerName 네가 너무 걱정할 필요는 없을 것 같아.",
  ui_story_5053_50531002_133_dialog_content = "아버님은 정말 예리하신 분이야.\n이번에도 처음 「하얀 악마」와 이야기할 때부터 아버님은 이미 조금 의심하기 시작하셨거든.",
  ui_story_5053_50531002_134_dialog_content = "외삼촌한테 남아서 「하얀 악마」를 지켜보라고 하신 것도\n아마 외삼촌이 직접 진상을 볼 수 있게 만들기 위해서였을 거야...",
  ui_story_5053_50531002_135_dialog_content = "그러니까 넌 「검은 천사」만 조심하면 될 것 같아.",
  ui_story_5053_50531002_136_dialog_content = "역시 성주님이라니까...",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>쾅, 콰앙!</color>",
  ui_story_5053_50531002_138_dialog_content = "으앗, 무슨 소리죠?!",
  ui_story_5053_50531002_139_dialog_content = "이런, 경비병들이 왔나 봐!",
  ui_story_5053_50531002_140_dialog_content = "내가 문을 막을 테니까, 쟈키니는 지금 바로 시간을...",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5053_50531002_142_dialog_content = "미아! 조심해!",
  ui_story_5053_50531002_143_dialog_content = "저건...",
  ui_story_5053_50531002_144_dialog_content = "......",
  ui_story_5053_50531002_145_dialog_content = "미즈 로트...?!",
  ui_story_5053_50531002_146_dialog_content = "미아, 물러서!",
  ui_story_5053_50531002_147_dialog_content = "...안 돼.",
  ui_story_5053_50531002_148_dialog_content = "미즈 로트는 분명히 무척 고통스러울 거야.\n카렌이 마지막 이성을 붙잡고 저항했던 것처럼...",
  ui_story_5053_50531002_149_dialog_content = "...이번엔 나도 망설이지 않을 거야.\n카렌과 같은 고통을 겪게 만들진 않겠어.",
  ui_story_5053_50531002_150_dialog_content = "제가 고통에서 구해줄게요.",
  ui_story_5053_50531002_151_dialog_content = "자! 시작하죠!",
  ui_story_5053_50531002_152_dialog_content = "──!",
  ui_story_5053_50531002_153_dialog_content = "미아...",
  ui_story_5053_50531002_154_dialog_content = "미아가 막아주는 동안... 우린 시간을 되돌리자, 쟈키니.",
  ui_story_5053_50531002_155_dialog_content = "깨어나면 일단 「검은 천사」부터 찾고... 그리고 경비병들을 피해서...",
  ui_story_5053_50531002_156_dialog_content = "PlayerName 씨... 손이 떨리고 있어요.",
  ui_story_5053_50531002_157_dialog_content = "......",
  ui_story_5053_50531002_158_dialog_content = "그런 막중한 임무를 혼자 감당해야 하니까 당연히 긴장되겠죠.\n하지만 겁내지 마요.",
  ui_story_5053_50531002_159_dialog_content = "우린 무슨 일이 있어도 당신을 믿으니까요. 분명히 잘될 거예요!",
  ui_story_5053_50531002_160_dialog_content = "쟈키니...!",
  ui_story_5053_50531002_161_dialog_content = "응! 그럼 이 기세로 가자!",
  ui_story_5053_50531002_162_dialog_content = "「레트로, 레트로, 레트로!」\n시간을 기점으로 되돌려 주세요...",
  ui_story_5053_50531002_163_dialog_content = "「아브라카다브라!」",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>──세 번째 회귀 후──</color>",
  ui_story_5053_50531101_1_dialog_content = "성주 전하, 퍼레이드 준비를 마쳤습니다.",
  ui_story_5053_50531101_2_dialog_content = "마차는 이미 입구에서 대기하고 있습니다. 언제든지 출발하실 수 있습니다.",
  ui_story_5053_50531101_3_dialog_content = "음, 알겠다.",
  ui_story_5053_50531101_4_dialog_content = "카렌, 넌 먼저 가서 타거라.",
  ui_story_5053_50531101_5_dialog_content = "카렌은... 어머님 곁에 남고 싶어요!",
  ui_story_5053_50531101_6_dialog_content = "쟈키니... 미아... 내가 꼭...",
  ui_story_5053_50531101_7_dialog_content = "으음... 여긴...?",
  ui_story_5053_50531101_8_dialog_content = "(아, 쟈키니가 시간을 되돌려 줬구나...)",
  ui_story_5053_50531101_9_dialog_content = "(창밖엔... 젊은 성주님이 카렌을 데리고 저택을 나서고 있어.)",
  ui_story_5053_50531101_10_dialog_content = "(시간은 딱 맞아. 다시 돌아왔어!)",
  ui_story_5053_50531101_11_dialog_content = "(그럼 제일 먼저 해야 할 일은...)",
  ui_story_5053_50531101_12_dialog_content = "수상한 인물... 부인의 명령... 처리한다...",
  ui_story_5053_50531101_13_dialog_content = "수상한 인물... 여긴 없다...",
  ui_story_5053_50531101_14_dialog_content = "(휴~ 일단 추격병 따돌리기는 성공!)",
  ui_story_5053_50531101_15_dialog_content = "(미아랑 쟈키니가 세운 계획에 따라 지금 해야 할 건 세 가지야.)",
  ui_story_5053_50531101_16_dialog_content = "(첫째, 「검은 천사」를 먼저 찾고 설득해서 우릴 돕게 만들기.)",
  ui_story_5053_50531101_17_dialog_content = "(둘째, 드래곤과 정신이 오염된 자들의 습격을 막아서 변수 없애기.)",
  ui_story_5053_50531101_18_dialog_content = "(셋째, 아무도 희생하지 않는다는 전제하에 「하얀 악마」 제압하기.)",
  ui_story_5053_50531101_19_dialog_content = "(미아, 쟈키니...)",
  ui_story_5053_50531101_20_dialog_content = "(이번이 마지막 회귀야. 반드시 성공해야만 해. 실패는 있을 수 없어.)",
  ui_story_5053_50531101_21_dialog_content = "수상한 인물... 처리한다...",
  ui_story_5053_50531101_22_dialog_content = "!!",
  ui_story_5053_50531101_23_dialog_content = "여긴... 없다...",
  ui_story_5053_50531101_24_dialog_content = "(위험했어... 지금까지의 경험으로 보면, 「하얀 악마」의 통제를 받는\n이 병사들은 계속해서 날 추적할 거야.)",
  ui_story_5053_50531101_25_dialog_content = "(시간도, 능력도, 행동 범위에도 제한이 있어.\n결국 난 그 세 가지 일을 동시에 해야만 해.)",
  ui_story_5053_50531101_26_dialog_content = "(한번 부딪혀 보는 수밖에 없어!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5053_50531102_2_dialog_content = "으윽... 큭...",
  ui_story_5053_50531102_3_dialog_content = "「검은 천사」는 어디 간 거지?",
  ui_story_5053_50531102_4_dialog_content = "바깥의 오솔길을 따라 도망친 것 같은데요?",
  ui_story_5053_50531102_5_dialog_content = "성주님의 방금 그 공격, 정말 하늘도 땅도 다 갈라버릴 것 같았어요!",
  ui_story_5053_50531102_6_dialog_content = "아무튼 다들 안 다쳐서 다...",
  ui_story_5053_50531102_7_dialog_content = "어머, 다들 여기 있었구나.",
  ui_story_5053_50531102_8_dialog_content = "어머님... 지금 왜 여기 계세요? 퍼레이드에 가신 거 아니었나요?",
  ui_story_5053_50531102_9_dialog_content = "......",
  ui_story_5053_50531102_10_dialog_content = "...정원에 불청객이 있는 모양이네.",
  ui_story_5053_50531102_11_dialog_content = "다들 괜찮니?",
  ui_story_5053_50531102_12_dialog_content = "누나? 아니... 그럼 방금 도망간 그 「검은 천사」는 대체...",
  ui_story_5053_50531102_13_dialog_content = "후훗, 우리 천재 군도 머리가 잘 안 돌아갈 때가 있는 모양이구나.",
  ui_story_5053_50531102_14_dialog_content = "괜찮아, 방금까지 싸웠으니까 분명히 힘들겠지. 먼저 들어가서 좀 앉으렴.",
  ui_story_5053_50531102_15_dialog_content = "그 괴물은 내가 사람을 보내서 추적하게 할 테니까.",
  ui_story_5053_50531102_16_dialog_content = "잠시만요, 어머님. 음... 뭔가 이상해요...",
  ui_story_5053_50531102_17_dialog_content = "혹시... 아무도 PlayerName 못 보셨나요?",
  ui_story_5053_50531102_18_dialog_content = "그러게요, PlayerName 씨는요? 왜 안 보이죠?",
  ui_story_5053_50531102_19_dialog_content = "애초부터 그는 이곳에 있지 않았다.",
  ui_story_5053_50531102_20_dialog_content = "그런...",
  ui_story_5053_50531102_21_dialog_content = "죄송해요, 어머님. 저흰 PlayerName 좀 찾으러 가 봐야 할 것 같아요...\n어쩌면 위험에 처했을지도 몰라요...",
  ui_story_5053_50531102_22_dialog_content = "으음, 역시 베로니카는 친구를 배려할 줄 아는 상냥한 아이라니까.\n하지만 엄마는 모두에게 전할 더 중요한 얘기가 있거든.",
  ui_story_5053_50531102_23_dialog_content = "나도 사람을 보내서 PlayerName 그 아이를 찾으라고 할 테니까,\n먼저 안으로 들어가는 게 어떠니?",
  ui_story_5053_50531102_24_dialog_content = "네? 음... 아, 알겠어요...",
  ui_story_5053_50531102_25_dialog_content = "...그러한가.",
  ui_story_5053_50531102_26_dialog_content = "한 젊은이의 생사 안위에 그토록 담담할 수 있다니, 그대답지 않군.",
  ui_story_5053_50531102_27_dialog_content = "어머, 제가 당신 마음속에서 그렇게 나약한 이미지였나요? 「다니엘」.",
  ui_story_5053_50531102_28_dialog_content = "......",
  ui_story_5053_50531102_29_dialog_content = "다니엘? 누나! 어떻게 알아챈 거죠...? 설마?!",
  ui_story_5053_50531201_1_dialog_content = "허억, 헉...",
  ui_story_5053_50531201_2_dialog_content = "(바, 방금 확실히 이쪽으로 갔는데... 왜 또 안 보이지?)",
  ui_story_5053_50531201_3_dialog_content = "다...니엘...",
  ui_story_5053_50531201_4_dialog_content = "(찾았다! 나무상자 뒤에 있어!)",
  ui_story_5053_50531201_5_dialog_content = "...!!",
  ui_story_5053_50531201_6_dialog_content = "잠깐만요, 전 당신이랑 싸우러 온 게 아니에요!\n지금 칼렙 씨랑 미아가 위험해요... 다들 당신 도움이 필요하다구요!",
  ui_story_5053_50531201_7_dialog_content = "칼...렙...? 미아...?",
  ui_story_5053_50531201_8_dialog_content = "네, 당신 동생 칼렙 씨랑 당신 딸 베로니카요.",
  ui_story_5053_50531201_9_dialog_content = "당신이 사랑하는 가족들이잖아요, 맞죠?",
  ui_story_5053_50531201_10_dialog_content = "사랑하는... 가족...",
  ui_story_5053_50531201_11_dialog_content = "당신 가족들은 지금 위험에 빠져 있어요. 저들은 당신이 필요해요.",
  ui_story_5053_50531201_12_dialog_content = "가족들이... 위험...",
  ui_story_5053_50531201_13_dialog_content = "저기... 괜찮아요...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>...가...족...... 다...니엘...!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "으앗?! 좀 진정하세요! 목소리가 너무 크면 병사들이 따라올 거라구요!",
  ui_story_5053_50531201_16_dialog_content = "(칼렙이 위험하단 말을 들었을 땐 도와주려고 했는데,\n왜 지금은 오히려 더 사나워지는 거지?)",
  ui_story_5053_50531201_17_dialog_content = "(설마 가족인 미아만 「검은 천사」를 진정시킬 수 있는 건가?!)",
  ui_story_5053_50531201_18_dialog_content = "아...아파...!",
  ui_story_5053_50531201_19_dialog_content = "(어떡하지... 빨리 방법을 떠올려! 시간이 없어!)",
  ui_story_5053_50531201_20_dialog_content = "울지... 말렴...",
  ui_story_5053_50531201_21_dialog_content = "로니... 울지 말렴... 우리 아가...",
  ui_story_5053_50531201_22_dialog_content = "괜찮아... 슬퍼하지 마...",
  ui_story_5053_50531201_23_dialog_content = "아...",
  ui_story_5053_50531201_24_dialog_content = "(감응 능력이 없는 오로리안들이 서로를 위로하는 방법...\n「검은 천사」에게 평안을 의미하는 것...)",
  ui_story_5053_50531201_25_dialog_content = "(...역시 해 보는 수밖에 없어!)",
  ui_story_5053_50531201_26_dialog_content = "장미... 한 송이를? 어... 귀여운 우리 아이에게 선물↘하자↗♪",
  ui_story_5053_50531201_27_dialog_content = "산들바람이... 네 웃는 얼굴을 어루만지고? 세상에↗ 하나뿐↘♪",
  ui_story_5053_50531201_28_dialog_content = "......?",
  ui_story_5053_50531201_29_dialog_content = "............",
  ui_story_5053_50531201_30_dialog_content = "장미... 한 송이를♪ 소중한 아빠와 엄마에게 선물하자♪",
  ui_story_5053_50531201_31_dialog_content = "닥쳐.",
  ui_story_5053_50531201_32_dialog_content = "내가 노래를 너무 못 불렀나? 그런 거라면 미안하게 됐어.",
  ui_story_5053_50531201_33_dialog_content = "우연히 거리에서 들었던 노래인데, 입에 잘 붙어 한 구절 기억에 남았거든.",
  ui_story_5053_50531201_34_dialog_content = "하지만 선율과 가사 모두 정확히 기억이 나질 않더라고. 추태를 보였네.",
  ui_story_5053_50531201_35_dialog_content = "솔라드 가문의 인간은 다운타운의 노래를 부를 자격 없어.",
  ui_story_5053_50531201_36_dialog_content = "...왜 솔라드 가문을 그토록 미워하는 거지?",
  ui_story_5053_50531201_37_dialog_content = "자신을 위장하고 희생하면서, 내게 접근해 연인이 되어야 할 정도로 말이야.",
  ui_story_5053_50531201_38_dialog_content = "그렇게 당신은 날 발판으로 삼아 아버님의 암살을 시도했어.",
  ui_story_5053_50531201_39_dialog_content = "......",
  ui_story_5053_50531201_40_dialog_content = "그대의 연기는 완벽했고, 전투 능력과 학식도 출중해.",
  ui_story_5053_50531201_41_dialog_content = "그대가 그 능력들을 단련하기 위해 얼마나 많은 시간을 들였을지 상상조차 못 하겠어.",
  ui_story_5053_50531201_42_dialog_content = "5년, 10년, 아니면... 지금까지의 일생인가?",
  ui_story_5053_50531201_43_dialog_content = "그 모든 것이 그저 암살을 위해서, 성공하지 못하면 죽음뿐인 암살을 위해서라니.",
  ui_story_5053_50531201_44_dialog_content = "내 아버님께 그대와 그대 배후의 사람들이 그토록 원망할 가치가 있는 건가?",
  ui_story_5053_50531201_45_dialog_content = "만약 무슨 오해가 있는 거라면, 내가 반드시 아버님을 대신해 해명하겠어.",
  ui_story_5053_50531201_46_dialog_content = "이건 그저 내 아버님의 명예만을 위해서가 아니야.\n...난 그대가 계속해서 증오를 위해 살아가는 것을 보고 싶지 않아.",
  ui_story_5053_50531201_47_dialog_content = "「솔라드」는 강권과 폭정의 화신이야.",
  ui_story_5053_50531201_48_dialog_content = "너희들이 먹는 모든 고기 한 점, 입는 모든 천 한 조각마다\n희생자들의 피가 묻어 있다고.",
  ui_story_5053_50531201_49_dialog_content = "그 「희생자」에는 칼렙의 「친누이」와 그대의 「진짜 가족」도 포함되나?",
  ui_story_5053_50531201_50_dialog_content = "......",
  ui_story_5053_50531201_51_dialog_content = "긴장할 거 없어. 어디까지나 내 추측일 뿐이니까.",
  ui_story_5053_50531201_52_dialog_content = "7년 전, 칼렙의 모친은 반란군의 체포 작전에 휘말려 세상을 떠났어.",
  ui_story_5053_50531201_53_dialog_content = "당시 그의 누이 「조슈아」도 현장에 있었지.",
  ui_story_5053_50531201_54_dialog_content = "허나 그녀는 유일한 생존자로 기적처럼 살아남았어...\n아니지, 「부자연스럽게 살아남았다」고 해야겠지.",
  ui_story_5053_50531201_55_dialog_content = "그리고 지금의 그대라는 새로운 「조슈아」가 탄생했고 말이야. 내 말이 맞겠지?",
  ui_story_5053_50531201_56_dialog_content = "......",
  ui_story_5053_50531201_57_dialog_content = "난 이 추측을 누구에게도 말하지 않았고, 그대가 여기에 있다는 것도 말하지 않았어.",
  ui_story_5053_50531201_58_dialog_content = "모두 그대가 이미 집에 돌아갔다고 생각했고,\n그대의 양부 쪽에도 내가 그렇게 말해 두었지.",
  ui_story_5053_50531201_59_dialog_content = "허나 그대가 돌아가지 않았음에도, 그대의 양아버지는 그대의 실종에 대해\n아무에게도 말하지 않았어.",
  ui_story_5053_50531201_60_dialog_content = "그는 분명히 그대가 돌아오지 않는 이유를 알고 있는 거야.",
  ui_story_5053_50531201_61_dialog_content = "......",
  ui_story_5053_50531201_62_dialog_content = "그럼에도 그는 도망치기는커녕, 나와 그대가 요즘 어떻게 지내는지 수업 때 물었어.\n마치 날 떠보려는 듯이 말이야.",
  ui_story_5053_50531201_63_dialog_content = "군주를 해치려 한 것은 찢겨 죽어 마땅한 죄야.\n하지만 그는 오히려 그대의 안위를 더 걱정하고 있었어.",
  ui_story_5053_50531201_64_dialog_content = "그 온화한 노학자는 증오와 두려움 대신, 그대를 선택했던 거야.",
  ui_story_5053_50531201_65_dialog_content = "난 그를 위해서라도 그대가 이제 내 아버님을 암살하려는 생각은 버렸으면 해.",
  ui_story_5053_50531201_66_dialog_content = "만약 그대가 포기한다면, 난 모든 일을 없었던 것으로 여기고\n그대를 즉시 가족에게 돌려보내겠어.",
  ui_story_5053_50531201_67_dialog_content = "그런 구차한 연극은 집어치워.\n나도, 그 남자도 그런 건 전혀 신경 안 쓰니까.",
  ui_story_5053_50531201_68_dialog_content = "우린 「솔라드」를 향한 증오로 모인 동지들이야.\n이상을 위해 희생할 수 있는 건 더없는 영광이고.",
  ui_story_5053_50531201_69_dialog_content = "그래? 방금 말한 건 아무 증거도 없는 내 추측일 뿐이었는데.",
  ui_story_5053_50531201_70_dialog_content = "정작 그대는 칼렙의 부친과의 협력 관계를 직접 인정해 버렸잖아?",
  ui_story_5053_50531201_71_dialog_content = "하하하, 체크메이트!",
  ui_story_5053_50531201_72_dialog_content = "..................",
  ui_story_5053_50531201_73_dialog_content = "크흠, 농담이었어. 그저 분위기를 좀 풀어보고 싶었을 뿐이야...",
  ui_story_5053_50531201_74_dialog_content = "그대의 불신은 물론 이해할 수 있어.",
  ui_story_5053_50531201_75_dialog_content = "아버님께선 늘 엄정하고 신속하게 모든 반역자들을 철저하게 처단하셨어.\n설령... 마구잡이로 죽이는 한이 있더라도 반역자는 한 놈도 놓치지 않으셨지.",
  ui_story_5053_50531201_76_dialog_content = "그분께선 이 모든 게 외부의 적에 맞설 기풍을 세우기 위한 것이라고 하셨어.",
  ui_story_5053_50531201_77_dialog_content = "모두가 솔라드 가문을 추앙하고, 유일한 지도자를 따르는 기풍 말이야.",
  ui_story_5053_50531201_78_dialog_content = "그렇게 모두가 유일하면서도 올바른 지도를 믿게 될 때,\n탐욕스럽고 이기적인 자는 숨을 곳이 없게 되겠지.",
  ui_story_5053_50531201_79_dialog_content = "그리고 모든 더러움이 제거되고 나면,\n백야성은 세상에서 가장 깨끗하고 순수한 곳이 될 거야.",
  ui_story_5053_50531201_80_dialog_content = "아버님의 이상은 위대해. 난 아버님을 무척 존경해.",
  ui_story_5053_50531201_81_dialog_content = "다만... 아버님의 위업은 아직 세워지는 도중이고,\n그분의 이상은 아직 모두에게 완전히 받아들여지진 못했어.",
  ui_story_5053_50531201_82_dialog_content = "그대가 우리 집에 왔을 때 주변 사람들의 표정을 알아차렸는진 모르겠어.",
  ui_story_5053_50531201_83_dialog_content = "내가 있을 땐 모두가 긴장하고, 아첨하는 얼굴을 한다는 것 말이야.",
  ui_story_5053_50531201_84_dialog_content = "그러다 난 멀리서 모두가 사적으로 웃는 걸 본 적이 있었는데,\n난 그제서야 그게 사람들이 진심으로 기뻐하는 모습이라는 걸 알았어.",
  ui_story_5053_50531201_85_dialog_content = "그래서 난 아버님께 물었어.\n왜 모두가 날 대할 때 그렇게 다른 모습을 보이냐고 말이야.",
  ui_story_5053_50531201_86_dialog_content = "아버님께선 그러셨지.\n그건 사람들이 더럽고 교활한 삶의 방식에 익숙해져 있기 때문이라고.",
  ui_story_5053_50531201_87_dialog_content = "그래서 절대적인 올바름을 상징하는 솔라드 가문을 똑바로 쳐다볼 수 없는 거라고 말이야.",
  ui_story_5053_50531201_88_dialog_content = "그건 사람들이 근절할 수 없는 나쁜 뿌리고, 그러니 그들은 우리의 인도가 필요해.",
  ui_story_5053_50531201_89_dialog_content = "그리고 그 모든 걸 짊어지고 바로잡는 게 바로 솔라드 가문의 사명이라고 하셨어.",
  ui_story_5053_50531201_90_dialog_content = "...하지만 난 그 숨 막히는 느낌을 견딜 수가 없었어.",
  ui_story_5053_50531201_91_dialog_content = "그래서 벽을 넘어 밖으로 뛰쳐나가서, 신분을 숨기고 잠시나마 긴장을 풀곤 했지.",
  ui_story_5053_50531201_92_dialog_content = "조슈아, 난 그대가 다르다고 생각했어. 그대만이 나와 함께 진심으로 웃어줬으니까.",
  ui_story_5053_50531201_93_dialog_content = "하지만 결국 모든 건 나 혼자만의 희망에 불과했어... 난 여전히 아무것도 몰라.",
  ui_story_5053_50531201_94_dialog_content = "자업자득이야.",
  ui_story_5053_50531201_95_dialog_content = "하하... 그대 말이 맞아, 전부 내가 「솔라드」 가문에서 태어난 탓이니까.",
  ui_story_5053_50531201_96_dialog_content = "그러니까 난 더더욱 그대의 증오를 직시해야만 해.",
  ui_story_5053_50531201_97_dialog_content = "완벽에 가까운 이번 암살 계획은 고작 몇 사람의 솜씨가 아냐.",
  ui_story_5053_50531201_98_dialog_content = "신분 조작, 오랜 시간의 훈련, 관련자들의 협조...",
  ui_story_5053_50531201_99_dialog_content = "대체 얼마나 많은 자들이 힘을 합쳐야, 모든 절차가 이토록 완벽하게 맞물릴 수 있을까.",
  ui_story_5053_50531201_100_dialog_content = "「솔라드」의 중압은 탐욕의 뿌리를 뽑지 못했고,\n오히려 우릴 수많은 백성들의 적으로 만들었어.",
  ui_story_5053_50531201_101_dialog_content = "아버님께서 바라신 건 이런 결과가 아니었을 텐데...",
  ui_story_5053_50531201_102_dialog_content = "잘못을 알았으면 네 아버지를 끌고 가서 같이 죽어버려.\n여기서 능청맞게 날 구슬릴 생각 말고.",
  ui_story_5053_50531201_103_dialog_content = "잘못을 저질렀다고 죽는 건 속죄가 아니라 도피야.",
  ui_story_5053_50531201_104_dialog_content = "아버님의 이상이 전부 틀린 건 아니야. 그분의 정책에도 좋은 면이 있어.",
  ui_story_5053_50531201_105_dialog_content = "그리고 그걸 뒷받침하는 가장 좋은 증거는 바로 이번 암살이고.",
  ui_story_5053_50531201_106_dialog_content = "......?",
  ui_story_5053_50531201_107_dialog_content = "과거의 백야성은 계급과 혈통이 전부였어.",
  ui_story_5053_50531201_108_dialog_content = "권력자는 뇌물을 받고 횡령하고, 법은 통치자의 일방적인 도구일 뿐이었지.\n요직은 힘 있는 자들만이 차지했고...",
  ui_story_5053_50531201_109_dialog_content = "그러나 아버님의 압력 덕분에 다운타운의 주민들도 정의를 세울 권리가 생겼어.",
  ui_story_5053_50531201_110_dialog_content = "귀족들은 스스로 자신의 죄를 털어놓고 용서를 구하기 시작했지.",
  ui_story_5053_50531201_111_dialog_content = "그리고 유능한 자들은 계급에 상관없이 시험을 통해 적절한 평가를 받게 됐어.",
  ui_story_5053_50531201_112_dialog_content = "그것이 바로 아버님께서 원하셨던, 출신을 불문하고 능력과 노력만 보는 세상이야.",
  ui_story_5053_50531201_113_dialog_content = "칼렙의 부친만 봐도 전형적인 평민 학자잖아?",
  ui_story_5053_50531201_114_dialog_content = "만약 내가 말한 이 모든 것에 조금이라도 거짓이 있다면,\n재물과 지위도 없는 그가 재능과 학문에 의지해 하이가든까지 올 순 없었겠지.",
  ui_story_5053_50531201_115_dialog_content = "그리고 그대도 가정교사의 딸이라는 신분으로 내게 접근할 수도 없었을 테고 말이야.",
  ui_story_5053_50531201_116_dialog_content = "이번 암살 계획을 세운 자는 이 사실에 대한 진실한 믿음을 토대로\n그런 중대한 계획을 세울 수 있었던 거야.",
  ui_story_5053_50531201_117_dialog_content = "......",
  ui_story_5053_50531201_118_dialog_content = "그러니까 내게 알려주지 않겠어?\n아버님의 정책이 올바르게 실현되지 않은 점이 구체적으로 어떤 것인지 말이야.",
  ui_story_5053_50531201_119_dialog_content = "암흑가의 세력이 여전히 다운타운 구역을 점거하고 있는 점?\n지나치게 과감한 숙청이 억울한 사례를 낳은 점?",
  ui_story_5053_50531201_120_dialog_content = "만약 이런 일이 있다면, 내가 반드시 끝까지 조사하겠어.",
  ui_story_5053_50531201_121_dialog_content = "어쩌면 지금에 와서 소를 잃고 외양간을 고친다 한들,\n그대의 상처를 메울 수는 없을지도 모르지...",
  ui_story_5053_50531201_122_dialog_content = "허나 적어도 우린 더 많은 사람들을 위해 그러한 잘못들을 제때 바로잡아야 해.",
  ui_story_5053_50531201_123_dialog_content = "...역시 넌 아무것도 몰라.",
  ui_story_5053_50531201_124_dialog_content = "사람들에게 올바른 통치 따윈 필요하지 않아.\n필요한 건 진정한 자유야.",
  ui_story_5053_50531201_125_dialog_content = "진정한... 자유?",
  ui_story_5053_50531201_126_dialog_content = "자신이 원하는 삶의 방식을 택할 수 있고, 갖가지 신분의 낙인이 찍히지 않는 것.",
  ui_story_5053_50531201_127_dialog_content = "자신과 가족의 목숨에 대한 걱정 없이, 마음속 좋고 싫음을 말할 수 있는 것.",
  ui_story_5053_50531201_128_dialog_content = "그게 바로 자유야.",
  ui_story_5053_50531201_129_dialog_content = "그 하인들이 널 무서워하는 건, 잘못된 시기에 내뱉은 한숨 하나로\n그들 온 집안의 목숨을 빼앗길 수 있기 때문이야.",
  ui_story_5053_50531201_130_dialog_content = "출신을 불문하고, 능력과 노력만 봐? 장난해?!",
  ui_story_5053_50531201_131_dialog_content = "너희 「솔라드」가 원하는 건 그저 너희 눈치나 보며 살아가는 가축이라고!",
  ui_story_5053_50531201_132_dialog_content = "......",
  ui_story_5053_50531201_133_dialog_content = "......",
  ui_story_5053_50531201_134_dialog_content = "그래서 그대는 내 아버님을 죽이고, 「솔라드」가 없어지길 원하는구나.",
  ui_story_5053_50531201_135_dialog_content = "그리고 「솔라드」가 없는 그 세상에서 진정으로 자유로운 삶을 살겠다는 건가?",
  ui_story_5053_50531201_136_dialog_content = "그게 바로 그대가 바라는 행복인가? 「조슈아」?",
  ui_story_5053_50531201_137_dialog_content = "난 행복 같은 걸 바라지 않아.",
  ui_story_5053_50531201_138_dialog_content = "암살 계획을 마치는 순간이 곧 내 목숨이 끝나는 순간이야.",
  ui_story_5053_50531201_139_dialog_content = "그 말은 그러니까, 성공하든 그렇지 않든, 그대는 죽음을 택하겠다는 건가?",
  ui_story_5053_50531201_140_dialog_content = "동료들을 지키기 위해서?",
  ui_story_5053_50531201_141_dialog_content = "아니, 사명을 완수하면 더는 구차하게 살아갈 이유가 없으니까.",
  ui_story_5053_50531201_142_dialog_content = "이유가... 없다?",
  ui_story_5053_50531201_143_dialog_content = "귀족들은 자신의 이익을 위해서만 행동하지.\n하지만 우린 이상을 위해서만 살아가.",
  ui_story_5053_50531201_144_dialog_content = "부귀도, 명예도 바라지 않아.\n모든 건 오직 샛별이 떠올라 모든 민중을 비추도록 하기 위해서야.",
  ui_story_5053_50531201_145_dialog_content = "스스로를 불태워 낡은 태양을 쏘아 떨어트리는 것, 우리가 원하는 건 그것뿐이야.\n너희들의 그런 썩어빠진 공리주의적 잣대로 우릴 평가하지 마.",
  ui_story_5053_50531201_146_dialog_content = "으음... 그대가 내게 그토록 많은 말을 해 주어 기쁘긴 하지만,\n어째서 전부 그런 난해한 내용뿐인지, 원.",
  ui_story_5053_50531201_147_dialog_content = "원래 그대는 그런 식으로 말하는 걸 좋아했던 거였나...?",
  ui_story_5053_50531201_148_dialog_content = "만약 「낡은 태양」이 아버님의 지배를 뜻한다면...\n그에 대응하는 「샛별」은 또 다른 새로운 통치자인가?",
  ui_story_5053_50531201_149_dialog_content = "이 모든 게 그대의 배후에서 이 모든 것을 꾸민 자가 아버님을 대신하여\n새로운 통치자가 되도록 위한 것인가?",
  ui_story_5053_50531201_150_dialog_content = "......",
  ui_story_5053_50531201_151_dialog_content = "...인정할 수 없어.",
  ui_story_5053_50531201_152_dialog_content = "동료와 가족을 지키기 위해서 적과 함께 죽음을 맞으려는 건 이해할 수 있어.\n하지만 「구차하게 살아갈 이유가 없다」는 건 대체 뭐지?",
  ui_story_5053_50531201_153_dialog_content = "내가 그대의 사랑을 빼앗아 간 탓에 매일 나와 척지고 있는 그대의 동생...",
  ui_story_5053_50531201_154_dialog_content = "그대의 안위를 걱정하며 그대가 집으로 돌아오길 고대하는 부친...",
  ui_story_5053_50531201_155_dialog_content = "정녕 그들은 그대가 살아가는 이유가 아니란 말인가...?",
  ui_story_5053_50531201_156_dialog_content = "만약 그대가 솔라드 가문이 모든 이들의 자유를 박탈했다고 생각한다면,\n「솔라드」를 파멸시키고 자유롭게 살아가면 되는 게 아닌가!",
  ui_story_5053_50531201_157_dialog_content = "그런데 왜 「솔라드」가 사라져도 여전히 그대는 자유를 얻을 수 없는 거지?",
  ui_story_5053_50531201_158_dialog_content = "만에 하나 아버님께서 뜻밖의 연유로 집에서 급사하신다 해도\n그대는 여전히 자신의 목숨을 끊을 생각인가?!",
  ui_story_5053_50531201_159_dialog_content = "나와 그 남자, 그리고 그의 아들과의 관계가 거짓된 위장이란 건 이미 확인했잖아?",
  ui_story_5053_50531201_160_dialog_content = "난 「솔라드」의 통치를 끝내기 위해 만들어진 무기야.",
  ui_story_5053_50531201_161_dialog_content = "「솔라드」가 사라지면 내 존재 의미도 없게 돼.\n자유는 민중의 것이고, 나와는 무관해.",
  ui_story_5053_50531201_162_dialog_content = "...가식적이야.",
  ui_story_5053_50531201_163_dialog_content = "그 「샛별」이란 자는 그대에게 자유와 사랑이 무엇인지조차 가르쳐 주지 못했어.",
  ui_story_5053_50531201_164_dialog_content = "그런데 그걸 어떻게 더 많은 사람들에게 가져다줄 수 있겠어?",
  ui_story_5053_50531201_165_dialog_content = "......",
  ui_story_5053_50531201_166_dialog_content = "............이제 알았어.",
  ui_story_5053_50531201_167_dialog_content = "난 그대의 세계에 있어 본 적이 없어.\n그래서 고압적인 정책에 대한 사람들의 증오를 이해할 수 없어.",
  ui_story_5053_50531201_168_dialog_content = "그대도 내 세계에 있어 본 적이 없기에,\n사랑과 자유의 구체적인 형태를 이해할 수 없는 거야.",
  ui_story_5053_50531201_169_dialog_content = "이건 우리 스스로는 결코 넘을 수 없는 간극이야.",
  ui_story_5053_50531201_170_dialog_content = "맞아, 그러니까 포기...",
  ui_story_5053_50531201_171_dialog_content = "──그러니까 우린 협력해서 서로의 부족한 부분을 채워야 해!",
  ui_story_5053_50531201_172_dialog_content = "미쳤구나.",
  ui_story_5053_50531201_173_dialog_content = "나나, 그대나, 아버님이나, 그 「샛별」이나 전부 마찬가지야...",
  ui_story_5053_50531201_174_dialog_content = "어쩌면 인간이 다른 처지의 인간과 완전하게 입장을 바꾸어 생각하는 건\n불가능한 일일지도 모르지.",
  ui_story_5053_50531201_175_dialog_content = "하지만 우린 선입견을 버리고 함께 노력해 볼 수 있어.",
  ui_story_5053_50531201_176_dialog_content = "그리고 모든 이의 목소리에 귀를 기울이는, 진정으로 자유로운 세상을 만드는 거야!",
  ui_story_5053_50531201_177_dialog_content = "이것도 그대가 품은 이상이잖아. 그렇지?",
  ui_story_5053_50531201_178_dialog_content = "......",
  ui_story_5053_50531201_179_dialog_content = "내가 그대를 가로막았던 그날부터 난 끊임없이 생각해 왔어.",
  ui_story_5053_50531201_180_dialog_content = "우리가 이렇게 자신의 꿈을 다른 이에게 거는 건 잘못된 선택이 아닐지 말이야.",
  ui_story_5053_50531201_181_dialog_content = "단순히 아버님의 이상을 따르는 것도,\n죽음으로써 그 「샛별」에게 길을 열어주는 것도.",
  ui_story_5053_50531201_182_dialog_content = "어쩌면 모두 운명을 자신의 손에 맡기는 것보다는 진실하지 못할지도 몰라.",
  ui_story_5053_50531201_183_dialog_content = "비록 난 지금 무지하고 막막해.",
  ui_story_5053_50531201_184_dialog_content = "하지만 그대와 함께라면 모든 게 달라질 것이라는 예감이 들어.",
  ui_story_5053_50531201_185_dialog_content = "그러니까 그 첫걸음으로...",
  ui_story_5053_50531201_186_dialog_content = "그대가 날 도와서 시야를 넓히고, 하이가든 바깥의 세계가 대체 어떤 것인지\n이해할 수 있게 해 줘.",
  ui_story_5053_50531201_187_dialog_content = "그래야만 나도 아버님의 정치에 무슨 문제가 있는 건지 확실하게 알 수 있을 테니까.",
  ui_story_5053_50531201_188_dialog_content = "그리고 난 그대를 데리고 마음껏 삶을 느낄 수 있게 해 주겠어.\n그대가 진심 어린 웃음을 보일 수 있도록 말이야.",
  ui_story_5053_50531201_189_dialog_content = "그러면 그대는 그 웃음을 더 많은 사람들에게 전하는 거야!",
  ui_story_5053_50531201_190_dialog_content = "...시시해.",
  ui_story_5053_50531201_191_dialog_content = "백야성엔 너랑 소꿉놀이 해줄 사람은 얼마든지 있는데,\n왜 나한테 시간을 낭비하는 거지?",
  ui_story_5053_50531201_192_dialog_content = "음... 그건...",
  ui_story_5053_50531201_193_dialog_content = "일단... 감히 아버님께 거역하려는 자는 드물고,\n하이가든의 주민들은 대부분 바깥세상을 이해하지 못해...",
  ui_story_5053_50531201_194_dialog_content = "그리고... 크흠, 내가 그대를 처음 만났을 때 말했던 것처럼──",
  ui_story_5053_50531201_195_dialog_content = "난 그대에게 첫눈에 반했으니까!",
  ui_story_5053_50531201_196_dialog_content = "............",
  ui_story_5053_50531201_197_dialog_content = "(「검은 천사」가 벌써 한참 동안 가만히 있었어. 이제 진정된 거겠지...?)",
  ui_story_5053_50531201_198_dialog_content = "저기요~ 이제 좀 차분하게 제 말을 들어주실 수 있겠어요?",
  ui_story_5053_50531201_199_dialog_content = "잘 들으세요. 그 「하얀 악마」가...\n그러니까 또 다른 당신이 지금 칼렙 씨랑 미아를 죽이려고 해요.",
  ui_story_5053_50531201_200_dialog_content = "다들 당신의 도움이...",
  ui_story_5053_50531201_201_dialog_content = "다...니엘...",
  ui_story_5053_50531201_202_dialog_content = "네?",
  ui_story_5053_50531201_203_dialog_content = "다니엘... 왜... 날... 배신했어...!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>다니엘!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "뭐야?! 왜 더 난폭해진 거야?!\n전 성주님이 아니에요! 정신 좀 차려 보세요!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>다니엘! 다니엘!</size>",
  ui_story_5053_50531201_207_dialog_content = "(시간이 없어! 적어도 관심을 끄는 데는 성공했으니까...\n일단 중앙 광장으로 유인하고 나서 다시 생각하자!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>다니엘────</size>",
  ui_story_5053_50531301_1_dialog_content = "오늘 이 특별한 날을 함께 축하하고자 여기에 모인\n백야성의 온 백성들에게 감사의 뜻을 전한다.",
  ui_story_5053_50531301_2_dialog_content = "솔라드 가문은 백야성 정상의 면류관이자, 백야성의 시작이 되었던 초석이다.",
  ui_story_5053_50531301_3_dialog_content = "비록 우리는 이 팔로 백성들을 지키나, 우리의 손에 쥔 검은 백성들이 만든 것이다.",
  ui_story_5053_50531301_4_dialog_content = "오늘 우리는 이곳에 모여 「솔라드」 가문의 미덕을 노래하고,\n백야성 백성들의 미덕을 노래할 것이다.",
  ui_story_5053_50531301_5_dialog_content = "「솔라드 가문의 날」 축제의 개막을 선언한다!",
  ui_story_5053_50531301_6_dialog_content = "축제는 예정대로 시작되었고, 「검은 천사」도 관람석에 나타나지 않았군.",
  ui_story_5053_50531301_7_dialog_content = "방해물을... 제거한다...",
  ui_story_5053_50531301_8_dialog_content = "그렇다면 이 병사들은 또 무엇이란 말인가.",
  ui_story_5053_50531301_9_dialog_content = "이치대로라면, 「영원한 기억의 수정」 속 존재들은 루미나의 환영에 불과하다.",
  ui_story_5053_50531301_10_dialog_content = "헌데 어째서 이성을 잃고 이처럼 소통할 수 없는 산송장이 되었단 말이냐...",
  ui_story_5053_50531301_11_dialog_content = "그럼 아까 작전대로 전 관람석에 가 볼게요.\n「검은 천사」를 발견하면 곧바로 말씀드릴게요.",
  ui_story_5053_50531301_12_dialog_content = "알겠다, 미아. 조심하거라.",
  ui_story_5053_50531301_13_dialog_content = "(미아 쪽은 당분간 문제가 없을 것이다. 허나 PlayerName 그대는\n이러한 상황에서 어딜 간 것이냐.)",
  ui_story_5053_50531301_14_dialog_content = "으음?",
  ui_story_5053_50531301_15_dialog_content = "PlayerName...",
  ui_story_5053_50531301_16_dialog_content = "찾는다... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "잠깐, 그대들의 옷차림은 카르티마 가문의 기사가 아님이 명백하군.",
  ui_story_5053_50531301_18_dialog_content = "축제 기간에 거리를 지키는 것은 카르티마 가문에서 맡고 있거늘,\n그대들은 왜 이곳을 배회하고 있지?",
  ui_story_5053_50531301_19_dialog_content = "(이 병사들, 걸음걸이가 불안정하고 끝없이 무언가를 중얼거린다.\n설마 술이라도 마신 것이냐.)",
  ui_story_5053_50531301_20_dialog_content = "(게다가 왜 저들의 입에서 PlayerName의 이름이 나온단 말이냐.)",
  ui_story_5053_50531301_21_dialog_content = "찾는다... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "없앤다... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "지금 그 말은 못 들은 것으로 여길 수 없겠군.",
  ui_story_5053_50531301_24_dialog_content = "번거롭겠지만 사건의 경위를 제대로 설명하도록.",
  ui_story_5053_50531301_25_dialog_content = "방해물을... 제거한다...!",
  ui_story_5053_50531301_26_dialog_content = "배후를 묻기는커녕 제대로 된 소통조차 할 수 없다니,\n이 병사들은 대체 어떻게 된 일인가.",
  ui_story_5053_50531301_27_dialog_content = "(시간 회귀 후, PlayerName의 존재는 「영원한 기억의 수정」 속 그 누구도\n모르는 것이 마땅하다.)",
  ui_story_5053_50531301_28_dialog_content = "(피맺힌 원한은커녕 그의 존재조차 아는 이가 없어야 할 터.)",
  ui_story_5053_50531301_29_dialog_content = "당신이 시간을 쓸 필요는 없어요. 경비병을 보내서 찾아도 되잖아요.",
  ui_story_5053_50531301_30_dialog_content = "하지만 저 괴물은 모두가 힘을 모으지 않으면 이길 가능성은 낮아요.",
  ui_story_5053_50531301_31_dialog_content = "어느 쪽 일이 더 중요한지 당신이라면 판단할 수 있을 거라 믿어요.\n이성적으로 생각해요, 다니엘.",
  ui_story_5053_50531301_32_dialog_content = "(...조슈아는 우리 일행 외에 PlayerName의 존재를 아는 유일한 사람이다.)",
  ui_story_5053_50531301_33_dialog_content = "(또한 우리 외에 「영원한 기억의 수정」 속 유일한 실제 인간이기도 하지.)",
  ui_story_5053_50531301_34_dialog_content = "(허나, 무슨 이유로 그대는 아무 상관도 없는 저 젊은이를 죽이려 한단 말인가.)",
  ui_story_5053_50531301_35_dialog_content = "(적어도 일단은 칼렙을 그녀의 곁에 두었다.)",
  ui_story_5053_50531301_36_dialog_content = "(그 영리한 녀석이 내 대신 모든 것을 간파해야 할 텐데 말이야.\n부디 재회의 기쁨으로 이성이 흐려지지 않았길 비는 수밖에.)",
  ui_story_5053_50531301_37_dialog_content = "하, 하아... 성주님! 여기 계셨다니 정말 다행이에요!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "아아아악──!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName! 엎드려라!",
  ui_story_5053_50531301_41_dialog_content = "「검은 천사」는 신경 쓰지 마시고 얼른 관람석으로 가세요! 미아가 위험해요!",
  ui_story_5053_50531301_42_dialog_content = "뭐라?",
  ui_story_5053_50531301_43_dialog_content = "그냥 절 믿고 빨리 관람석으로 가 주세요!",
  ui_story_5053_50531301_44_dialog_content = "...알겠다.",
  ui_story_5053_50531301_45_dialog_content = "으앗?! 지, 지금 뭐 하시는 거예요?",
  ui_story_5053_50531301_46_dialog_content = "버둥대지 마라. 내가 그대를 데리고 가도록 하지.",
  ui_story_5053_50531301_47_dialog_content = "?!",
  ui_story_5053_50531301_48_dialog_content = "다...니엘...? 다니엘!!!",
  ui_story_5053_50531301_49_dialog_content = "으악! 밀지 마!",
  ui_story_5053_50531301_50_dialog_content = "무, 무슨 일이야?",
  ui_story_5053_50531301_51_dialog_content = "괴물이다! 괴물이 나타났어!",
  ui_story_5053_50531301_52_dialog_content = "아래쪽이 소란스러운데, 무슨 일이지?",
  ui_story_5053_50531301_53_dialog_content = "<size=30>저건... 아버님, PlayerName, 그리고... 「검은 천사」...?!</size>",
  ui_story_5053_50531301_54_dialog_content = "베로니카, 뭐라고 했지?",
  ui_story_5053_50531301_55_dialog_content = "아, 아무것도 아니에요.",
  ui_story_5053_50531301_56_dialog_content = "저들이 군중을 뚫고 관람석으로 달려온다!",
  ui_story_5053_50531301_57_dialog_content = "경비병! 어서 막지 않고 뭘 하는 것이냐!",
  ui_story_5053_50531301_58_dialog_content = "(검은 천사가 정말로 아버님을 쫓아왔어. 어머님 말씀대로야.)",
  ui_story_5053_50531301_59_dialog_content = "(저들이 왜 관람석 쪽으로 오는지는 모르겠지만, 반드시 아버님을 지켜야 해.)",
  ui_story_5053_50531301_60_dialog_content = "(내 힘이... 내 부름을 들어줘야 할 텐데...!)",
  ui_story_5053_50531301_61_dialog_content = "언니, 무슨 일이야? 광장에서 소란을 피우는 저 사람들은 누구야?",
  ui_story_5053_50531301_62_dialog_content = "아, 아무것도 아니야. 카렌... 넌 절대 함부로 움직이지 마.",
  ui_story_5053_50531301_63_dialog_content = "앞서 달리고 있는 저 남자는 어찌 된 일인가...",
  ui_story_5053_50531301_64_dialog_content = "사람 한 명을 둘러메고 있으면서도 모든 경비병의 저지를 피할 수 있다니.",
  ui_story_5053_50531301_65_dialog_content = "저 모습, 마치...",
  ui_story_5053_50531301_66_dialog_content = "저 노인네가 넘어진 병사들을 밟고 뛰어올랐다! 관람석을 향해 날아온다!",
  ui_story_5053_50531301_67_dialog_content = "경비병, 다른 이들을 보호해라. 내가 저들을 상대하겠다.",
  ui_story_5053_50531301_68_dialog_content = "......",
  ui_story_5053_50531301_69_dialog_content = "그대는 누구인가?",
  ui_story_5053_50531301_70_dialog_content = "PlayerName, 위험은 어디에 있지?",
  ui_story_5053_50531301_71_dialog_content = "노인이여, 먼저 내 질문에 답하라!",
  ui_story_5053_50531301_72_dialog_content = "하늘에 있어요! 곧 올 거예요!",
  ui_story_5053_50531301_73_dialog_content = "저 괴물은 또 뭐야?! 경비병! 경비병! 빨리 날 지켜라! 경비병!",
  ui_story_5053_50531301_74_dialog_content = "다니...엘? 다니엘...? 다니엘......",
  ui_story_5053_50531301_75_dialog_content = "아아아악── 다니엘──!",
  ui_story_5053_50531301_76_dialog_content = "아버님을 해치게 두진 않아요!",
  ui_story_5053_50531301_77_dialog_content = "...왔어요! 드래곤이 왔다구요!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>크오오──!</size>",
  ui_story_5053_50531301_79_dialog_content = "...드래곤?",
  ui_story_5053_50531301_80_dialog_content = "카르티마 가문의 핏줄에 새겨진 계약... 허나 어째서 이토록 일찍 온 거지?",
  ui_story_5053_50531301_81_dialog_content = "잔꾀를 부리지 말고 눈앞의 위기 대응에 전념하게.",
  ui_story_5053_50531301_82_dialog_content = "카르티마의 역적이여, 그대가 명령을 내릴 기회는 오지 않는다!",
  ui_story_5053_50531301_83_dialog_content = "집중하게! 귀하의 적이 누구인지 확실히 분간하란 말일세!\n놈이 온다!",
  ui_story_5053_50531301_84_dialog_content = "......",
  ui_story_5053_50531301_85_dialog_content = "드, 드래곤?!\n<size=30>기억이 맞다면 드래곤은 지금 나타날 때가 아닌데...</size>",
  ui_story_5053_50531301_86_dialog_content = "언니, 무서워하지 마! 카렌이 지켜줄게!",
  ui_story_5053_50531301_87_dialog_content = "<size=30>아니야... 반란이 일찍 시작된 거야...</size>\n카렌, 어서 숨어!",
  ui_story_5053_50531301_88_dialog_content = "카...렌...? 미...아...?",
  ui_story_5053_50531301_89_dialog_content = "크아아!",
  ui_story_5053_50531301_90_dialog_content = "드래곤이 공격하기 시작했어요!",
  ui_story_5053_50531301_91_dialog_content = "──────!!!",
  ui_story_5053_50531301_92_dialog_content = "드래곤이 어디서 나타난 거지?!",
  ui_story_5053_50531301_93_dialog_content = "으아앙── 아빠... 어디 있어?",
  ui_story_5053_50531301_94_dialog_content = "놈이 불을 뿜는다! 어서 도망쳐!",
  ui_story_5053_50531301_95_dialog_content = "얘야! 아들아! 어디 간 거야?!",
  ui_story_5053_50531301_96_dialog_content = "......",
  ui_story_5053_50531301_97_dialog_content = "혹시 남자애 하나 못 보셨습니까? 키가 이 정도고...",
  ui_story_5053_50531301_98_dialog_content = "...늘려라... 없애라...",
  ui_story_5053_50531301_99_dialog_content = "네? 뭐라고요?",
  ui_story_5053_50531301_100_dialog_content = "동료를 늘려라... 저들을 없애라...",
  ui_story_5053_50531301_101_dialog_content = "으악! 대체 무슨...",
  ui_story_5053_50531301_102_dialog_content = "동료를 늘려라... 저들을 없애라...",
  ui_story_5053_50531301_103_dialog_content = "콜록콜록... 언니, 아버님... 어디 계세요?",
  ui_story_5053_50531301_104_dialog_content = "카렌! 괜찮아?!",
  ui_story_5053_50531301_105_dialog_content = "응... 카렌은 사레들렸을 뿐이야. 카렌은 괜찮아.",
  ui_story_5053_50531301_106_dialog_content = "다행이야...",
  ui_story_5053_50531301_107_dialog_content = "미아... 카렌...",
  ui_story_5053_50531301_108_dialog_content = "해냈어요! 다 같이 드래곤의 습격을 막아냈네요!",
  ui_story_5053_50531301_109_dialog_content = "(역시 「검은 천사」를 진정시킬 수 있는 건 가족뿐이었구나.\n과정은 아슬아슬했지만 역시 내 선택이 옳았어!)",
  ui_story_5053_50531301_110_dialog_content = "기뻐하기엔 아직 이르다.",
  ui_story_5053_50531301_111_dialog_content = "놈은 다시 화염을 토할 힘을 모으고자 잠시 하늘로 올라가 선회하고 있을 뿐이다.",
  ui_story_5053_50531301_112_dialog_content = "다음 공격이 곧 올 것이다.",
  ui_story_5053_50531301_113_dialog_content = "그렇다면 놈이 공격하기 전에 단칼에 베면 되겠군.",
  ui_story_5053_50531301_114_dialog_content = "되도록 첫 공격으로 놈의 약점을 찌르는 게 좋네.",
  ui_story_5053_50531301_115_dialog_content = "놈의 약점은...",
  ui_story_5053_50531301_116_dialog_content = "물론 알고 있다.",
  ui_story_5053_50531301_117_dialog_content = "소용없어요! 저 드래곤은 「불사성」을 가지고 있어서 상처가 빨리 치유될 거예요!",
  ui_story_5053_50531301_118_dialog_content = "뭐라?",
  ui_story_5053_50531301_119_dialog_content = "성주님! 폭동이 시작되었습니다!",
  ui_story_5053_50531301_120_dialog_content = "기존 계획대로 병사를 배치해 역적들을 토벌하라.",
  ui_story_5053_50531301_121_dialog_content = "광장의 드래곤은 내게 맡기고, 나머지 인원들은 가서 백성들을 대피시키도록.",
  ui_story_5053_50531301_122_dialog_content = "허, 허나... 반란군뿐만 아니라 주변의 백성들...\n심지어 저희 병사들까지 폭동에 가담하기 시작했습니다!",
  ui_story_5053_50531301_123_dialog_content = "뭐라...?!",
  ui_story_5053_50531301_124_dialog_content = "게다가 폭동에 가담한 자들의 표정이 무척 이상했습니다.\n저들은 정신이 혼미해서 피아 구분 없이 모든 산 사람을 공격하고 있습니다.",
  ui_story_5053_50531301_125_dialog_content = "더욱 이상한 건 저들에게 상처를 입은 사람이 저들과 한패가 된다는 겁니다! 마치...",
  ui_story_5053_50531301_126_dialog_content = "전염성을 지닌 살아 있는 시체들처럼 말이죠?",
  ui_story_5053_50531301_127_dialog_content = "그렇습니다!",
  ui_story_5053_50531301_128_dialog_content = "보아하니 그대는 일의 내막을 적지 않게 알고 있는 모양이군.",
  ui_story_5053_50531301_129_dialog_content = "시간이 많지 않다. 이 모든 게 어떻게 된 일인지 내게 고하라.",
  ui_story_5053_50531301_130_dialog_content = "아, 그게...",
  ui_story_5053_50531301_131_dialog_content = "(젊은 성주님도 지금 날 쳐다보고 있어...)",
  ui_story_5053_50531301_132_dialog_content = "(만족할 만한 답을 주지 못하면 분명히 날 그냥 보내주진 않을 거야.)",
  ui_story_5053_50531301_133_dialog_content = "(하지만 진실을 말한다면 오히려 더 믿지 않을 거야.\n역시 잘 꾸며서 말하는 수밖에 없어... 으으...)",
  ui_story_5053_50531301_134_dialog_content = "그렇게나 내 앞에서 진실을 털어놓는 걸 꺼리는 것인가?",
  ui_story_5053_50531301_135_dialog_content = "아니면 이 모든 일의 원흉이 바로 그대들 불청객 무리 가운데 있는 것일지도 모르지.",
  ui_story_5053_50531301_136_dialog_content = "예를 들면 머리에 날개가 자란 저 괴물 말이야.",
  ui_story_5053_50531301_137_dialog_content = "그렇게 말하지 마세요! 이분은 괴물이 아니에요. 이분은...",
  ui_story_5053_50531301_138_dialog_content = "하늘에서는 드래곤이 곧 두 번째 공세를 펼칠 것이네.",
  ui_story_5053_50531301_139_dialog_content = "지상에서는 산송장들이 파도처럼 관람석을 포위해 오고 있지.",
  ui_story_5053_50531301_140_dialog_content = "지금 당면한 급선무가 무엇인지 귀하는 이해할 수 있으리라 믿네.",
  ui_story_5053_50531301_141_dialog_content = "...물론 알고 있다.",
  ui_story_5053_50531301_142_dialog_content = "경비병, 가서 라치온과 아우토에게 전하라.\n광장의 병사들에 대한 지휘권은 그들에게 잠시 넘기겠다.",
  ui_story_5053_50531301_143_dialog_content = "관람석을 중심으로 수비대를 배치하여 군중을 대피시켜라.\n드래곤은 내가 견제하겠다.",
  ui_story_5053_50531301_144_dialog_content = "예!",
  ui_story_5053_50531301_145_dialog_content = "(늙은 성주님이 도와주셔서 다행이야. 내가 말을 못 하는 사정을 눈치채신 모양이야.)",
  ui_story_5053_50531301_146_dialog_content = "(겨우 번 시간을 낭비할 순 없어. 빨리 솔라드 저택으로 돌아가야 해!)",
  ui_story_5053_50531301_147_dialog_content = "언니, 저 사람... 왜 내 이름을 부르는 거야?",
  ui_story_5053_50531301_148_dialog_content = "카렌, 절대 가까이 가지 마.",
  ui_story_5053_50531301_149_dialog_content = "미아... 카렌... 다치진... 않았니...?",
  ui_story_5053_50531301_150_dialog_content = "아픈... 곳은... 없니...?",
  ui_story_5053_50531301_151_dialog_content = "아프면... 엄마가... 안아주고... 노래... 불러 줄게...",
  ui_story_5053_50531301_152_dialog_content = "에엣? 저, 전 괜찮아요... 방금 카렌도 살펴봤는데 괜찮았어요.",
  ui_story_5053_50531301_153_dialog_content = "이제 보니 우리와 소통할 수 있는 거였군요... 당신도 어머님의 일부인 거죠?",
  ui_story_5053_50531301_154_dialog_content = "엄마... 그래... 엄마야...",
  ui_story_5053_50531301_155_dialog_content = "그럼 이제 우릴 공격하지 말아 주실 수 있나요? 아버님도 포함해서요.",
  ui_story_5053_50531301_156_dialog_content = "미아... 아버지... 다니엘... 다니엘...!!!",
  ui_story_5053_50531301_157_dialog_content = "어, 어머님은 우리 앞에서 아버님과 싸우는 걸 싫어하시잖아요!",
  ui_story_5053_50531301_158_dialog_content = "맞죠?",
  ui_story_5053_50531301_159_dialog_content = "..................",
  ui_story_5053_50531301_160_dialog_content = "싸우지 않아... 아이들이 놀랄 거야... 싸우지 않을게...",
  ui_story_5053_50531301_161_dialog_content = "미아... 무서워하지 마... 엄마는... 싸우지 않아...",
  ui_story_5053_50531301_162_dialog_content = "네, 고마워요... 어머님.",
  ui_story_5053_50531301_163_dialog_content = "(어머님은 「검은 천사」가 씨앗의 산물이고, 이성이 없는 괴물이라고 했어.)",
  ui_story_5053_50531301_164_dialog_content = "(하지만 이렇게 보면 소통도 할 수 있고, 심지어 약간... 다정하다는 느낌까지 들어.)",
  ui_story_5053_50531301_165_dialog_content = "(하지만 저택에 계신 어머님은 조금 차갑게 느껴져... 대체 왜일까...)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>저기, 미아! 이쪽이야!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName, 무사했구나!\n아버님! 괜찮으세요?",
  ui_story_5053_50531301_168_dialog_content = "쉿, 조용히 해.",
  ui_story_5053_50531301_169_dialog_content = "젊은 성주님이 드래곤을 상대하는 동안 얼른 「검은 천사」를 데리고 가자.",
  ui_story_5053_50531301_170_dialog_content = "「검은 천사」를 데리고...? 어디로 가는데?",
  ui_story_5053_50531301_171_dialog_content = "솔라드 저택, 칼렙 씨랑 쟈키니가 위험해.",
  ui_story_5053_50531301_172_dialog_content = "응? 잠깐만, 조금 혼란스러워서... 대체 뭐가 어떻게...",
  ui_story_5053_50531301_173_dialog_content = "가는 동안 PlayerName에게 설명을 듣기로 했다.\n우선은 함께 가보는 게 좋겠다.",
  ui_story_5053_50531301_174_dialog_content = "아, 알겠어요.",
  ui_story_5053_50531301_175_dialog_content = "다...니엘...",
  ui_story_5053_50531301_176_dialog_content = "PlayerName, 그녀가 날 다시 공격하지 않으리라 확신하나?",
  ui_story_5053_50531301_177_dialog_content = "어, 음... 그럴걸요, 아마도요...",
  ui_story_5053_50531301_178_dialog_content = "네, 어머님은 이미 저랑 약속하셨어요, 그렇죠?",
  ui_story_5053_50531301_179_dialog_content = "응... 약속...했어...",
  ui_story_5053_50531301_180_dialog_content = "...좋다.",
  ui_story_5053_50531301_181_dialog_content = "관람석 뒤쪽으로 가는 게 좋겠군. 저쪽은 구경하는 군중이 없으니,\n아직 병력이 배치되지 않은 틈에 빠져나가도록 하지. 서둘러라.",
  ui_story_5053_50531301_182_dialog_content = "언니, 어디 가?",
  ui_story_5053_50531301_183_dialog_content = "아버님이 그러셨는데 이따가 미즈 로트가 우리 데리러 온대.\n함부로 움직이지 말고 우리 같이 있으라고 그러셨어.",
  ui_story_5053_50531301_184_dialog_content = "카렌, 언니는 할 일이 있어서 계속 같이 있어줄 수가 없어.",
  ui_story_5053_50531301_185_dialog_content = "카렌은 용감한 아이니까, 여기서 혼자 미즈 로트를 기다릴 수 있을까?",
  ui_story_5053_50531301_186_dialog_content = "카렌은 문제없지만, 언니가 걱정돼.",
  ui_story_5053_50531301_187_dialog_content = "카렌은 다 알아. 언니는 자주 혼자서 몰래 운다는 거...",
  ui_story_5053_50531301_188_dialog_content = "그치만 언니, 무서워하지 마. 카렌은 이미 강해졌어.\n카렌이 언니를 지켜줄 수 있어!",
  ui_story_5053_50531301_189_dialog_content = "헤헤, 역시 성숙하고 철든 우리 카렌답네.",
  ui_story_5053_50531301_190_dialog_content = "걱정 마, 언니도 이제 더는 예전처럼 연약하지 않아.",
  ui_story_5053_50531301_191_dialog_content = "그러니까 항상 언니 걱정하지 않아도 돼.",
  ui_story_5053_50531301_192_dialog_content = "전에는 줄곧 카렌보다 반 박자 늦어서, 늘 모두에게 폐를 끼쳤지만...",
  ui_story_5053_50531301_193_dialog_content = "지금부터 난 믿음직한 언니가 돼서 네가 진 짐을 같이 질 수 있게 노력할게.",
  ui_story_5053_50531301_194_dialog_content = "언니...?",
  ui_story_5053_50531301_195_dialog_content = "그러니까 언니를 믿어줘.",
  ui_story_5053_50531301_196_dialog_content = "응, 카렌은 믿어.",
  ui_story_5053_50531301_197_dialog_content = "헤헤, 고마워.",
  ui_story_5053_50531301_198_dialog_content = "<size=30>그럼... 잘 있어, 사랑하는 카렌...</size>",
  ui_story_5053_50531302_1_dialog_content = "...중앙 광장 쪽은 이런 상황입니다.",
  ui_story_5053_50531302_2_dialog_content = "현재 광장으로 통하는 모든 관문은 이미 닫혔습니다.",
  ui_story_5053_50531302_3_dialog_content = "성주 전하의 지휘하에 폭동은 이미 확실하게 통제되고 있으니 안심하십시오.",
  ui_story_5053_50531302_4_dialog_content = "...알겠어, 이제 가 봐도 돼.",
  ui_story_5053_50531302_5_dialog_content = "알겠습니다.",
  ui_story_5053_50531302_6_dialog_content = "참, 쟈키니, 혹시 방문 좀 잠가줄 수 있을까?",
  ui_story_5053_50531302_7_dialog_content = "아, 그렇죠! 문을 잠가야 좀 더 안전할 테니까요. 알겠어요~",
  ui_story_5053_50531302_8_dialog_content = "칼렙, 한 가지 궁금한 게 있어. 왜 날 구하고 싶은 거니?",
  ui_story_5053_50531302_9_dialog_content = "네?",
  ui_story_5053_50531302_10_dialog_content = "음? 누나는 제 친누나잖아요. 누나를 구하는 건 당연한 일 아닌가요?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5053_50531302_12_dialog_content = "부인, 저예요. 모시러 왔어요. 지금 들어가도 괜찮을까요?",
  ui_story_5053_50531302_13_dialog_content = "네네! 괜찮아요! 얼른 들어오세요!",
  ui_story_5053_50531302_14_dialog_content = "쟈키니 씨, 손님으로서의 자각이 조금도 없는 겁니까?\n아직 누나가 말도 꺼내지 않았잖습니까.",
  ui_story_5053_50531302_15_dialog_content = "......",
  ui_story_5053_50531302_16_dialog_content = "그럼 실례하겠습니다...",
  ui_story_5053_50531302_17_dialog_content = "미즈 로트, 무슨 일일까?",
  ui_story_5053_50531302_18_dialog_content = "성주 전하께서는 부인께서 몸이 불편하시니 제게 여기 머물면서\n부인의 안전을 지키라고 특별히 당부하셨습니다.",
  ui_story_5053_50531302_19_dialog_content = "지금 긴급 상황이 발생했으니 저와 함께 안전한 곳으로 피신해 주시지요.",
  ui_story_5053_50531302_20_dialog_content = "그 뒤에 전 광장에 가서 카렌 공주님을 모셔 올 테니 걱정하지 마세요.",
  ui_story_5053_50531302_21_dialog_content = "그렇구나, 수고가 많아.",
  ui_story_5053_50531302_22_dialog_content = "하지만 나와 손님들은 여기 있으면 안전해.\n내 신경은 쓰지 말고 카렌을 데리러 가도 괜찮아.",
  ui_story_5053_50531302_23_dialog_content = "어떻게 그럴 수가 있겠어요.",
  ui_story_5053_50531302_24_dialog_content = "아니면... 제가 여기 있으면 두 젊은 손님들을 살해하기가 불편하실까요?",
  ui_story_5053_50531302_25_dialog_content = "사, 살해?!",
  ui_story_5053_50531302_26_dialog_content = "미즈 로트, 그게 무슨 헛소리입니까! 누나가 왜 그런 짓을...",
  ui_story_5053_50531302_27_dialog_content = "누나...?",
  ui_story_5053_50531302_28_dialog_content = "그래, 내가 어떻게 그런 짓을 할 수 있겠니.",
  ui_story_5053_50531302_29_dialog_content = "무슨 말을 하는지 전혀 모르겠네, 미즈 로트.",
  ui_story_5053_50531302_30_dialog_content = "연기는 이제 그만하셔도 괜찮아요.",
  ui_story_5053_50531302_31_dialog_content = "칼은 당신 다리에 숨겨져 있잖아요, 그렇죠?\n정말 고전적인 암살 방식이네요.",
  ui_story_5053_50531302_32_dialog_content = "무기를 숨기는 기술은 정말 뛰어나지만, 당장이라도 칼자루로 뻗고 싶은\n그 손에서 당신의 의도가 드러나더군요.",
  ui_story_5053_50531302_33_dialog_content = "......",
  ui_story_5053_50531302_34_dialog_content = "당신은 뛰어난 암살자로군요.",
  ui_story_5053_50531302_35_dialog_content = "선생님을 무척이나 닮았지만, 사실은 진짜 같은 가짜일 뿐이죠.",
  ui_story_5053_50531302_36_dialog_content = "가짜? 하지만 누나는... 누나의 목소리와 모습을 제가 잘못 볼 리가 없습니다...!",
  ui_story_5053_50531302_37_dialog_content = "맞아요! 게다가 「영원한 기억의 수정」도 부인이 진짜 살아있는 사람이라고 했어요!",
  ui_story_5053_50531302_38_dialog_content = "설마 다른 산 사람이 조슈아 부인으로 위장했다는 건가요?",
  ui_story_5053_50531302_39_dialog_content = "두 분이 그 암살자와 어떤 관계인지는 모르겠지만,\n당신들의 안전을 위해서 지금은 그 사람에게 접근하지 않는 게 좋을 거예요.",
  ui_story_5053_50531302_40_dialog_content = "아마 당신은 「그 조직」의 잔당일지도 모르겠군요.\n그들이 키워낸 또 다른 암살자겠죠.",
  ui_story_5053_50531302_41_dialog_content = "그 모습은 과거의 선생님과 너무나도 비슷하니까요.",
  ui_story_5053_50531302_42_dialog_content = "하지만 그렇기에 당신은 지금의 그분을 흉내 낼 수 없어요.\n아내이자 어머니, 누나로서의 조슈아 부인을 말이죠.",
  ui_story_5053_50531302_43_dialog_content = "제 말이 틀렸나요?",
  ui_story_5053_50531302_44_dialog_content = "............",
  ui_story_5053_50531302_45_dialog_content = "조, 조슈아 부인 손에 칼이 있어요! 대체 언제 어디서 저런 걸 꺼내 든 거죠...?",
  ui_story_5053_50531302_46_dialog_content = "으아아, 그런 거 따질 때가 아니죠! 수정구슬아!",
  ui_story_5053_50531302_47_dialog_content = "말도 안 돼... 누나가 맞는데... 아무리 봐도 누나라고...",
  ui_story_5053_50531302_48_dialog_content = "칼렙 씨! 거기서 멍때리고 있지 말고 싸우기 싫으면 비켜요!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>아아아악──!</size>",
  ui_story_5053_50531302_50_dialog_content = "네, 네가 어떻게──?!",
  ui_story_5053_50531302_51_dialog_content = "앗! 「검은 천사」예요!",
  ui_story_5053_50531302_52_dialog_content = "「검은 천사」...?",
  ui_story_5053_50531302_53_dialog_content = "떨어져... 칼렙...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>칼렙...에게서... 떨어져...!</size>",
  ui_story_5053_50531302_55_dialog_content = "왜 네가 여기 있는 거야?!",
  ui_story_5053_50531302_56_dialog_content = "다가오지 마! 이 역겹고 더러운 괴물아!",
  ui_story_5053_50531302_57_dialog_content = "거기 서!",
  ui_story_5053_50531302_58_dialog_content = "조슈아 부인은 우릴 죽이려고 하고... 「검은 천사」는 조슈아 부인을 쫓아내고...",
  ui_story_5053_50531302_59_dialog_content = "이, 이게 다 무슨 일이냐구요! 누가 설명 좀 해 줘요!",
  ui_story_5053_50531302_60_dialog_content = "머, 멈춰! 히포카, 그만...!",
  ui_story_5053_50531302_61_dialog_content = "으아앗?! 왜 또 창문에서 말 머리 거미가 튀어나오는 거죠?!",
  ui_story_5053_50531302_62_dialog_content = "...PlayerName 씨? 미아 씨! 성주님!",
  ui_story_5053_50531302_63_dialog_content = "잘했다, 미아. 루미나 소환물을 다루는 데 소질이 있는 모양이로구나.",
  ui_story_5053_50531302_64_dialog_content = "하, 하아... 히포카를 이렇게 쓸 수도 있다는 건 처음 알았어요...",
  ui_story_5053_50531302_65_dialog_content = "우웁... 거미 말을 타고 건물에서 이리저리 뛰었더니... 토할 것 같아요...",
  ui_story_5053_50531302_66_dialog_content = "당신들 대체 뭐가 어떻게 된 겁니까...",
  ui_story_5053_50531302_67_dialog_content = "칼렙 씨랑 쟈키니는... 다행히 괜찮아 보이네요...",
  ui_story_5053_50531302_68_dialog_content = "안 늦어서... 다행이에요... 우웁...!",
  ui_story_5053_50531401_1_dialog_content = "그러니까... 우린 지금까지 계속 저 「하얀 악마」에게 속아왔던 거군요.",
  ui_story_5053_50531401_2_dialog_content = "「검은 천사」와 「하얀 악마」는 모두 조슈아 부인의 일부였지만,\n둘은 서로를 받아들일 수 없었고...",
  ui_story_5053_50531401_3_dialog_content = "그래서 우릴 죽이고 루미나를 흡수해서 자유를 얻으려고 한다는 거네요...",
  ui_story_5053_50531401_4_dialog_content = "조금 상상하기 힘든 일이지만... 이해할 수 있어.",
  ui_story_5053_50531401_5_dialog_content = "머리가 깨질 듯한 고통, 또 다른 자신에 대한 두려움...",
  ui_story_5053_50531401_6_dialog_content = "하지만 나랑 바바 야가가 그랬던 것처럼, 두 인격은 모두 「나」의 일부야.",
  ui_story_5053_50531401_7_dialog_content = "우린 서로를 받아들일 수 있었어. 그러니까 어머님도 분명히...",
  ui_story_5053_50531401_8_dialog_content = "PlayerName 씨는 우리가 「하얀 악마」를 설득할 기회가 있을 것 같나요?",
  ui_story_5053_50531401_9_dialog_content = "휴... 그건 아마 조슈아 부인 본인밖에 모르지 않을까.",
  ui_story_5053_50531401_10_dialog_content = "내가 지금 아는 거라곤 「영원한 기억의 수정」 속 루미나가 곧 바닥난다는 것뿐이야.",
  ui_story_5053_50531401_11_dialog_content = "지금 이건 우리한테 주어진 마지막 기회야. 이제 다른 생각을 할 겨를이 없어.",
  ui_story_5053_50531401_12_dialog_content = "죄송합니다. 또 다른 부인을 놓치고 말았습니다.",
  ui_story_5053_50531401_13_dialog_content = "방금 경비병이 소식을 전했습니다.\n광장 쪽은 안정적인 방어 단계에 접어들었습니다.",
  ui_story_5053_50531401_14_dialog_content = "다만 그 지치지 않는 드래곤의 공격에 병사들이 얼마나 더\n버틸 수 있을지 모르겠습니다.",
  ui_story_5053_50531401_15_dialog_content = "수고했네, 미즈 로트.\n앞으로의 일은 우리에게 맡기고, 그대는 가서 쉬어도 좋네.",
  ui_story_5053_50531401_16_dialog_content = "어떻게 그럴 수가 있겠습니까.",
  ui_story_5053_50531401_17_dialog_content = "제 임무는 백야성과 솔라드 일가를 지키는 것입니다.",
  ui_story_5053_50531401_18_dialog_content = "비록 제가 허구의 세상 속 한 점의 환영에 불과할지라도,\n제가 여전히 「미즈 로트」인 이상, 그 점은 변하지 않습니다.",
  ui_story_5053_50531401_19_dialog_content = "자신이 환영이라는 사실조차 곧바로 받아들일 수 있다니,\n그대의 태연함은 실로 존경스럽군.",
  ui_story_5053_50531401_20_dialog_content = "후훗, 솔직히 말씀드리자면 그 사실을 알고 나니 전 오히려 더 마음이 놓였습니다.",
  ui_story_5053_50531401_21_dialog_content = "아무래도 미래가 없는 환영은 시시각각 미래를 걱정하는 사람보다\n훨씬 더 홀가분한 모양이네요.",
  ui_story_5053_50531401_22_dialog_content = "저보다는 이제 막 진실을 알게 된 칼렙 경이 훨씬 더 괴로워 보이는걸요.",
  ui_story_5053_50531401_23_dialog_content = "조슈아는... 그 누구도 자신의 과거를 알기를 원하지 않았다.",
  ui_story_5053_50531401_24_dialog_content = "하나는 그녀의 과거가 수많은 비난을 불러일으킬 수 있기 때문이고.",
  ui_story_5053_50531401_25_dialog_content = "다른 하나는 어쩌면 동생에게 진실을 밝힐 용기가 없어서였을지도 모르지.",
  ui_story_5053_50531401_26_dialog_content = "몇 년 이래 그녀는 무척 밝아졌지만, 그 대신 마음속에는 나약함이 생겨나고 말았다.",
  ui_story_5053_50531401_27_dialog_content = "부인의 감정이 전보다 더 풍부해졌으니 좋은 일이라는 말씀이시군요.",
  ui_story_5053_50531401_28_dialog_content = "「하지만 때로는 진실하고 용기 있는 소통만이 문제를 해결할 수 있는 법이랍니다.」",
  ui_story_5053_50531401_29_dialog_content = "부인이 현실 세계에서 깨어나신다면, 부디 성주님의 그 생각들을\n부인께 분명하게 전하셨으면 좋겠습니다.",
  ui_story_5053_50531401_30_dialog_content = "그렇지 않으면 깨어나신 부인께서 화가 나셔서 다시 기절하실 수도 있으니까요.",
  ui_story_5053_50531401_31_dialog_content = "...유념하도록 하지.",
  ui_story_5053_50531401_32_dialog_content = "성주님, 미즈 로트랑 이야기는 다 나누셨나요?\n괜찮으시다면 성주님이랑 앞으로의 대책을 상의하고 싶어요.",
  ui_story_5053_50531401_33_dialog_content = "좋다.",
  ui_story_5053_50531401_34_dialog_content = "...칼렙 씨는요? 좀 나아졌나요?",
  ui_story_5053_50531401_35_dialog_content = "지금은 혼자 두는 게 좋을 것 같군.",
  ui_story_5053_50531401_36_dialog_content = "......",
  ui_story_5053_50531401_37_dialog_content = "누나... 누나 맞죠...?",
  ui_story_5053_50531401_38_dialog_content = "──!",
  ui_story_5053_50531401_39_dialog_content = "왜 피하는 거죠?",
  ui_story_5053_50531401_40_dialog_content = "설마 누나는... 정말 또 다른 당신이 했던 말처럼...\n한 번도 절 가족으로 생각해 본 적이 없나요?",
  ui_story_5053_50531401_41_dialog_content = "...아니야...",
  ui_story_5053_50531401_42_dialog_content = "무서워... 난... 무서워...",
  ui_story_5053_50531401_43_dialog_content = "무섭다고요?",
  ui_story_5053_50531401_44_dialog_content = "칼렙은... 누나를 좋아해... 누나를 믿어...",
  ui_story_5053_50531401_45_dialog_content = "가슴이 답답해... 머리가 아파... 부담감으로... 숨을 쉴 수가 없어...",
  ui_story_5053_50531401_46_dialog_content = "아버지는... 증오를 내려놓고... 우릴 지키려고... 죽었어... 모두 내 탓이야...",
  ui_story_5053_50531401_47_dialog_content = "그게 무슨 뜻이죠...?",
  ui_story_5053_50531401_48_dialog_content = "또 다른 누나는 아버지가 복수의 불씨를 지키려고 자살을 선택했다고 했어요.",
  ui_story_5053_50531401_49_dialog_content = "하지만 누나는 아버지가 증오를 내려놨다고 하고...\n대체 뭐가 진실인지 이제 도저히 모르겠어요.",
  ui_story_5053_50531401_50_dialog_content = "당신은 솔라드의 아버지를 암살하기 위해 줄곧 제 누나를 연기해 왔어요.",
  ui_story_5053_50531401_51_dialog_content = "하지만 마치 친누나, 아니, 친어머니처럼 절 그 누구보다도 세심하게 보살펴 주셨죠.",
  ui_story_5053_50531401_52_dialog_content = "그리고 전 그렇게나 누나 곁에 붙어 있는 걸 좋아해서,\n누나는 많은 부담을 받았을 거라 생각해요.",
  ui_story_5053_50531401_53_dialog_content = "...됐어요. 누나, 제겐 언제나 당신의 행복이 제일 중요했어요.",
  ui_story_5053_50531401_54_dialog_content = "만약 누나가 정말로 절 좋아하지 않는다면, 여기서 나가고 나서 전 다시는\n누나에게 매달리지 않을 거예요. 가서 자유롭게 누나가 살고 싶은 삶을 살아요.",
  ui_story_5053_50531401_55_dialog_content = "아니... 아니야... 날... 떠나지 마...",
  ui_story_5053_50531401_56_dialog_content = "난... 추한... 마음을... 속였어... 난... 무서웠어...",
  ui_story_5053_50531401_57_dialog_content = "네가... 날... 싫어할까... 무서웠어...",
  ui_story_5053_50531401_58_dialog_content = "......",
  ui_story_5053_50531401_59_dialog_content = "그럴 리가 없잖아요.",
  ui_story_5053_50531401_60_dialog_content = "누나는 이 세상에서 가장 아름답고 상냥한 사람인걸요.",
  ui_story_5053_50531401_61_dialog_content = "제가 어떻게 누나를 싫어할 수 있겠어요.",
  ui_story_5053_50531401_62_dialog_content = "그럼 지금까지 논의한 내용을 제가 요약해 볼게요.",
  ui_story_5053_50531401_63_dialog_content = "지금까지 우린 「하얀 악마」의 모든 계획을 막았어요.",
  ui_story_5053_50531401_64_dialog_content = "막다른 골목에 몰린 「하얀 악마」는 아마 자신이 제어하는 무리와 드래곤을\n이용해서 최후의 공격을 감행할 거예요.",
  ui_story_5053_50531401_65_dialog_content = "다행히 우린 지금 모두 무사하고, 젊은 성주님도 백야성의 전력을 동원해서\n저들의 공세를 막아냈어요.",
  ui_story_5053_50531401_66_dialog_content = "하지만 「영원한 기억의 수정」에 남은 루미나는 저들이 드래곤에 맞서기엔\n충분하지 않을 거예요.",
  ui_story_5053_50531401_67_dialog_content = "게다가 하루라는 시간도 이제 몇 시간밖에 안 남았어요.",
  ui_story_5053_50531401_68_dialog_content = "지금 우린 먼저 「하얀 악마」의 체스말들을 단시간 내에 철저하게 해결할 수 있는\n간단하고 효과적인 방법이 필요해요.",
  ui_story_5053_50531401_69_dialog_content = "그래야 「하얀 악마」를 생포할 수 있으니까요.",
  ui_story_5053_50531401_70_dialog_content = "쟈키니가 가지고 있는 그 「영원한 기억의 수정」에 뭔가 다른 기능이 있을까?\n예를 들면 「하얀 악마」처럼 환영을 조종한다든지...",
  ui_story_5053_50531401_71_dialog_content = "음~ 안 돼요! 우선 지금 「영원한 기억의 수정」은 더 많은 기능을\n지원할 만한 루미나가 없어요.",
  ui_story_5053_50531401_72_dialog_content = "게다가 이 「영원한 기억의 수정」은 결국 비상 탈출 장치일 뿐이거든요.",
  ui_story_5053_50531401_73_dialog_content = "사실 따지고 보면 이렇게 자꾸 막 쓰면 안 되는 건데...\n우린 이미 이걸 가지고 정상 범위에서 벗어난 일들을 너무 많이 했어요.",
  ui_story_5053_50531401_74_dialog_content = "정 안 되면... 제가 주문을 다시 만들어 볼게요...!",
  ui_story_5053_50531401_75_dialog_content = "되었다, 쟈키니. 지금은 상황이 급박하니, 다른 문제가 생기게 할 순 없다.",
  ui_story_5053_50531401_76_dialog_content = "헤, 헤헤... 알겠어요.",
  ui_story_5053_50531401_77_dialog_content = "그렇게 골치 아프게 생각할 필요 없습니다.",
  ui_story_5053_50531401_78_dialog_content = "저들이 서로 싸우게 만들면 됩니다.",
  ui_story_5053_50531401_79_dialog_content = "헤에, 칼렙 씨, 다 울었어요?",
  ui_story_5053_50531401_80_dialog_content = "당신이나 울겠죠! 제가 세 살짜리 아이로 보입니까?!",
  ui_story_5053_50531401_81_dialog_content = "자기들끼리 싸운다고요?\n다들 「하얀 악마」한테 조종당하고 있는데, 어떻게 그렇게 만들죠?",
  ui_story_5053_50531401_82_dialog_content = "무척 간단합니다.",
  ui_story_5053_50531401_83_dialog_content = "저들이 지닌 루미나의 균형을 깨트릴 수만 있다면,\n저들은 고통 때문에 자신의 몸을 통제할 수 있는 능력을 잃을 겁니다.",
  ui_story_5053_50531401_84_dialog_content = "루미나의 균형? 그런 말은 처음 들어봐요...",
  ui_story_5053_50531401_85_dialog_content = "훗, 평범한 오로리안들은 이해할 수 없을 겁니다.\n하지만 그쪽의 아이테르는 제 말이 무슨 뜻인지 알겠죠.",
  ui_story_5053_50531401_86_dialog_content = "저요? 음... 확실히 전 루미나의 미묘한 차이를 알아볼 수 있긴 해요.",
  ui_story_5053_50531401_87_dialog_content = "그건 또 무슨 이도 저도 아닌 표현입니까... 정말 실망스럽군요.",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName 씨, 전부터 느낀 건데, 칼렙 씨 왠지 우리한테 갈수록\n말을 막 하는 것 같지 않아요? 설마 저 사람 원래 성격이 엄청 나쁜 걸까요?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>하하하하... 난 잘 모르겠는데...</size>",
  ui_story_5053_50531401_90_dialog_content = "거기! 수업 시간에 수군대지 마세요!",
  ui_story_5053_50531401_91_dialog_content = "거두절미하고 본론으로 들어가라, 칼렙. 그대의 계획을 말해라.",
  ui_story_5053_50531401_92_dialog_content = "저는 투약 대상의 루미나 균형을 어지럽히는 약을 만들 수 있습니다.\n여러분은 그걸 「루미나에 대한 독약」의 일종으로 이해해도 좋습니다.",
  ui_story_5053_50531401_93_dialog_content = "「영원한 기억의 수정」의 사람과 사물은 모두 루미나와 거울 호수의 물이\n작용해 만들어진 환상입니다.",
  ui_story_5053_50531401_94_dialog_content = "그러니 제 약도 저들에게 똑같이 효과가 있을 겁니다.",
  ui_story_5053_50531401_95_dialog_content = "지금 가진 재료의 양에는 한계가 있으니, 저는 이 약을 저 드래곤에게 쓸 생각입니다.",
  ui_story_5053_50531401_96_dialog_content = "놈이 고통으로 몸부림치면서 광장에서 소란을 피운다면,\n나머지 걸어 다니는 시체들은 놈에게 그저 개미 떼에 불과할 겁니다.",
  ui_story_5053_50531401_97_dialog_content = "그렇게 되면 또 다른 누나의 체스말들도 무용지물이 되겠죠.",
  ui_story_5053_50531401_98_dialog_content = "으음~ 그러니까 드래곤한테 설사약을 먹이고 떼굴떼굴 구르게 만들자는 거네요!",
  ui_story_5053_50531401_99_dialog_content = "...그렇다고 치죠.",
  ui_story_5053_50531401_100_dialog_content = "그 계획은 확실히 그대의 방식이로군.\n그대는 어릴 적부터 그런 간단하면서도 음험한 수법을 즐겨 사용했지.",
  ui_story_5053_50531401_101_dialog_content = "어라, 성주님께서 아직도 그 일을 기억하고 계셨을 줄은 몰랐습니다만.\n그 홍차 한 잔이 그토록 인상이 깊으셨습니까?",
  ui_story_5053_50531401_102_dialog_content = "(뭐...? 그럼 칼렙 씨가 전에 성주님한테 설사약을 먹였단 소리야?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>역시 제 생각이 맞았어요! 칼렙 씨는 성질이 더러운 사람이었네요!</size>",
  ui_story_5053_50531401_104_dialog_content = "풉, 푸훕...",
  ui_story_5053_50531401_105_dialog_content = "미아, 웃지 마세요.",
  ui_story_5053_50531401_106_dialog_content = "죄, 죄송해요... 못 참고 그만... 아, 아니, 그런 뜻은 아니었어요...",
  ui_story_5053_50531401_107_dialog_content = "약은 한 병뿐이니, 기회도 한 번뿐입니다.\n전 드래곤을 견제해 줄 강한 전사가 필요합니다. 당신이 절 도와주세요.",
  ui_story_5053_50531401_108_dialog_content = "엣? 막강한 전사... 제가요?",
  ui_story_5053_50531401_109_dialog_content = "네, 얼른 따라오세요.",
  ui_story_5053_50531401_110_dialog_content = "앗! 잠깐만요...",
  ui_story_5053_50531401_111_dialog_content = "칼렙 씨가 또 제멋대로 도망갔어요! 어떡하죠? 저희도 따라갈까요?",
  ui_story_5053_50531401_112_dialog_content = "드래곤 쪽은 칼렙에게 맡겨라. 나는 그를 믿고, 미아도 믿는다.",
  ui_story_5053_50531401_113_dialog_content = "성주님...",
  ui_story_5053_50531401_114_dialog_content = "그대의 말에 따르면, 나는 매번 「하얀 악마」의 음모에서 끝까지 살아남았다.\n허나 그 모든 결말을 나는 바꾸지 못했다.",
  ui_story_5053_50531401_115_dialog_content = "오히려 항상 그대 같은 젊은이들의 활약이 사건에 새로운 전환점을 가져다주었지.",
  ui_story_5053_50531401_116_dialog_content = "나는 지금까지 줄곧 내가 직접 모든 것을 지켜야 한다고 생각해 왔다...\n허나 어쩌면 이제는 그 오만함을 내려놓을 때가 되었는지도 모르겠군.",
  ui_story_5053_50531401_117_dialog_content = "그럼 저흰 계속 여기서 기다리나요?",
  ui_story_5053_50531401_118_dialog_content = "그렇다, 우리는 이곳에서 힘을 비축한다.",
  ui_story_5053_50531401_119_dialog_content = "내가 아는 그녀라면, 모든 패가 바닥나는 순간 반드시 스스로 나타나\n우리와 필사적으로 싸울 것이다.",
  ui_story_5053_50531401_120_dialog_content = "그녀는 그토록 완강한 사람이다.",
  ui_story_5053_50531401_121_dialog_content = "게다가...",
  ui_story_5053_50531401_122_dialog_content = "............",
  ui_story_5053_50531401_123_dialog_content = "나는 또다시 그녀를 설득해야만 한다.",
  ui_story_5053_50531401_125_dialog_content = "다시 이곳으로 돌아오게 되었군. 저녁, 식탁, 그대와 나.",
  ui_story_5053_50531401_126_dialog_content = "......",
  ui_story_5053_50531401_127_dialog_content = "종전에 나는 젊은 모습으로 분장하여 당시 불쾌하게 헤어졌던 결말을 바꾸고 싶었다.",
  ui_story_5053_50531401_128_dialog_content = "내 비록 말로는 그대가 더는 상처를 받지 않길 바란다고 하였으나,\n이 허상 속에서 내가 하는 그 무엇이 자기만족을 위함이 아니라 할 수 있겠나.",
  ui_story_5053_50531401_129_dialog_content = "공교롭게도 그대는 애초부터 내 눈앞에 있었고, 한눈에 나의 비열함을 알아보았지.\n그대가 그토록 화를 내는 것도 당연한 일이었다.",
  ui_story_5053_50531401_130_dialog_content = "...다...니...엘...",
  ui_story_5053_50531401_131_dialog_content = "그래, 이 모든 것은 나의 잘못이다.\n내 목이라면 언제든지 가져가도 좋다. 허나 그게 지금은 아니다.",
  ui_story_5053_50531401_132_dialog_content = "저 아이들은 죄가 없다. 저들은 이곳을 떠나야만 한다.",
  ui_story_5053_50531401_133_dialog_content = "그러니 우릴 도와 또 다른 그대를 붙잡고, 우리와 함께 이 세상을 떠나줄 수 있겠나.",
  ui_story_5053_50531401_134_dialog_content = "아이들의... 미래... 미래를... 지켜요...",
  ui_story_5053_50531401_135_dialog_content = "동의한 것 같군. 고맙다, 조슈아...\n그리고 다시 한번... 나를 믿어주어 고맙다.",
  ui_story_5053_50531401_136_dialog_content = "......",
  ui_story_5053_50531401_137_dialog_content = "칼렙이 간 지도 얼마 되지 않았으니, 우리는 조금 더 쉴 수 있겠군.",
  ui_story_5053_50531401_138_dialog_content = "조슈아, 그대가 아직 그 노래를 기억하고 있다고 들었다.",
  ui_story_5053_50531401_139_dialog_content = "다운타운의... 노래... 행복한... 삶의... 노래...",
  ui_story_5053_50531401_140_dialog_content = "그렇지, 바로 그 노래 말이야.\n사실 12년 전, 그대에게 줄 선물을 하나 준비했었다.",
  ui_story_5053_50531401_141_dialog_content = "허나 애석하게도 일순간의 충동으로 그대에게 건네줄 기회를 놓치고 말았지.\n내 기억으로는... 음, 여기 있군.",
  ui_story_5053_50531401_142_dialog_content = "레코드...판?",
  ui_story_5053_50531401_143_dialog_content = "그래, 레코드판이다. 사람을 시켜 무도곡의 형식으로 편곡하도록 했는데, 궁금한가?\n마침 여기 축음기가 있었지.",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>~♪</color>",
  ui_story_5053_50531401_145_dialog_content = "......!",
  ui_story_5053_50531401_146_dialog_content = "마음에 들었나 보군. 다행이야.",
  ui_story_5053_50531401_147_dialog_content = "무도곡인데 그저 앉아서 감상하기에는 다소 지루하지 않겠나.",
  ui_story_5053_50531401_148_dialog_content = "그렇다면, 아름다운 여사여, 나와 함께 춤 한 곡을 추지 않겠는가.",
  ui_story_5053_50531401_149_dialog_content = "......",
  ui_story_5053_50531401_150_dialog_content = "......",
  ui_story_5053_50531401_151_dialog_content = "다...니엘...",
  ui_story_5053_50531401_152_dialog_content = "왜 그러지?",
  ui_story_5053_50531401_153_dialog_content = "다들... 잘... 지내나요...?",
  ui_story_5053_50531401_154_dialog_content = "...잘 지내고 있다.",
  ui_story_5053_50531401_155_dialog_content = "카렌은 이미 백야성 호위대의 대장이 되었다.\n뛰어난 부하들도 있고, 친구도 많이 사귀었지.",
  ui_story_5053_50531401_156_dialog_content = "미아는 여전히 이스타반이 돌보고 있다.\n병세는 이미 많이 호전되었고, 한낮의 거리에서 놀 수도 있다더군.",
  ui_story_5053_50531401_157_dialog_content = "칼렙... 그자는 여명 아카데미에서 일을 잘하고 있다고 들었다.\n그리고 그대를 무척 그리워하고 있다. 그 마음은 아마 우리 중 가장 클지도 모르지.",
  ui_story_5053_50531401_158_dialog_content = "당신...은요...?",
  ui_story_5053_50531401_159_dialog_content = "...나 말인가?",
  ui_story_5053_50531401_160_dialog_content = "지금은 더는 내 시대가 아니게 되었다.",
  ui_story_5053_50531401_161_dialog_content = "과거의 나는 무능했고, 많은 실수를 저질렀지.\n이제 아이들은 내 어깨를 밟고, 더 높은 곳을 향해 올라가고 있다.",
  ui_story_5053_50531401_162_dialog_content = "내가 할 수 있는 일은 그저 이 자리에 서서 저들을 받들고,\n저들이 더 먼 미래로 나아갈 수 있게 하는 것뿐이다.",
  ui_story_5053_50531401_163_dialog_content = "그대와 나의 이상 속 세계가 현실이 되는 그날까지 말이야.",
  ui_story_5053_50531401_164_dialog_content = "그대가 돌아오면, 나는 그대가 칼렙의 집에서 계속 요양할 수 있도록 준비하겠다.",
  ui_story_5053_50531401_165_dialog_content = "그리고 베로니카를 데려와 그대와 함께 지내도록 하고,\n이 좋은 소식을 카렌에게 전하면, 한 가족이 다시 함께할 수 있게 되겠지.",
  ui_story_5053_50531401_166_dialog_content = "다만... 하하, 나는 이미 늙어서 그대와 어울리지 않을지도 모르겠군.\n그대만 괜찮다면, 이따금 그대를 보러 가도 되겠나.",
  ui_story_5053_50531401_167_dialog_content = "집...",
  ui_story_5053_50531401_168_dialog_content = "조슈아?",
  ui_story_5053_50531401_169_dialog_content = "집에... 가고... 싶어요...",
  ui_story_5053_50531401_170_dialog_content = "그래, 함께 집으로 돌아가자.",
  ui_story_5053_50531401_171_dialog_content = "...조슈아, 그대는 후회하는가.",
  ui_story_5053_50531401_172_dialog_content = "만약 그대가 계속 이처럼 고통과 분노를 느껴 왔다면...\n그대는... 처음에 날 선택한 것을 후회하지는 않는가.",
  ui_story_5053_50531401_173_dialog_content = "행복... 사랑... 모두 당신이... 가르쳐 준... 거예요...",
  ui_story_5053_50531401_174_dialog_content = "미움은... 사랑의 이면이에요...",
  ui_story_5053_50531401_175_dialog_content = "미움은... 고통스러워요... 하지만... 미움은... 깊은 사랑 때문이에요...\n그래서... 난 후회하지...않아요...",
  ui_story_5053_50531401_176_dialog_content = "............",
  ui_story_5053_50531401_177_dialog_content = "그러한가.",
  ui_story_5053_50531401_178_dialog_content = "그랬던 것인가...",
  ui_story_5053_50531401_179_dialog_content = "5구역 설치 완료, 6구역 설치 완료...",
  ui_story_5053_50531401_180_dialog_content = "자, 드래곤을 유인할 폭탄은 모두 설치했습니다. 이제 기폭장치만 남았습니다.",
  ui_story_5053_50531401_181_dialog_content = "칼렙 경, 폭탄 설치는 잘 되어가시나요? 제 도움이 필요하신가요?",
  ui_story_5053_50531401_182_dialog_content = "아니요, 이미 다 했습니다.",
  ui_story_5053_50531401_183_dialog_content = "이렇게 짧은 시간에 일을 끝내시다니, 정말 당신답네요.",
  ui_story_5053_50531401_184_dialog_content = "친척끼리 빈말은 됐습니다. 그리고 정말 칭찬받아 마땅한 사람은 당신입니다.",
  ui_story_5053_50531401_185_dialog_content = "당신이 없었다면 경비병들을 뚫고 지나오지 못했을 겁니다.",
  ui_story_5053_50531401_186_dialog_content = "제가 해야 할 일인걸요. 하지만 두 분 정말 제 도움이 필요 없으신가요?",
  ui_story_5053_50531401_187_dialog_content = "적을 막는 위험한 임무라면 수정 속 환영인 제가 수행하는 게 더 적합한걸요.",
  ui_story_5053_50531401_188_dialog_content = "그렇게 말하지 마세요, 미즈 로트...",
  ui_story_5053_50531401_189_dialog_content = "그리고 그것보다 더 중요한 일을 부탁할 게 있거든요.",
  ui_story_5053_50531401_190_dialog_content = "얼마든지 도움을 드리겠습니다, 공주 전하.",
  ui_story_5053_50531401_191_dialog_content = "저 대신 가서 카렌이랑 함께 있어주실 수 있을까요?\n그 앤 지금 혼자니까 분명히 무척 불안할 거예요.",
  ui_story_5053_50531401_192_dialog_content = "얼마든지요. 다만 여쭤보고 싶은 게 있어요...",
  ui_story_5053_50531401_193_dialog_content = "저흰 단지 환영일 뿐인데, 왜 전하께서는 저희에게 그렇게 마음을 쓰시는 건가요?",
  ui_story_5053_50531401_194_dialog_content = "그렇지 않아요... 여러분은 제 소중한 사람들과 같은 얼굴, 같은 인격,\n그리고 같은 기억을 가지고 있어요.",
  ui_story_5053_50531401_195_dialog_content = "비록 생명이 존재하는 형태는 다르지만, 전 여러분에게 같은 감정을 가지고 있어요.",
  ui_story_5053_50531401_196_dialog_content = "전 우리 사이의 감정이 「진실」과 「허구」의 차이가 없다고 생각해요.",
  ui_story_5053_50531401_197_dialog_content = "게다가 전 어떤 건 희생해도 되고, 어떤 건 중요하지 않다고 생각하는 게 싫어요...",
  ui_story_5053_50531401_198_dialog_content = "그런 생각만 하면 제 초심을 잃어버릴까 무서워요.",
  ui_story_5053_50531401_199_dialog_content = "전부터 미아 공주님은 조슈아 부인을 무척 닮았다고 생각했는데,\n지금은 더 닮게 변하셨네요.",
  ui_story_5053_50531401_200_dialog_content = "그, 그래요...?",
  ui_story_5053_50531401_201_dialog_content = "모든 준비가 끝났습니다. 이제 갑시다, 미아!",
  ui_story_5053_50531401_202_dialog_content = "네, 갈게요!\n그럼 카렌을 부탁해요, 미즈 로트!",
  ui_story_5053_50531401_203_dialog_content = "아무래도 제 기도가 없이도, 빛은 이미 솔라드 가문의 미래를 비추고 있는 모양이네요.",
  ui_story_5053_50531401_204_dialog_content = "스읍... 후우...",
  ui_story_5053_50531401_205_dialog_content = "제가 들고 있는 버튼을 누르면 폭탄이 하나씩 터지고,\n20초 안에 드래곤이 우리 앞에 나타날 겁니다.",
  ui_story_5053_50531401_206_dialog_content = "미아, 준비됐습니까?",
  ui_story_5053_50531401_207_dialog_content = "아, 아마도요...",
  ui_story_5053_50531401_208_dialog_content = "휴... 어째서 이런 중요한 상황에 와서도 당신은 여전히 자신이 없는 겁니까.",
  ui_story_5053_50531401_209_dialog_content = "정신 바짝 차리세요!",
  ui_story_5053_50531401_210_dialog_content = "죄송해요...\n저기, 외삼촌....",
  ui_story_5053_50531401_211_dialog_content = "할 말 있으면 짧게 하세요.",
  ui_story_5053_50531401_212_dialog_content = "왜 이 계획에 절 선택하신 건가요...?",
  ui_story_5053_50531401_213_dialog_content = "강한 전사가 필요하다면... 아버님이나 미즈 로트가 저보다 더 적합하지 않나요?",
  ui_story_5053_50531401_214_dialog_content = "음? 왜 그렇게 생각하는 겁니까?",
  ui_story_5053_50531401_215_dialog_content = "그간의 여정을 겪으면서 당신의 실력은 이미 파악했습니다.\n게다가 당신에겐 루미나 소환물이 있다고 들었습니다.",
  ui_story_5053_50531401_216_dialog_content = "그건 당신이 기동력에 있어 우위를 점할 수 있게 할 겁니다.\n따라서 당신보다 이 계획에 적합한 사람은 없습니다.",
  ui_story_5053_50531401_217_dialog_content = "소, 소환물이요?!",
  ui_story_5053_50531401_218_dialog_content = "저는 히포카를 별로 불러내 본 적이 없어서 잘 다룰 수 있을 거란 보장은 없는걸요...",
  ui_story_5053_50531401_219_dialog_content = "별로 불러내 본 적이 없다고요?\n그토록 드문 재능이 있는데 왜 활용하질 않는 겁니까?",
  ui_story_5053_50531401_220_dialog_content = "그게... 히포카는 무섭게 생겨서... 다들 불길한 상징이라고 두려워했거든요.",
  ui_story_5053_50531401_221_dialog_content = "하지만 이제 전 그렇게 생각하지 않아요!\n전 더는 남들의 말 때문에 멋대로 자신을 의심하지 않을 거니까요.",
  ui_story_5053_50531401_222_dialog_content = "하지만... 전 정말 히포카와 함께 싸워본 적이 별로 없어서, 조금 자신이 없어요...",
  ui_story_5053_50531401_223_dialog_content = "만약 우리가 실패한다면, 어쩌면 모두의 목숨이...",
  ui_story_5053_50531401_224_dialog_content = "흥, 그런 거였군요. 솔라드 짓입니까?",
  ui_story_5053_50531401_225_dialog_content = "......",
  ui_story_5053_50531401_226_dialog_content = "고작 그 귀족들의 허튼 말 때문에 당신에게 소환물을 쓰지 못하게 하다니.",
  ui_story_5053_50531401_227_dialog_content = "당신 아버지란 사람은 그렇게만 하면 소환물이 모든 오명을 뒤집어쓰고,\n당신은 비난에서 벗어날 수 있다고 생각한 겁니까?",
  ui_story_5053_50531401_228_dialog_content = "네...? 아버님께선 절 지키려고 그러신 거란 말인가요...?",
  ui_story_5053_50531401_229_dialog_content = "<size=45>정말 재미없기 짝이 없군요!</size>",
  ui_story_5053_50531401_230_dialog_content = "네...?!",
  ui_story_5053_50531401_231_dialog_content = "잘 들어요, 미아. 그 귀족들이 당신을 헐뜯는 건 당신을 질투하기 때문이에요.\n당신이 출중할수록 평범한 이들은 당신을 더 비방하고 싶어 할 겁니다.",
  ui_story_5053_50531401_232_dialog_content = "그러니까 솔라드 말 따위 듣지 마세요. 남이 하지 말라고 하면 꼭 하란 말입니다!\n그것이야말로 천재가 세상을 살아가는 방법입니다!",
  ui_story_5053_50531401_233_dialog_content = "처, 천재가 살아가는 방법이요...?\n으엣... 전 주변 사람들의 의견도 들어야 한다고 생각하는걸요...",
  ui_story_5053_50531401_234_dialog_content = "아닙니다, 미아 당신은 이미 오랫동안 사람들에게 억압받아 그렇게 생각하는 겁니다.\n자, 이 외삼촌이 가르쳐 주도록 하죠.",
  ui_story_5053_50531401_235_dialog_content = "이제 모든 힘을 해방시키세요.\n힘이 몸을 지배하도록 해서 자신의 모든 것을 느끼는 겁니다!",
  ui_story_5053_50531401_236_dialog_content = "에엣......?",
  ui_story_5053_50531401_237_dialog_content = "당신처럼 지나치게 조심스러운 사람에겐 극약 처방이 필요합니다.",
  ui_story_5053_50531401_238_dialog_content = "진정으로 자신의 모든 힘을 이해해야만 앞으로 그걸 더 잘 다룰 수 있습니다.",
  ui_story_5053_50531401_239_dialog_content = "모든 힘을 이해...",
  ui_story_5053_50531401_240_dialog_content = "(사람은 미지를 두려워해... 그래서 나도 마찬가지로 두려운 거야.)",
  ui_story_5053_50531401_241_dialog_content = "(외삼촌의 방법은 왠지 너무 자유분방한 것 같지만...\n확실히 나도 내 힘의 깊이를 알 필요가 있어.)",
  ui_story_5053_50531401_242_dialog_content = "걱정 마요, 그리고 제가 있지 않습니까.\n설마 제가 연구만 하는 샌님인 줄 아는 겁니까?",
  ui_story_5053_50531401_243_dialog_content = "그, 그런 생각 안 했어요!\n그럼 외삼촌 말대로... 전력을 다해 볼게요!",
  ui_story_5053_50531401_244_dialog_content = "그래야지요!",
  ui_story_5053_50531401_245_dialog_content = "그렇다면 본격적으로 작전을 개시하죠!",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>크오오──!</color>",
  ui_story_5053_50531501_2_dialog_content = "날카로운 울음소리가 저택에서도 훤히 들려요.",
  ui_story_5053_50531501_3_dialog_content = "폭발이 시작된 지 3분이 지났고... 그 사이 두 색깔의 화염이 공중에서 충돌했어요.",
  ui_story_5053_50531501_4_dialog_content = "파란색은 미아, 빨간색은 드래곤...",
  ui_story_5053_50531501_5_dialog_content = "앗...! 붉은 화염이 떨어졌어요! 칼렙 씨랑 미아가 해냈어요!",
  ui_story_5053_50531501_6_dialog_content = "아무래도 때맞춰 온 모양이로군.",
  ui_story_5053_50531501_7_dialog_content = "네! 안 그래도 가서 알려드리려던 참이었어요.",
  ui_story_5053_50531501_8_dialog_content = "이야기는 다 나누셨나요?",
  ui_story_5053_50531501_9_dialog_content = "그렇다. 이것으로 정세는 완전히 역전되겠지.",
  ui_story_5053_50531501_10_dialog_content = "체스판 위에 외로이 남은 백색의 여왕이여. 그대의 마지막 수는 어디에 둘 생각인가...",
  ui_story_5053_50531501_11_dialog_content = "...왔어...",
  ui_story_5053_50531501_12_dialog_content = "네? 뭐가요?",
  ui_story_5053_50531501_13_dialog_content = "그녀가... 왔어...!",
  ui_story_5053_50531501_14_dialog_content = "지진?! 그리고 이 균열... 「하얀 악마」가 지금 여기로 오는 건가요?!",
  ui_story_5053_50531501_15_dialog_content = "PlayerName!",
  ui_story_5053_50531501_16_dialog_content = "제길, 이게 대체 무슨 일입니까!",
  ui_story_5053_50531501_17_dialog_content = "미아랑 칼렙 씨는 방금 막 드래곤을 해치운 거 아니었어요?\n어떻게 이렇게 빨리 돌아온 거죠?!",
  ui_story_5053_50531501_18_dialog_content = "아니야... 우리도 어떻게 된 건지 모르겠어.",
  ui_story_5053_50531501_19_dialog_content = "드래곤이 쓰러지니까 중앙 광장이 갑자기 뒤틀려서 무너지더니, 나랑 외삼촌만 빼고...",
  ui_story_5053_50531501_20_dialog_content = "주변의 사람들이 전부 흰 빛이 돼서 하늘로 날아가 버렸어.",
  ui_story_5053_50531501_21_dialog_content = "우린 도망치다가 근처 민가의 문을 열고 들어갔는데, 갑자기 저택으로 와버린 거야.",
  ui_story_5053_50531501_22_dialog_content = "후아...",
  ui_story_5053_50531501_23_dialog_content = "쟈키니 씨! 그만 자고 일어나요! 큰일이 났단 말입니다!",
  ui_story_5053_50531501_24_dialog_content = "으응? 어? 누구야! 내 수정 건드리지 마!",
  ui_story_5053_50531501_25_dialog_content = "...어라?! 수, 수정이 왜 이렇게 변한 거지?!",
  ui_story_5053_50531501_26_dialog_content = "아... 어째서...",
  ui_story_5053_50531501_27_dialog_content = "왜 당신들은 그 더럽고 추한 괴물을 선택한 걸까?",
  ui_story_5053_50531501_28_dialog_content = "어머님... 얼굴이...",
  ui_story_5053_50531501_29_dialog_content = "얼굴의 부서진 부분이 「검은 천사」랑 똑같은 색이잖아?!",
  ui_story_5053_50531501_30_dialog_content = "어째서 아무도... 날 선택하지 않은 거야?",
  ui_story_5053_50531501_31_dialog_content = "왜 아무도 「이상」이 얼마나 중요한 것인지 이해하지 못하는 거냐고...",
  ui_story_5053_50531501_32_dialog_content = "<size=45>대체 왜!</size>",
  ui_story_5053_50531501_33_dialog_content = "뭐야?! 이쪽도 「검은 천사」가 돼버렸잖아?!",
  ui_story_5053_50531501_34_dialog_content = "역시 미아 말이 맞았던 모양이네요. 두 인격의 본질은 똑같아요...",
  ui_story_5053_50531501_35_dialog_content = "휴, 안타깝지만 우린 좋게 말로 항복하라고 권할 시간이 없어요!\n수정구슬아!",
  ui_story_5053_50531501_36_dialog_content = "어, 어머님... 미안해요!",
  ui_story_5053_50531501_37_dialog_content = "누나...",
  ui_story_5053_50531501_38_dialog_content = "칼렙, 아직도 망설이고 있는 것인가?",
  ui_story_5053_50531501_39_dialog_content = "그대의 그런 모습은 겁 많은 내 큰딸보다도 못하군.",
  ui_story_5053_50531501_40_dialog_content = "쓸데없는 소리 마세요!\n다른 사람은 몰라도 솔라드 당신만은 누나의 일을 놓고 누굴 탓할 자격이 없단 말입니다!",
  ui_story_5053_50531501_41_dialog_content = "못다 한 말은 나가서 똑똑히 들려줄 테니까 잠자코 기다리기나 하세요!",
  ui_story_5053_50531501_42_dialog_content = "(어리석은 녀석, 이렇게나 시간이 흐르고도 여전히 자극 요법에 약한 것이냐.)",
  ui_story_5053_50531501_43_dialog_content = "......",
  ui_story_5053_50531502_1_dialog_content = "으윽...!",
  ui_story_5053_50531502_2_dialog_content = "쟈키니!",
  ui_story_5053_50531502_3_dialog_content = "네!",
  ui_story_5053_50531502_4_dialog_content = "다가오지 마...",
  ui_story_5053_50531502_5_dialog_content = "포기해요, 누나.",
  ui_story_5053_50531502_6_dialog_content = "오지 말라고...!",
  ui_story_5053_50531502_7_dialog_content = "계속 발버둥 쳐봤자 당신만 더 고통스러워질 뿐이에요!",
  ui_story_5053_50531502_8_dialog_content = "가까이 오지 마!",
  ui_story_5053_50531502_9_dialog_content = "성주님!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>「지배자의 칼날──!」</size>",
  ui_story_5053_50531502_11_dialog_content = "아악!",
  ui_story_5053_50531502_12_dialog_content = "전부... 네 탓이야...",
  ui_story_5053_50531502_13_dialog_content = "......",
  ui_story_5053_50531502_14_dialog_content = "너 때문에... 내 힘이 약해졌다고...",
  ui_story_5053_50531502_15_dialog_content = "미아, 카렌, 칼렙, 블랑... 솔라드.",
  ui_story_5053_50531502_16_dialog_content = "저들은 전부 불량품이고, 배신자야!",
  ui_story_5053_50531502_17_dialog_content = "하지만 넌 그런 저들 때문에 「이상」을 포기했어! 이 부정한 괴물──!",
  ui_story_5053_50531502_18_dialog_content = "미아, 저와 함께 제압합시다. 누나가 계속 자길 해치지 않게 말이에요.",
  ui_story_5053_50531502_19_dialog_content = "네...",
  ui_story_5053_50531502_20_dialog_content = "잠깐! 다가가지 마라!",
  ui_story_5053_50531502_21_dialog_content = "이렇게... 된 이상... 대의를 위해...",
  ui_story_5053_50531502_22_dialog_content = "당신들을 처단하겠어...",
  ui_story_5053_50531502_23_dialog_content = "...응? 바람이 불잖아?",
  ui_story_5053_50531502_24_dialog_content = "...「영원한 기억의 수정」 속 루미나가 전부 「하얀 악마」한테 모이고 있어요!",
  ui_story_5053_50531502_25_dialog_content = "설마... 우리와 함께 죽겠다는 겁니까?!",
  ui_story_5053_50531502_26_dialog_content = "쟈키니, 우릴 내보낼 준비를 해라!\n다른 이들은 함께 그녀를 제압하는 것이다!",
  ui_story_5053_50531502_27_dialog_content = "엣? 지금요?!",
  ui_story_5053_50531502_28_dialog_content = "누나를 저대로 데리고 나갈 생각입니까?!",
  ui_story_5053_50531502_29_dialog_content = "제 손으로 그대들에게 상처를 입히도록 내버려 둔다면,\n조슈아의 마음만 아프게 만들 것이다.",
  ui_story_5053_50531502_30_dialog_content = "이상을 더럽히는 모든 배신자는... 죽어버려!",
  ui_story_5053_50531502_31_dialog_content = "어머님... 대체 왜 이렇게까지 하시는 거죠...?\n어머님은 정말 마음속으로 우릴 그렇게나 증오했던 건가요...?",
  ui_story_5053_50531502_32_dialog_content = "로니... 속상해하지 말렴...",
  ui_story_5053_50531502_33_dialog_content = "나한테... 맡겨...",
  ui_story_5053_50531502_34_dialog_content = "어, 어머님...?",
  ui_story_5053_50531502_35_dialog_content = "쳇, 공격도 먹히질 않습니다! 미아! 멍하니 있지 말고 전투에 전념...",
  ui_story_5053_50531502_36_dialog_content = "...누나? 잠깐만요, 뭘 하려는 겁니까?! 가까이 가지 마세요!",
  ui_story_5053_50531502_37_dialog_content = "...칼렙, 그녀를 믿어라.",
  ui_story_5053_50531502_38_dialog_content = "막지 마! 솔라드! 이거 놓으라고! 누나!!!",
  ui_story_5053_50531502_39_dialog_content = "바람이 너무 세서 눈을 못 뜨겠어요!\n이래서야 「영원한 기억의 수정」을 가동할 수가 없다구요!",
  ui_story_5053_50531502_40_dialog_content = "으아앗?! 나, 나나나, 날아간다아아! 살려줘──",
  ui_story_5053_50531502_41_dialog_content = "쟈키니!",
  ui_story_5053_50531502_42_dialog_content = "휴~ 고마워요, PlayerName 씨... 어라?",
  ui_story_5053_50531502_43_dialog_content = "겁내지 마... 이젠 괜찮아.",
  ui_story_5053_50531502_44_dialog_content = "모두 이번엔 서로 손을 꼭 잡고, 절대 놓지 마.",
  ui_story_5053_50531502_45_dialog_content = "누, 누나...?",
  ui_story_5053_50531502_46_dialog_content = "어머님... 어머님의 얼굴이야...",
  ui_story_5053_50531502_47_dialog_content = "가까이... 오지... 마...",
  ui_story_5053_50531502_48_dialog_content = "자, 소란 그만 피워. 이제 다들 집에 돌려보내 줘야지.",
  ui_story_5053_50531502_49_dialog_content = "가까이... 오지 말라고...!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>조슈아!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "드디어 찾았구나.",
  ui_story_5053_50531601_2_dialog_content = "너...? 다가오지 마!",
  ui_story_5053_50531601_3_dialog_content = "넌 내가 그렇게 싫니?",
  ui_story_5053_50531601_4_dialog_content = "그럼 안 싫겠어? 거울이나 좀 보는 게 어때? 그 추한 몰골을 누가 좋아한다고.",
  ui_story_5053_50531601_5_dialog_content = "그러니... 사실 나도 같은 생각이야.",
  ui_story_5053_50531601_6_dialog_content = "하지만 가족들이나 친구들이 날 저렇게 좋아해 주니까,\n나도 내 이런 모습을 좋아하게 됐어.",
  ui_story_5053_50531601_7_dialog_content = "역겨워...",
  ui_story_5053_50531601_8_dialog_content = "넌 네 모습을 본 적 있니?",
  ui_story_5053_50531601_9_dialog_content = "당연하지. 표정 관리 훈련을 위해 난 매일 세 시간씩 거울을 보며 연습했어.\n이미 지겨울 지경이라고.",
  ui_story_5053_50531601_10_dialog_content = "맞아, 넌 용감한 전사야.\n넌 「이상」을 위해 두려움 없이, 무엇이든 할 수 있어.",
  ui_story_5053_50531601_11_dialog_content = "하지만 넌 틀렸어. 세상엔 언제나 널 두렵게 만드는 게 있기 마련이거든.\n예를 들면...",
  ui_story_5053_50531601_12_dialog_content = "아버지의 죽음.",
  ui_story_5053_50531601_13_dialog_content = "?!",
  ui_story_5053_50531601_14_dialog_content = "또... 아이들과 동생이 진실을 알게 되는 것.",
  ui_story_5053_50531601_15_dialog_content = "헛소리...",
  ui_story_5053_50531601_16_dialog_content = "그리고... 남편과 갈라서는 것.",
  ui_story_5053_50531601_17_dialog_content = "입 닥쳐!",
  ui_story_5053_50531601_18_dialog_content = "그딴 건 너나 두렵겠지... 난 아냐!\n그따위 시시한 감정은 너한테나 있는 거잖아!",
  ui_story_5053_50531601_19_dialog_content = "그런 거... 난 필요 없어...\n난 이상을 위해 내 모든 걸 바칠 거야. 그런 건 필요 없다고!",
  ui_story_5053_50531601_20_dialog_content = "맞아, 넌 정말 순수하게 살았어. 어쩌면 그런 삶은 행복하지 않을지도 몰라.\n하지만 너라면 무언가를 잃더라도 고통스럽진 않겠지.",
  ui_story_5053_50531601_21_dialog_content = "그래서 넌 날 쫓아냈던 거야. 그 고통을 알게 되는 게 두려웠으니까.",
  ui_story_5053_50531601_22_dialog_content = "입 닥쳐... 그만해... 그만하라고...",
  ui_story_5053_50531601_23_dialog_content = "난 저들을 믿지 않아. 저들은 내 말을 듣지 않고, 날 배신할 테니까...",
  ui_story_5053_50531601_24_dialog_content = "사람은 체스말이 아냐. 모든 사람은 자신의 생각을 가지고 있어.",
  ui_story_5053_50531601_25_dialog_content = "「내가 그대를 가로막았던 그날부터 난 끊임없이 생각해 왔어.」",
  ui_story_5053_50531601_26_dialog_content = "「우리가 이렇게 자신의 꿈을 다른 이에게 거는 건 잘못된 선택이 아닐지 말이야.」",
  ui_story_5053_50531601_27_dialog_content = "기억하니? 다니엘이 했던 말이야.",
  ui_story_5053_50531601_28_dialog_content = "그놈은 사기꾼이야...",
  ui_story_5053_50531601_29_dialog_content = "우리가 그에게 너무 의지했던 거야.\n우린 자신이 품고 있던 이상을 그가 대신 짊어지게 만들었어.",
  ui_story_5053_50531601_30_dialog_content = "넌 나보다 더 잘 알고 있었어. 성주 일가의 사람은 평범한 행복을 누릴 수 없다는 걸.\n하지만 난 그 갈망을 내려놓을 수 없었어.",
  ui_story_5053_50531601_31_dialog_content = "무자비한 암살자, 완벽한 공작부인...",
  ui_story_5053_50531601_32_dialog_content = "바뀌어 온 이 신분들은 모두 타인의 부속품이고, 그 어느 것도 진정한 내가 아냐.",
  ui_story_5053_50531601_33_dialog_content = "진정한 나는 대체 어디에 있는 걸까.",
  ui_story_5053_50531601_34_dialog_content = "......",
  ui_story_5053_50531601_35_dialog_content = "하지만 지금 난 눈앞의 소중한 사람들을 잃고 싶지 않아.\n이 느낌은 그 무엇보다도 진실해.",
  ui_story_5053_50531601_36_dialog_content = "그러니까, 이제 그만하고 가자.",
  ui_story_5053_50531601_37_dialog_content = "...아파! 어떻게 된 거야?!\n네 손... 꼭 가시가 자란 것처럼 닿기만 해도 너무 아프다고!",
  ui_story_5053_50531601_38_dialog_content = "하지만... 따뜻하기도 해... 이 느낌... 대체 뭐야?",
  ui_story_5053_50531601_39_dialog_content = "후훗, 그게 바로 <color=#FFB400>사랑</color>인 거야.",
  ui_story_5053_50531601_40_dialog_content = "어머님! 어머님! 어디 계세요?! 콜록... 어머님!",
  ui_story_5053_50531601_41_dialog_content = "미아! 이쪽이야! 내 손 잡아!",
  ui_story_5053_50531601_42_dialog_content = "PlayerName, 다들... 그리고 어머님은 어디 계셔?",
  ui_story_5053_50531601_43_dialog_content = "조슈아 부인은... 아까 폭발 뒤로는 못 봤어...",
  ui_story_5053_50531601_44_dialog_content = "쟈키니, 어서 주문을 외워라.",
  ui_story_5053_50531601_45_dialog_content = "누나가 없으면 난 안 가! 이거 놔!",
  ui_story_5053_50531601_46_dialog_content = "지면이 무너지기 시작했다! 서둘러라!",
  ui_story_5053_50531601_47_dialog_content = "아, 알겠어요!",
  ui_story_5053_50531601_48_dialog_content = "「아드 프라이센스!」",
  ui_story_5053_50531601_49_dialog_content = "우리를 현실 세계로 되돌려 주세요!",
  ui_story_5053_50531601_50_dialog_content = "「아브라카다브라!」",
  ui_story_5053_50531601_51_dialog_content = "누나! 저 여기 있어요! 누나!!",
  ui_story_5053_50531601_52_dialog_content = "고집불통인 녀석... 쟈키니, 미아를 꽉 잡아라!",
  ui_story_5053_50531601_53_dialog_content = "뭐, 뭐라구요?! 바람이 너무 세서 잘 안 들려요!",
  ui_story_5053_50531601_54_dialog_content = "이러다 놓치겠어! PlayerName!",
  ui_story_5053_50531601_55_dialog_content = "으아악!",
  ui_story_5053_50531601_56_dialog_content = "꽉 잡으렴.",
  ui_story_5053_50531601_57_dialog_content = "당신은...?",
  ui_story_5053_50531601_58_dialog_content = "「......, 이렇게 편지로 인사를 대신합니다.」",
  ui_story_5053_50531601_59_dialog_content = "「요즘 잘 지내시나요? 이쪽은 저도 다른 사람들도 다 잘 지내고 있어요.」",
  ui_story_5053_50531601_60_dialog_content = "지금 편지 써요? 누구한테 쓰는 거예요?",
  ui_story_5053_50531601_61_dialog_content = "으아앗?! 쟈키니... 깜짝 놀랐잖아...",
  ui_story_5053_50531601_62_dialog_content = "헤헷, 미안해요~",
  ui_story_5053_50531601_63_dialog_content = "PlayerName, 안녕.",
  ui_story_5053_50531601_64_dialog_content = "안녕! 진짜 일찍 도착했네? 쟈키니가 또 늦을 줄 알았는데 말이야.",
  ui_story_5053_50531601_65_dialog_content = "그게 다 제 전문 지식이 그만큼 중요한 탓인 걸 어떡하겠어요!\n매일 같이 사람들이 줄을 서서 질문을 하니까 너무 바쁘다구요~",
  ui_story_5053_50531601_66_dialog_content = "아, 예예, 그렇고 말고요, 「여명 아카데미 임시 고문」 쟈키니 씨.",
  ui_story_5053_50531601_67_dialog_content = "헤헷, 그렇게 격식을 차리면 좀 쑥스러운데 말이죠...",
  ui_story_5053_50531601_68_dialog_content = "미아, 일은 다 잘 끝낸 거야?",
  ui_story_5053_50531601_69_dialog_content = "응, 다 끝났어.",
  ui_story_5053_50531601_70_dialog_content = "아쉽지만 카렌은 너무 바빠서 작별 인사를 할 기회가 없었어...",
  ui_story_5053_50531601_71_dialog_content = "걱정 마. 다음에 카렌이 콜로서스에 놀러 오면 너한테도 말해줄게.\n꼭 둘이 만나게 해줄 테니까.",
  ui_story_5053_50531601_72_dialog_content = "아니야, 그냥 때가 돼서 자연스럽게 만나는 게 좋을 것 같아.",
  ui_story_5053_50531601_73_dialog_content = "그런가...",
  ui_story_5053_50531601_74_dialog_content = "「그 뒤로 이곳엔 많은 일들이 있었고, 많은 사람들이 예상밖의 결정을 내렸어요.」",
  ui_story_5053_50531601_75_dialog_content = "「자초지종을 전부 전해드리겠다고 약속했으니까, 그럼 맨 처음부터 말씀드릴게요.」",
  ui_story_5053_50531601_76_dialog_content = "「그때 우린 마침내 <color=#FFB400>『영원한 기억의 수정』</color>에서 무사히 빠져나올 수 있었어요.」",
  ui_story_5053_50531601_77_dialog_content = "「칼렙 씨는 자기 몸 상태를 확인할 새도 없이 방문을 뛰쳐나가 집으로 돌아갔죠.」",
  ui_story_5053_50531601_78_dialog_content = "「그리고 우리도 칼렙 씨를 따라갔고...\n칼렙 씨가 줄곧 집에 숨겨 두었던 조슈아 부인을 만났어요.」",
  ui_story_5053_50531601_79_dialog_content = "어머님의 눈이 살짝 움직였어...!",
  ui_story_5053_50531601_80_dialog_content = "빨리 약을 가져오세요! 왼쪽 선반이요!",
  ui_story_5053_50531601_81_dialog_content = "잠깐만요! 아직 거즈를 못 찾았어요!",
  ui_story_5053_50531601_82_dialog_content = "내가 하지.",
  ui_story_5053_50531601_83_dialog_content = "「응급 처치 끝에 조슈아 부인은 무사히 위험을 피할 수 있었고,\n며칠 뒤에 깨어났어요.」",
  ui_story_5053_50531601_84_dialog_content = "「하지만... 부인은 모든 기억을 잃었어요.」",
  ui_story_5053_50531601_85_dialog_content = "대체 왜 이렇게 된 겁니까? 장기간의 수면 때문입니까? 아니면 그 마지막 폭발 때문에?",
  ui_story_5053_50531601_86_dialog_content = "하지만 누나한테서 인격 분열의 증세가 완전히 사라졌어요. 도대체 무슨...",
  ui_story_5053_50531601_87_dialog_content = "쟈키니 씨, 설마 이것도 「영원한 기억의 수정」과 관련이 있는 겁니까?",
  ui_story_5053_50531601_88_dialog_content = "으음~ 아마 그럴 리는 없을걸요.",
  ui_story_5053_50531601_89_dialog_content = "「아마 그럴 리가 없는」 건 또 뭡니까? 좀 진지하게 굴 순 없습니까?",
  ui_story_5053_50531601_90_dialog_content = "「조슈아 부인을 돕고, 『영원한 기억의 수정』을 고치기 위해...」",
  ui_story_5053_50531601_91_dialog_content = "「쟈키니는 잠시 백야성에 머물면서 칼렙 씨와 함께 연구를 진행했어요.」",
  ui_story_5053_50531601_92_dialog_content = "「쟈키니를 기분 좋게 해 주려고 칼렙 씨는 쟈키니한테\n『여명 아카데미 임시 고문』이라는 직함도 줬어요.」",
  ui_story_5053_50531601_93_dialog_content = "「근데 들어보니까 그 직함은 사실 아무 의미도 없는 거라고 하더라구요.\n쟈키니가 그 사실을 몰라야 할 텐데 말이죠...」",
  ui_story_5053_50531601_94_dialog_content = "이제 우리가 아는 유일한 사실은 「하얀 악마」와 「검은 천사」가\n결국 모종의 이유로 서로를 받아들이게 됐다는 거예요.",
  ui_story_5053_50531601_94X1_dialog_content = "이중인격은 사라졌고, 조슈아 부인의 정신도 다시 정상으로 돌아왔어요.",
  ui_story_5053_50531601_95_dialog_content = "「씨앗」에 대한 문제는 아직 여러 측면에서 심층 연구가 필요해요.\n이 부분은 칼렙 씨한테 의존하는 수밖에 없어요.",
  ui_story_5053_50531601_96_dialog_content = "수고가 많았다, 북방의 사절 쟈키니여.\n며칠간 백야성에 머물면서 칼렙의 연구를 도운 데 감사의 뜻을 표하도록 하지.",
  ui_story_5053_50531601_97_dialog_content = "당연히 해야 할 일인걸요~ 다들 같이 죽다 살았는데 저도 이젠 남이 아니잖아요!",
  ui_story_5053_50531601_98_dialog_content = "게다가 애초에 「영원한 기억의 수정」에 거울 호수의 물을 보충하러 온 거면서,\n오히려 수정을 망가트렸다는 말을 어디 가서 하겠어요...",
  ui_story_5053_50531601_99_dialog_content = "아, 참, 「영원한 기억의 수정」은 이미 고쳤어요!\n이제 조슈아 부인도 돌아오셨으니까 진짜로 아무 때나 쓰셔도 돼요!",
  ui_story_5053_50531601_100_dialog_content = "고맙군, 이제는 다른 이가 실수로 들어가는 일이 없도록 잘 보관할 것이다.",
  ui_story_5053_50531601_101_dialog_content = "아하하... 그나저나, 사실 전 칼렙 씨가 좀 걱정되는데 말이죠.\n조슈아 부인이 깨어난 뒤부터 매일 부인 곁에만 있었잖아요!",
  ui_story_5053_50531601_102_dialog_content = "게다가 여명 아카데미의 직위도 버리고 집에서 부인만 돌보고 싶다고 했다면서요?\n어휴, 진짜 그래도 되는 건가요?",
  ui_story_5053_50531601_103_dialog_content = "철딱서니 없는 녀석...\n그러고 보니 그대가 「시로나」라는 기사를 찾는다고 하던데, 그게 사실인가?",
  ui_story_5053_50531601_104_dialog_content = "맞아요! 역시 성주님은 소식도 참 빠르시네요!\n그럼 혹시 저 좀 그 사람한테 소개시켜 주실 수 있나요?",
  ui_story_5053_50531601_105_dialog_content = "유감스럽게도 그 바람은 이루어 줄 수 없을 듯하군.\n시로나는 이미 백야성을 떠났다.",
  ui_story_5053_50531601_106_dialog_content = "네에? 하지만 그 사람 분명히 최고의 기사가 되겠다고 했단 말이에요...",
  ui_story_5053_50531601_107_dialog_content = "일루미나 연방에 가서 찾아보면 될 것이다.\n허나 그녀 앞에서 백야성에 대한 이야기는 결코 꺼내지 마라.",
  ui_story_5053_50531601_108_dialog_content = "「영원한 기억의 수정」 안에서 발생한 모든 일들은 진실이 아니라는 것을 잊지 말도록.\n아무리 그녀와 깊은 인연을 맺었다 한들...",
  ui_story_5053_50531601_109_dialog_content = "그것도 긴 꿈이었을 뿐이다.\n12년이 지났고, 이제는 모든 것이 달라졌으니 말이야.",
  ui_story_5053_50531601_110_dialog_content = "그런가요... 그래도 괜찮아요!\n서로의 초심이 변하지 않았다면, 우린 반드시 친구가 될 수 있을 거예요!",
  ui_story_5053_50531601_111_dialog_content = "「초심이 변하지 않는다」라, 일리가 있군.",
  ui_story_5053_50531601_112_dialog_content = "「전 부인의 기억 상실이 가족을 다시 슬픔에 빠트릴 줄 알았어요.」",
  ui_story_5053_50531601_113_dialog_content = "「근데 제 예상과 다르게 아무도 그 일로 낙담하지 않았어요.\n비록 잠시 실의에 빠지긴 했었지만, 금방 다시 재회의 기쁨에 젖었죠.」",
  ui_story_5053_50531601_114_dialog_content = "「그저 가족들이 무사하고 건강하면 그걸로 충분하다면서요...\n정말 순수하고 아름다운 감정인 것 같아요.」",
  ui_story_5053_50531601_115_dialog_content = "「하지만 <color=#FFB400>성주 일가</color>라는 너무나도 눈부신 신분은,\n저들이 그런 평범한 행복을 누릴 수 없게 했어요.」",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>칼렙 마그누스 경의 저택</color>",
  ui_story_5053_50531601_117_dialog_content = "누나, 저 왔어요! 보세요, 이건 움브라톤에서 새로 나온 과일 맛 홍차예요!\n누나가 분명히 좋아할 것 같아서 사 왔어요!",
  ui_story_5053_50531601_118_dialog_content = "다녀오셨어요, 외삼촌?",
  ui_story_5053_50531601_119_dialog_content = "어서 와... 어머, 오늘 평일 맞지? 칼렙, 너 출근 안 하니?",
  ui_story_5053_50531601_120_dialog_content = "일이 누나보다 중요하겠어요? 이미 여명 아카데미에 사표도 냈어요.\n앞으로 계속 누나 곁에 있을 거예요.",
  ui_story_5053_50531601_121_dialog_content = "세상에, 사표?\n고작 내가 나타났다고 지금 네 사명과 이상을 포기하려는 거야?",
  ui_story_5053_50531601_122_dialog_content = "누나, 그런 말 하지 마세요.\n가족이 함께 행복하게 사는 것보다 더 중요한 게 어딨겠어요.",
  ui_story_5053_50531601_123_dialog_content = "미아도 쭉 백야성으로 돌아와서 가족들과 만나고 싶어 했잖아요. 안 그래요?",
  ui_story_5053_50531601_124_dialog_content = "저기, 사실... 오늘은 안 그래도 어머님께 그 일에 대해 말씀드리러 왔어요.\n전 앞으로도 계속 움브라톤에서 지내고 싶어요.",
  ui_story_5053_50531601_125_dialog_content = "뭐라고요...? 미아, 갑자기 왜 그러는 겁니까?\n설마 솔라드가 또 당신을 괴롭혔습니까?!",
  ui_story_5053_50531601_126_dialog_content = "아니에요! 이건 제 생각이고, 아버님도 제 결정을 지지해 주셨어요.",
  ui_story_5053_50531601_127_dialog_content = "과거의 전 나약하고 힘이 없어서 어머님을 떠나보내고 큰 고통을 겪었어요...",
  ui_story_5053_50531601_128_dialog_content = "대신 그 덕에 어려움을 직시하면서 백야성 바깥의 세상을 볼 수 있었고,\n지금의 저로 성장했어요. 하지만 이것만으로는 아직 부족해요.",
  ui_story_5053_50531601_129_dialog_content = "외삼촌도 아시겠지만, 외삼촌은 최근에 휴가를 자주 내셨고,\n저도 베일을 쓰고 이 집을 드나들면서, 이미 하이가든엔 소문이 퍼지기 시작했어요.",
  ui_story_5053_50531601_130_dialog_content = "게다가 아버님은 그 때문에 어머님을 보러 오실 수도 없었죠...\n이미 우린 어머님을 숨겨버렸는데도 말이에요.",
  ui_story_5053_50531601_131_dialog_content = "알고 있습니다! 그 문제는 저도 열심히 방법을 찾고 있단 말입니다.\n그리고 어차피 백야성을 떠나서 살면 그만이지 않습니까!",
  ui_story_5053_50531601_132_dialog_content = "성주의 부인이 몇 년 만에 살아난 게 뭐가 어쨌다고...",
  ui_story_5053_50531601_133_dialog_content = "솔라드를 쓰러트리고 싶으면 실력으로 덤비라고들 하세요!\n정치 스캔들 같은 상스러운 수법이나 쓰는 게 뭐가 그리 재미있답니까?!",
  ui_story_5053_50531601_134_dialog_content = "네, 저도 이해해요. 이 모든 건 우리 가족의 잘못이 아니에요.\n하지만 우리 가족이 감당해야 할 문제이기도 해요.",
  ui_story_5053_50531601_135_dialog_content = "전 이제서야 아버님을 이해하기 시작했어요...\n그러니까 이제 더는 어머님의 품에 연연해하지 않을래요.",
  ui_story_5053_50531601_136_dialog_content = "백야성의 빛 아래 살아갈 수 없는 이상, 전 모두의 「그림자」가 되고 싶어요.",
  ui_story_5053_50531601_137_dialog_content = "전 움브라톤에서 이스타반 어르신을 따라 열심히 공부해서,\n더는 보호받는 약자가 아닌 강인한 기사가 될 거예요.",
  ui_story_5053_50531601_138_dialog_content = "앞으로는 제가 모두를 지키겠어요...!",
  ui_story_5053_50531601_139_dialog_content = "왜 그런 생각을 하는 거죠? 설마 이 외삼촌은 믿고 의지할 수 없다는 겁니까?\n누나도 가만히 있지 말고 좀 말려 보세요.",
  ui_story_5053_50531601_140_dialog_content = "칼렙, 난 <color=#FFB400>기억이 없는 사람</color>이야.\n난 과거가 없으니까, 과거에 연연하지도 않아.",
  ui_story_5053_50531601_141_dialog_content = "난 미아가 자신의 꿈을 찾을 수 있어서 기뻐.\n아가야, 열심히 노력하렴. 난 네가 반드시 멋진 미래를 손에 넣을 거라고 믿어.",
  ui_story_5053_50531601_142_dialog_content = "어머님... 고마워요.",
  ui_story_5053_50531601_143_dialog_content = "그러고 보면 미아 너도 날 일깨워 줬는걸.\n바깥엔 저렇게나 멋진 게 많은 세상이 있는데, 나도 한번 가서 봐야 하지 않겠니?",
  ui_story_5053_50531601_144_dialog_content = "잠깐만요... 누나, 지금 그게 무슨 말이에요...?",
  ui_story_5053_50531601_145_dialog_content = "「맞아요, 이런 일들을 겪고 나서, 미아는 결국 떠나기로 결심했어요.」",
  ui_story_5053_50531601_146_dialog_content = "「이건 미아가 성장해서 스스로 내린 결정이에요. 전 진심으로 기쁘게 생각해요.」",
  ui_story_5053_50531601_147_dialog_content = "「그리고 칼렙 씨의 사직 신청도 반려됐어요.」",
  ui_story_5053_50531601_148_dialog_content = "「왠지 평소에도 이런저런 이유로 충동적으로 사표를 냈던 것 같더라고요.\n아카데미에서도 익숙한 일이었는지 평소대로 반려했다고 해요.」",
  ui_story_5053_50531601_149_dialog_content = "「그리고 조슈아 부인도 이번 일에 영감을 받아 자신만의 생각이 생긴 것 같았어요.」",
  ui_story_5053_50531601_150_dialog_content = "「부인은 사람들 몰래 백야성을 떠나 혼자 여행을 떠나기로 결정했거든요.」",
  ui_story_5053_50531601_151_dialog_content = "고마워, PlayerName. 콜로서스로 몰래 데려다준다고 고생했어.",
  ui_story_5053_50531601_152_dialog_content = "별일 아닌걸요. 근데 왜 모두한테 작별 인사도 안 하고 떠나시는 건가요?",
  ui_story_5053_50531601_153_dialog_content = "바보야, 내가 떠나려는 걸 알면 다들 쉽게 동의하지 않을 거잖니.",
  ui_story_5053_50531601_154_dialog_content = "하지만 난 반드시 떠나야 해, 이건 저들을 지키기 위해서일 뿐만 아니라,\n어머니이자 누나로서 저들에게 가르쳐 줘야 할 마지막 교훈이거든.",
  ui_story_5053_50531601_155_dialog_content = "...조슈아 씨, 정말 기억을 잃으신 게 맞나요?",
  ui_story_5053_50531601_156_dialog_content = "후훗, 당연하지.\n너 혹시라도 아이테르의 능력으로 숙녀의 비밀을 몰래 훔쳐보면 안 된다?",
  ui_story_5053_50531601_157_dialog_content = "아, 알겠어요... 그럼 돌아가서 조슈아 씨가 떠나셨다는 소식만 전할게요...\n이렇게 하면 군주를 속인 죄는 아니게 되는 거죠?",
  ui_story_5053_50531601_158_dialog_content = "후훗, 아마 그래도 맞을 것 같은데.",
  ui_story_5053_50531601_159_dialog_content = "네에?!",
  ui_story_5053_50531601_160_dialog_content = "농담이야~ 다니엘은 아마 진작에 내 생각을 알아챘을 거야.\n우리 사이엔 많은 말이 필요하지 않거든.",
  ui_story_5053_50531601_161_dialog_content = "그리고 카렌은... 다니엘과 너무 닮았어.\n넌 그 아이와도 친하다고 들었는데, 그럼 너도 이해할 수 있겠지?",
  ui_story_5053_50531601_162_dialog_content = "그 아이는 강인하고 유능해 보이지만, 실제로는 항상 억지로 버티고 있어.\n그래서 다들 약속이라도 한 것처럼 그 애에겐 침묵을 지켰던 거야.",
  ui_story_5053_50531601_163_dialog_content = "카렌의 능력이라면, 자신이 알고 싶은 진실은 반드시 직접 찾을 수 있을 거야.\n만약 못 찾는다면...",
  ui_story_5053_50531601_164_dialog_content = "그건 분명히 그 아이가 아직 그 진실을 받아들일 준비가 되지 않았기 때문일 거야.",
  ui_story_5053_50531601_165_dialog_content = "...후훗, 이렇게 뭐든 다 안다는 듯이 고고하게 말하고 있지만,\n사실 내 마음속에도 엄청난 그늘이 숨겨져 있단다.",
  ui_story_5053_50531601_166_dialog_content = "만약 「씨앗」이 심어지지 않았다면, 아마 난 평생 깨닫지 못했을 거야.\n사실 나도 남몰래 포악한 모습을 억누르고 있었다는 걸 말이야.",
  ui_story_5053_50531601_167_dialog_content = "조슈아 씨...",
  ui_story_5053_50531601_168_dialog_content = "전 서로를 따스하게 감싸주는 것 말고도, 엄하게 타이르는 것도\n가족끼리 관심을 기울이는 방법이라고 생각해요. 맞죠?",
  ui_story_5053_50531601_169_dialog_content = "맞아, 따스한 항구가 때로는 바다로 나아가는 발걸음을 붙잡고 마는 법이거든.",
  ui_story_5053_50531601_170_dialog_content = "지금의 카렌에겐 우리 가족들보다는 믿음직한 오른팔,\n그리고 그 애와 뜻을 함께하는 친구가 더 필요해.",
  ui_story_5053_50531601_171_dialog_content = "그래서 말인데, PlayerName, 카렌과 계속 함께 성장해 달라고 부탁해도 될까?",
  ui_story_5053_50531601_X171_option_content = "네! 물론이죠!",
  ui_story_5053_50531601_X172_option_content = "제, 제가요...?",
  ui_story_5053_50531601_X173_dialog_content = "우리 오로리안과는 전혀 다른 종족, 마지막 아이테르인 네게서\n난 미래의 빛을 볼 수 있었어.",
  ui_story_5053_50531601_X174_dialog_content = "그건 백야성이라는 닫힌 환경에서는 영원히 볼 수 없는 보물이란다.",
  ui_story_5053_50531601_X175_dialog_content = "난 네가 반드시 카렌... 아니, 더 많은 사람들을 다른 내일로 인도할 수 있을 거라 믿어.",
  ui_story_5053_50531601_X176_dialog_content = "네 존재, 그리고 미아의 용기는 내게 바깥세상에 숨겨진 가능성을 보여줬어.",
  ui_story_5053_50531601_X177_dialog_content = "어쩌면 더 넓은 세상을 보고 겪은 뒤엔,\n나도 내가 진정으로 원하는 걸 찾을 수 있을지도 몰라.",
  ui_story_5053_50531601_X178_dialog_content = "언젠간 그 소중한 깨달음을 가지고 내가 사랑하는 사람 곁으로 돌아올게.",
  ui_story_5053_50531601_X179_dialog_content = "「그래서 그날 저는 조용히 당신과 헤어지고, 당신이 떠났다는 소식을 백야성에 전했어요.」",
  ui_story_5053_50531601_X180_dialog_content = "「누군가는 미소를 지으며 담담하게 축복을 전했고,\n누군가는 깜짝 놀랐지만 흔쾌히 받아들였어요.」",
  ui_story_5053_50531601_X181_dialog_content = "「누군가는 이해할 수 없어 문을 박차고 나갔고,\n누군가는 이미 이 결말을 예상한 것 같았어요.」",
  ui_story_5053_50531601_X182_dialog_content = "「그렇게 우여곡절 끝에, 모두 이 결말을 받아들였어요.\n이제 더는 기억을 잃은 사람이 새로운 인생을 시작하는 걸 막지 않기로 했어요.」",
  ui_story_5053_50531601_X183_dialog_content = "「저랑 몰래 편지로 연락하고 있다는 건 다른 사람들에게 반드시 비밀로 할게요.」",
  ui_story_5053_50531601_X184_dialog_content = "「그리고 저도 약속대로 수시로 가족들의 근황을 보고드릴게요.」",
  ui_story_5053_50531601_172_dialog_content = "「부디 다음에 만날 때는 각자 여행자라는 신분으로 서로 겪었던\n재미있는 이야기들을 나눌 수 있길 바랄게요.」",
  ui_story_5053_50531601_173_dialog_content = "PlayerName 씨──! 그만 좀 써요!",
  ui_story_5053_50531601_174_dialog_content = "으앗?! 휴, 쟈키니... 왜 또 놀래키는 건데?",
  ui_story_5053_50531601_175_dialog_content = "이번엔 제 탓하면 안 되죠! 그러게 누가 계속 말도 없이 편지만 쓰래요?\n미아 씨랑 같이 저 북방으로 데려다준다고 했었잖아요!",
  ui_story_5053_50531601_176_dialog_content = "자, 잠깐만... 나 쿠리어한테 우편배달 예약했거든. 이제 금방 올 거야.",
  ui_story_5053_50531601_177_dialog_content = "쟈키니가 제시간에 올 줄은 정말 몰랐다고...",
  ui_story_5053_50531601_178_dialog_content = "앗! 다 들었거든요!",
  ui_story_5053_50531601_179_dialog_content = "헤헤, 그럼 이렇게 된 이상 우리도 조금만 더 기다리자.",
  ui_story_5053_50531601_180_dialog_content = "참, PlayerName, 혹시 엽서 받았어?",
  ui_story_5053_50531601_181_dialog_content = "엽서?",
  ui_story_5053_50531601_182_dialog_content = "아, 조슈아 부인이 보낸 엽서 말이죠? 잘 받았어요!",
  ui_story_5053_50531601_183_dialog_content = "부인은 어느 외진 마을에 도착했는데, 말을 하는 새를 만났대요!",
  ui_story_5053_50531601_184_dialog_content = "음... 아마 아인족 같은 게 아닐까?\n어머님은 둘이 잘 맞아서 마음을 털어놓는 친구가 되셨대. 정말 잘됐네.",
  ui_story_5053_50531601_185_dialog_content = "어? 뭐야, 그럼 나만 못 받은 거야...?",
  ui_story_5053_50531601_186_dialog_content = "PlayerName 씨는 아무래도 우리보다 우선순위에서 좀 밀리는 모양인데요?",
  ui_story_5053_50531601_187_dialog_content = "배, 배달이 늦는 거겠지! 분명히 나한테도 곧 올 거라고!",
  ui_story_5053_50531601_188_dialog_content = "문 열어요! 쿠리어 에호가 배달 왔어요!",
  ui_story_5053_50531601_189_dialog_content = "우와, 진짜 말하니까 바로 오네요.",
  ui_story_5053_50531601_190_dialog_content = "자! 편지는 여기 있어, 그럼 잘 부탁할게.",
  ui_story_5053_50531601_191_dialog_content = "네, 잘 받았어요. 그리고 이건 당신한테 온 거예요.",
  ui_story_5053_50531601_192_dialog_content = "나한테? 앗... 이건!",
  ui_story_5053_50531601_193_dialog_content = "뭔데요? 뭐 재밌는 건가요?",
  ui_story_5053_50531601_194_dialog_content = "왜 그래? PlayerName.",
  ui_story_5053_50531601_195_dialog_content = "PlayerName, 우리도 같이 보면 안 돼요?",
  ui_story_5053_50531601_196_dialog_content = "으아아앗! 미안! 이건 못 보여줘!",
  ui_story_5053_50531601_197_dialog_content = "「친애하는 PlayerName, 잘 지내고 있니?」",
  ui_story_5053_50531601_198_dialog_content = "「난 지금 여행길에 올랐어...」",
  ui_story_5053_50531601_199_dialog_content = "장미 한 송이를♪ 귀여운 우리 아이에게 선물하자~♪",
  ui_story_5053_50531601_200_dialog_content = "산들바람이 그 뺨을 어루만지고, 네 웃는 얼굴은 세상에 하나뿐인 보물~♪",
  ui_story_5053_50531601_201_dialog_content = "장미 한 송이를♪ 소중한 아빠와 엄마에게 선물하자~♪",
  ui_story_5053_50531601_202_dialog_content = "무슨 일이 있어도, 우린 영원히 서로의 사랑이야~♪"
}
